   101→        };
   102→
   103→        // Spawn periodic flush timer - saves dirty layers every 10 seconds
   104→        // This prevents blocking the actor on every single operation
   105→        let myself_clone = myself.clone();
   106→        tokio::spawn(async move {
   107→            let mut flush_interval = interval(Duration::from_secs(10));
   108→            loop {
   109→                flush_interval.tick().await;
   110→                let _ = myself_clone.cast(ScribeMessage::Flush);
   111→            }
   112→        });
   113→
   114→        // Spawn periodic reconciliation timer - catches missed syncs every 30 seconds
   115→        // Only for Node mode (Broadcast) - User mode (ToSource) relies on Node to initiate sync
   116→        // This prevents bilateral reconciliation attempts that can cause sync storms
   117→        let is_user_mode = args.sync_config.as_ref().map(|c| c.mode) == Some(SyncMode::ToSource);
   118→        if !is_user_mode {
   119→            let myself_reconcile = myself.clone();
   120→            tokio::spawn(async move {
   121→                let mut reconcile_interval = interval(Duration::from_secs(30));
   122→                loop {
   123→                    reconcile_interval.tick().await;
   124→                    let _ = myself_reconcile.cast(ScribeMessage::ReconcileWithPeers);
   125→                }
   126→            });
   127→        }
   128→
   129→        let mut state = ScribeState {
   130→            page_id: args.page_id,
   131→            layers: args.layers,
   132→            subscribers: Arc::new(std::sync::RwLock::new(HashMap::new())),
   133→            local_only_layers: Arc::new(std::sync::RwLock::new(HashSet::new())),
   134→            query_subscribers: HashMap::new(),
   135→            dirty_layers: HashSet::new(),
   136→            // Storage traits
   137→            layer_storage: args.layer_storage,
   138→            vector_storage: args.vector_storage,
   139→            peer_resolver: args.peer_resolver,
   140→            permit_issuer: args.permit_issuer,
   141→            // Sync configuration
   142→            sync_config: args.sync_config,
   143→            sync_event_tx: args.sync_event_tx,
   144→            loro_subscriptions: HashMap::new(),
   145→            page_update_subscribers: Arc::new(std::sync::RwLock::new(Vec::new())),
   146→            pending_update_source: Arc::new(Mutex::new(None)),
   147→            validation_handle: args.validation_handle,
   148→            our_permit,
   149→            our_did: args.our_did.clone(),
   150→            node_script_shutdown: None,
   151→        };
   152→
   153→        // Pre-create static layers from permit (already extracted via PermitContext)
   154→        // Static layers are fully known after expanding {page_id} and {aud}
   155→        // Dynamic layers (with wildcards) are created on-demand during sync
   156→        for layer_name in static_layers {
   157→            if !state.layers.contains_key(&layer_name) {
   158→                info!(
   159→                    page_id = %state.page_id,
   160→                    layer = %layer_name,
   161→                    "Pre-creating static layer from permit"
   162→                );
   163→                state.layers.insert(layer_name, Layer::new());
   164→            }
   165→        }
   166→
   167→        // Update local_only_layers based on permit before setting up observers
   168→        state.update_local_only_layers();
   169→
   170→        // Set up Loro observers for all layers (including pre-created ones)
   171→        // This ensures import() triggers broadcasts via observer pattern
   172→        loro_observer::setup_observers_for_all_layers(&mut state);
   173→
   174→        // Emit EnsureSync on page open to trigger remote subscription
   175→        // Flow: EnsureSync → Coordinator → (connect if needed) → RefreshSubscriptions → remote subscribes
   176→        // Works for both ToSource mode (single sync_target) and Broadcast mode (all authorized users)
   177→        if let Some(ref tx) = state.sync_event_tx {
   178→            let sync_targets = sync::reconcile::get_sync_targets(&state);
   179→            if sync_targets.is_empty() {
   180→                debug!(page_id = %state.page_id, "No sync targets on page open");
   181→            } else {
   182→                info!(page_id = %state.page_id, targets = ?sync_targets, "Emitting EnsureSync for {} targets on page open", sync_targets.len());
   183→                for user_did in sync_targets {
   184→                    let event = message::SyncEvent::EnsureSync {
   185→                        user_did: user_did.clone(),
   186→                    };
   187→                    match tx.try_send(event) {
   188→                        Ok(()) => info!(user_did = %user_did, page_id = %state.page_id, "Emitted EnsureSync on page open"),
   189→                        Err(e) => warn!(user_did = %user_did, error = %e, "Failed to emit EnsureSync on page open"),
   190→                    }
   191→                }
   192→            }
   193→        }
   194→
   195→        // Note: Node script spawning is handled by the caller (e.g., kunki's NodeRuntimeManager)
   196→        // This keeps the Scribe actor storage-agnostic and focused on CRDT sync
   197→
   198→        Ok(state)
   199→    }
   200→
   201→    #[instrument(skip_all, fields(page_id = %state.page_id))]
   202→    async fn handle(
   203→        &self,
   204→        myself: ActorRef<Self::Msg>,
   205→        message: Self::Msg,
   206→        state: &mut Self::State,
   207→    ) -> std::result::Result<(), ActorProcessingErr> {
   208→        match message {
   209→            ScribeMessage::Subscribe {
   210→                user_did,
   211→                device_id,
   212→                broadcast_tx,
   213→                ephemeral_tx,
   214→                permit,
   215→            } => {
   216→                sync::handle_subscribe(state, user_did, device_id, broadcast_tx, ephemeral_tx, permit).await;
   217→            }
   218→
   219→            ScribeMessage::Unsubscribe { user_did, device_id } => {
   220→                sync::handle_unsubscribe(state, &user_did, &device_id).await;
   221→            }
   222→
   223→            ScribeMessage::SubscribeToPageUpdates { tx } => {
   224→                // Send PeerSubscribed for all currently subscribed peers
   225→                // (peers that subscribed before this app opened)
   226→                if let Ok(subs) = state.subscribers.read() {
   227→                    info!(page_id = %state.page_id, peer_count = subs.len(), "Sending existing peers as PeerSubscribed");
   228→                    for ((user_did, _device_id), _info) in subs.iter() {
   229→                        let _ = tx.try_send(message::PageUpdate::PeerSubscribed {
   230→                            did: user_did.clone(),
   231→                            username: None,
   232→                        });
   233→                    }
   234→                }
   235→
   236→                // Presence state is delivered via CRDT sync (presence layer snapshot)
   237→                // No need to send OnlinePeers event — apps read from LayerChanged on {page_id}/presence
   238→
   239→                if let Ok(mut subs) = state.page_update_subscribers.write() {
   240→                    subs.push(tx);
   241→                    info!(page_id = %state.page_id, subscriber_count = subs.len(), "PageUpdate subscriber added");
   242→                }
   243→            }
   244→
   245→            ScribeMessage::ApplyUpdate {
   246→                layer_name,
   247→                update,
   248→                from_peer,
   249→                permit,
   250→            } => {
   251→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
   252→                // Loro observer handles broadcast automatically after import()
   253→                let _ = sync::handle_apply_update(
   254→                    state,
   255→                    &layer_name,
   256→                    &update,
   257→                    from_peer,
   258→                    permit.as_deref(),
   259→                )
   260→                .await;
   261→            }
   262→
   263→            ScribeMessage::ApplyUpdateWithResult {
   264→                layer_name,
   265→                update,
