   273→                    state,
   274→                    &layer_name,
   275→                    &update,
   276→                    from_peer,
   277→                    permit.as_deref(),
   278→                )
   279→                .await;
   280→                let _ = reply.send(result);
   281→            }
   282→
   283→            ScribeMessage::SyncRequest {
