   330→                    Err(e) => {
   331→                        error!(layer = %layer_name, error = %e, "Failed to parse snapshot for layer replacement");
   332→                        Err(format!("Failed to parse snapshot: {}", e))
   333→                    }
   334→                };
   335→                let _ = reply.send(result);
   336→            }
