   341→
   342→            ScribeMessage::EnsureLoroList { layer_name, reply } => {
   343→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
   344→                // Get existing layer or create new one (for list access)
   345→                let is_new_layer = !state.layers.contains_key(&layer_name);
   346→                if is_new_layer {
   347→                    state.layers.insert(layer_name.clone(), Layer::new());
   348→                    state.dirty_layers.insert(layer_name.clone());
   349→                    debug!(layer = %layer_name, "Created new layer for Lua list");
   350→                    // Check if layer is local-only (sync: false in permit)
   351→                    state.mark_layer_local_only_if_needed(&layer_name);
   352→                    // Set up Loro observer for new layer to enable sync broadcasts
   353→                    loro_observer::setup_layer_observer(state, &layer_name);
   354→                    // Notify UI subscribers about the new layer
   355→                    sync::notify_layer_discovered(state, &layer_name);
   356→                }
   357→                // Just confirm the layer exists, don't return handle
   358→                let _ = reply.send(Ok(()));
   359→            }
