   384→            // Typed read operations (for Lua bindings - avoids stale handles)
   385→
   386→            ScribeMessage::ListGet { layer_name, index, reply } => {
   387→                let layer_name = normalize_layer_name(&layer_name, &state.page_id);
   388→                let result = state.layers.get(&layer_name)
