   616→            // Ephemeral events (from datagrams via PeerActor)
   617→            ScribeMessage::RemoteEphemeral { user_did, device_id, payload } => {
   618→                // Log payload content for debugging
   619→                let payload_str = std::str::from_utf8(&payload).unwrap_or("<binary>");
   620→                debug!(
   621→                    page_id = %state.page_id,
   622→                    user_did = ?user_did,
   623→                    device_id = ?device_id,
   624→                    payload_len = payload.len(),
   625→                    payload = %payload_str,
   626→                    our_did = %state.our_did,
   627→                    "Scribe received RemoteEphemeral"
   628→                );
   629→                // 1. Forward to local app layer (if we have sender info)
   630→                if let Some(ref did) = user_did {
   631→                    let handled = route_remote_ephemeral(state, did, &payload);
   632→                    debug!(page_id = %state.page_id, handled = handled, our_did = %state.our_did, "route_remote_ephemeral returned");
