   636→                    }
   637→                } else {
   638→                    debug!(page_id = %state.page_id, "RemoteEphemeral without user_did - not emitting to local app");
   639→                }
   640→
   641→                // 2. Relay to other subscribers (node mode relay) - exclude sender
   642→                let exclude = match (&user_did, &device_id) {
   643→                    (Some(d), Some(dev)) => Some((d.as_str(), dev.as_str())),
   644→                    _ => None,
   645→                };
   646→                broadcast_ephemeral_to_subscribers(state, &payload, exclude);
   647→            }
   648→
   649→            ScribeMessage::SendEphemeral { payload } => {
   650→                // Broadcast ephemeral data directly to all subscribed PeerActors
   651→                // No exclusion - this is local user action, send to everyone
   652→                debug!(page_id = %state.page_id, payload_len = payload.len(), "Broadcasting ephemeral to all subscribers");
   653→                broadcast_ephemeral_to_subscribers(state, &payload, None);
   654→            }
   655→
   656→            ScribeMessage::SendStructuredEphemeral { func, args } => {
   657→                // Log the incoming request
   658→                let has_permit = state.our_permit.is_some();
   659→                let ephemeral_funcs = state.our_permit
   660→                    .as_ref()
   661→                    .map(|p| p.ephemeral_funcs().to_vec())
   662→                    .unwrap_or_default();
   663→                debug!(
   664→                    page_id = %state.page_id,
   665→                    func = %func,
   666→                    has_permit = has_permit,
   667→                    ephemeral_funcs = ?ephemeral_funcs,
   668→                    our_did = %state.our_did,
   669→                    "SendStructuredEphemeral received"
   670→                );
   671→
   672→                // Validate func against our permit's ephemeral_funcs (if set)
   673→                // Empty ephemeral_funcs list means all funcs allowed
   674→                let can_send = state.our_permit
   675→                    .as_ref()
   676→                    .map(|p| p.can_send_ephemeral(&func))
   677→                    .unwrap_or(true); // No permit = allow (local mode)
   678→
   679→                if !can_send {
   680→                    warn!(page_id = %state.page_id, func = %func, "Structured ephemeral func not allowed by permit");
   681→                    return Ok(());
   682→                }
   683→
   684→                // Broadcast as StructuredEphemeral to app subscribers (local UI)
   685→                let our_did = state.our_did.clone();
   686→                emit_structured_ephemeral(state, &our_did, &func, &args);
   687→
   688→                // Also broadcast via ephemeral channel for remote peers
   689→                // PeerActor should be subscribed to this Scribe with ephemeral_tx
   690→                // Include from_did so relayed messages preserve original sender identity
   691→                let payload = serde_json::json!({
   692→                    "type": "structured",
   693→                    "from_did": our_did,
   694→                    "func": func,
   695→                    "args": args
   696→                });
   697→                if let Ok(bytes) = serde_json::to_vec(&payload) {
   698→                    debug!(
   699→                        page_id = %state.page_id,
   700→                        func = %func,
   701→                        "Broadcasting structured ephemeral to PeerActor subscribers"
   702→                    );
   703→                    broadcast_ephemeral_to_subscribers(state, &bytes, None);
   704→                }
   705→            }
   706→
   707→            ScribeMessage::RemoteStructuredEphemeral { from_did, device_id, func, args } => {
   708→                // Validate func against sender's permit
   709→                let can_send = {
   710→                    let subs = state.subscribers.read().ok();
   711→                    subs.and_then(|s| {
   712→                        s.get(&(from_did.clone(), device_id.clone()))
   713→                            .map(|info| info.permit.can_send_ephemeral(&func))
   714→                    }).unwrap_or(false) // Unknown sender = reject
   715→                };
   716→
   717→                if !can_send {
   718→                    warn!(
   719→                        page_id = %state.page_id,
   720→                        from_did = %from_did,
   721→                        func = %func,
   722→                        "Remote structured ephemeral rejected - func not allowed"
   723→                    );
   724→                    return Ok(());
   725→                }
   726→
   727→                // Emit to local app subscribers
   728→                emit_structured_ephemeral(state, &from_did, &func, &args);
   729→
   730→                debug!(
   731→                    page_id = %state.page_id,
   732→                    from_did = %from_did,
   733→                    func = %func,
   734→                    "Processed remote structured ephemeral"
   735→                );
   736→            }
   737→
   738→            // Note: Ephemeral events now go through SubscribeToPageUpdates (PageUpdate::Ephemeral)
   739→
   740→            // Derivation operations (now handled by kunki/LuaRuntime externally)
   741→            ScribeMessage::RebuildDerived { target: _, reply } => {
   742→                // Derivation is now handled by kunki, not Scribe
   743→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
   744→            }
   745→
   746→            ScribeMessage::RebuildAllDerived { reply } => {
   747→                // Derivation is now handled by kunki, not Scribe
   748→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
   749→            }
   750→
   751→            ScribeMessage::IsDerivationEnabled { reply } => {
   752→                // Derivation is now external, Scribe always returns false
   753→                let _ = reply.send(false);
   754→            }
   755→
   756→            ScribeMessage::CreateDerivedLayer { target_layer } => {
   757→                let target_layer = normalize_layer_name(&target_layer, &state.page_id);
   758→                // Create the derived layer (empty) so it exists for subscribers
   759→                if !state.layers.contains_key(&target_layer) {
   760→                    let layer = Layer::new();
   761→                    let _ = layer.loro().get_map(target_layer.clone());
   762→                    layer.commit();
   763→                    state.layers.insert(target_layer.clone(), layer);
   764→                    info!(target = %target_layer, "Created empty derived layer");
   765→
   766→                    // Set up observer for the new layer
   767→                    loro_observer::setup_layer_observer(state, &target_layer);
   768→                }
   769→            }
   770→
   771→            ScribeMessage::GetAppFiles { app_name, reply } => {
   772→                // Use bare layer name (Scribe uses bare names, no page_id/ prefix)
   773→                let layer_name = format!("app:{}", app_name);
   774→                let result = if let Some(layer) = state.layers.get(&layer_name) {
   775→                    Ok(layer.get_all_files())
   776→                } else {
   777→                    Err(format!("App layer '{}' not found", layer_name))
   778→                };
   779→                let _ = reply.send(result);
   780→            }
   781→
   782→            ScribeMessage::GetSubscriberCount { reply } => {
   783→                let count = state.subscribers.read()
   784→                    .map(|s| s.len())
   785→                    .unwrap_or(0);
   786→                let _ = reply.send(count);
   787→            }
   788→
   789→            ScribeMessage::RefreshApp { app_name: _, app_dir: _, reply } => {
   790→                // RefreshApp requires filesystem access which is handled by butler's refresh service
   791→                // This stub returns an error - callers should use butler's refresh functionality instead
   792→                let _ = reply.send(Err("RefreshApp not supported in base Scribe - use butler's refresh service".to_string()));
   793→            }
   794→        }
   795→
   796→        Ok(())
   797→    }
   798→
   799→    #[instrument(skip_all, fields(page_id = %state.page_id))]
   800→    async fn post_stop(
   801→        &self,
   802→        _myself: ActorRef<Self::Msg>,
   803→        state: &mut Self::State,
   804→    ) -> std::result::Result<(), ActorProcessingErr> {
   805→        // Flush any dirty layers before stopping
   806→        if !state.dirty_layers.is_empty() {
   807→            info!(page_id = %state.page_id, dirty_count = state.dirty_layers.len(), "Flushing dirty layers on shutdown");
   808→            sync::handle_flush(state).await;
   809→        }
   810→
   811→        // Stop node script if running
   812→        if let Some(tx) = state.node_script_shutdown.take() {
   813→            info!(page_id = %state.page_id, "Stopping node script tick loop");
   814→            let _ = tx.send(()).await;
   815→        }
   816→
   817→        info!(page_id = %state.page_id, "Scribe stopped");
   818→        Ok(())
   819→    }
   820→}
   821→
   822→// Helper Methods
   823→
   824→impl Scribe {
   825→    /// Handle JSON update from UI (CEL commit())
   826→    ///
   827→    /// **Broadcast**: Handled automatically by Loro observer after commit()
   828→    #[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
   829→    async fn handle_update_from_json(
   830→        &self,
   831→        state: &mut ScribeState,
   832→        layer_name: &str,
   833→        path: &str,
   834→        value: serde_json::Value,
   835→    ) -> Result<()> {
   836→        info!(layer = %layer_name, path = %path, "Updating layer from JSON");
   837→
   838→        // Get or create the layer
   839→        let layer = state
   840→            .layers
   841→            .entry(layer_name.to_string())
   842→            .or_insert_with(Layer::new);
   843→
   844→        // Convert JSON to Loro and update
   845→        layer
   846→            .set_from_json(path, &value)
   847→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
   848→
   849→        // Commit to trigger Loro observer (which broadcasts to peers + notifies UI)
   850→        layer.commit();
   851→
   852→        // Mark as dirty for persistence
   853→        state.dirty_layers.insert(layer_name.to_string());
   854→
   855→        debug!("Layer update from JSON complete, observer will broadcast");
   856→        Ok(())
   857→    }
   858→}
   859→
   860→// Tests
   861→
   862→#[cfg(test)]
   863→mod tests {
   864→    use super::*;
   865→    use crate::test_fixtures::node_scribe_args;
   866→    use std::time::Duration;
   867→
   868→    /// Test that Scribe with no subscribers doesn't crash on ephemeral send
   869→    #[tokio::test]
   870→    async fn test_ephemeral_with_no_subscribers() {
   871→        let args = node_scribe_args("test-page-456");
   872→        let (scribe_ref, _handle) = ractor::Actor::spawn(
   873→            Some("test-scribe-no-subs".to_string()),
   874→            Scribe,
   875→            args,
   876→        ).await.expect("Failed to spawn Scribe");
   877→
   878→        // Send ephemeral with no subscribers - should not crash
   879→        scribe_ref.cast(ScribeMessage::SendStructuredEphemeral {
   880→            func: "typing".to_string(),
   881→            args: serde_json::json!({"user": "TestUser"}),
   882→        }).expect("Failed to send ephemeral");
   883→
   884→        // Small delay to ensure message is processed
   885→        tokio::time::sleep(Duration::from_millis(50)).await;
   886→
   887→        println!("✓ Ephemeral with no subscribers handled gracefully");
   888→        scribe_ref.stop(Some("test complete".to_string()));
   889→    }
   890→}
   891→

