     1→//! Loro CRDT observer and delta handling
     2→//!
     3→//! Handles subscription to Loro changes, delta conversion, and reactive notifications.
     4→//!
     5→//! **Architecture**: Loro's `import()` triggers `subscribe_root` observers automatically.
     6→//! We set up observers for all layers at startup so that both UI notifications and
     7→//! peer broadcasts are handled through the observer pattern (no manual callbacks needed).
     8→
     9→use loro::event::{Diff, DiffEvent, ListDiffItem};
    10→use loro::{LoroValue, ValueOrContainer};
    11→use tokio::sync::mpsc;
    12→use tracing::{debug, info, instrument, warn};
    13→use base64::Engine;
    14→
    15→use crate::message::{BroadcastPayload, LoroDelta, ListOp, PageUpdate};
    16→use crate::permit::Permissions;
    17→use crate::state::ScribeState;
    18→use domains::JsonOp;
    19→
    20→/// Data sent through observer channel (delta + ops for reactive bindings)
    21→struct ObserverSignal {
    22→    delta: Option<LoroDelta>,
    23→    ops: Vec<JsonOp>,
    24→    /// Source of the change: None = local, Some = remote peer (user_did, device_id)
    25→    /// Used for sender exclusion in broadcasts
    26→    from_peer: Option<(String, String)>,
    27→}
    28→
    29→// Delta Conversion Helpers
    30→
    31→/// Convert DiffEvent to structured JsonOps for reactive bindings
    32→///
    33→/// **Context**: Observer receives DiffEvent on Loro changes
    34→/// **We do**: Extract structured ops (insert/update/delete) with keys/values
    35→/// **Used by**: Lua's on_loro_change(layer, ops, full_data) for surgical UI updates
    36→pub fn diff_event_to_ops(diff_event: &DiffEvent) -> Vec<JsonOp> {
    37→    let mut ops = Vec::new();
    38→
    39→    for container_diff in &diff_event.events {
    40→        let path = container_diff.target.to_string();
    41→
    42→        match &container_diff.diff {
    43→            Diff::List(items) => {
    44→                // Track position for list operations
    45→                let mut pos = 0usize;
    46→                for item in items.iter() {
    47→                    match item {
    48→                        ListDiffItem::Insert { insert, .. } => {
    49→                            for (i, value) in insert.iter().enumerate() {
    50→                                let json_value = value_or_container_to_json(value);
    51→                                ops.push(JsonOp {
    52→                                    op: "insert".to_string(),
    53→                                    path: path.clone(),
    54→                                    key: None,
    55→                                    index: Some(pos + i),
    56→                                    value: Some(json_value),
    57→                                    old_value: None,
    58→                                });
    59→                            }
    60→                            pos += insert.len();
    61→                        }
    62→                        ListDiffItem::Delete { delete } => {
    63→                            // Each delete is a single op
    64→                            for _ in 0..*delete {
    65→                                ops.push(JsonOp {
    66→                                    op: "delete".to_string(),
    67→                                    path: path.clone(),
    68→                                    key: None,
    69→                                    index: Some(pos),
    70→                                    value: None,
    71→                                    old_value: None,
    72→                                });
    73→                            }
    74→                            // Position doesn't advance for deletes
    75→                        }
    76→                        ListDiffItem::Retain { retain } => {
    77→                            // Retain just moves position, no op
    78→                            pos += retain;
    79→                        }
    80→                    }
    81→                }
    82→            }
    83→
    84→            Diff::Map(map_delta) => {
    85→                for (key, value) in map_delta.updated.iter() {
    86→                    let json_value = value.as_ref()
    87→                        .map(|v| value_or_container_to_json(v));
    88→
    89→                    if let Some(val) = json_value {
    90→                        // Could be insert or update - we use "set" for both
    91→                        ops.push(JsonOp {
    92→                            op: "set".to_string(),
    93→                            path: path.clone(),
    94→                            key: Some(key.to_string()),
    95→                            index: None,
    96→                            value: Some(val),
    97→                            old_value: None,  // TODO: Could track old values if needed
    98→                        });
    99→                    } else {
   100→                        // Value is None = deletion
   101→                        ops.push(JsonOp {
   102→                            op: "delete".to_string(),
   103→                            path: path.clone(),
   104→                            key: Some(key.to_string()),
   105→                            index: None,
   106→                            value: None,
   107→                            old_value: None,
   108→                        });
   109→                    }
   110→                }
   111→            }
   112→
   113→            Diff::Text(_text_delta) => {
   114→                // Text deltas not yet supported for ops
   115→                debug!("Text ops not yet implemented");
   116→            }
   117→
   118→            _ => {
   119→                debug!("Unsupported diff type for ops: {:?}", container_diff.diff);
   120→            }
   121→        }
   122→    }
   123→
   124→    ops
   125→}
   126→
   127→/// Convert Loro's Diff to our LoroDelta format
   128→///
   129→/// **Context**: Loro observer provides Diff on changes, we convert to JSON-serializable format
   130→/// **Returns**: LoroDelta for List/Map/Text containers, None for unsupported types
   131→pub fn convert_loro_diff_to_delta(diff: &Diff) -> Option<LoroDelta> {
   132→    match diff {
   133→        Diff::List(items) => {
   134→            let ops = items.iter().map(|item| {
   135→                match item {
   136→                    ListDiffItem::Insert { insert, .. } => {
   137→                        // Convert ValueOrContainer to JSON values
   138→                        let values = insert.iter()
   139→                            .map(|v| value_or_container_to_json(v))
   140→                            .collect();
   141→                        ListOp::Insert { values }
   142→                    }
   143→                    ListDiffItem::Delete { delete } => {
   144→                        ListOp::Delete { count: *delete }
   145→                    }
   146→                    ListDiffItem::Retain { retain } => {
   147→                        ListOp::Retain { count: *retain }
   148→                    }
   149→                }
   150→            }).collect();
   151→
   152→            Some(LoroDelta::List { ops })
   153→        }
   154→
   155→        Diff::Map(map_delta) => {
   156→            let updated = map_delta.updated.iter()
   157→                .map(|(k, v)| {
   158→                    let value = v.as_ref()
   159→                        .map(|v| value_or_container_to_json(v));
   160→                    (k.to_string(), value)
   161→                })
   162→                .collect();
   163→
   164→            Some(LoroDelta::Map { updated })
   165→        }
   166→
   167→        Diff::Text(_text_delta) => {
   168→            // TODO: Implement text delta conversion when needed
   169→            // For now, return None and fall back to full data
   170→            debug!("Text delta conversion not yet implemented");
   171→            None
   172→        }
   173→
   174→        _ => {
   175→            debug!("Unsupported diff type: {:?}", diff);
   176→            None
   177→        }
   178→    }
   179→}
   180→
   181→/// Convert Loro ValueOrContainer to serde_json::Value
   182→///
   183→/// **Context**: Loro stores values as LoroValue or nested Containers
   184→/// **We do**: Extract deep value and convert to JSON
   185→fn value_or_container_to_json(value: &ValueOrContainer) -> serde_json::Value {
   186→    // Use ValueOrContainer::get_deep_value() to resolve containers
   187→    let deep_value = value.get_deep_value();
   188→    loro_value_to_json(&deep_value)
   189→}
   190→
   191→/// Convert LoroValue to serde_json::Value
   192→///
   193→/// **Context**: Loro's native value type → JSON for Lua consumption
   194→pub fn loro_value_to_json(value: &LoroValue) -> serde_json::Value {
   195→    match value {
   196→        LoroValue::Null => serde_json::Value::Null,
   197→        LoroValue::Bool(b) => serde_json::Value::Bool(*b),
   198→        LoroValue::I64(i) => serde_json::json!(*i),
   199→        LoroValue::Double(f) => serde_json::json!(*f),
   200→        LoroValue::String(s) => serde_json::Value::String(s.to_string()),
   201→        LoroValue::List(arr) => {
   202→            serde_json::Value::Array(
   203→                arr.iter().map(loro_value_to_json).collect()
   204→            )
   205→        }
   206→        LoroValue::Map(map) => {
   207→            serde_json::Value::Object(
   208→                map.iter()
   209→                    .map(|(k, v)| (k.to_string(), loro_value_to_json(v)))
   210→                    .collect()
   211→            )
   212→        }
   213→        LoroValue::Binary(bytes) => {
   214→            // Encode binary as base64 string
   215→            serde_json::Value::String(base64::engine::general_purpose::STANDARD.encode(&**bytes))
   216→        }
   217→        LoroValue::Container(_) => {
   218→            // Containers are resolved by get_deep_value, shouldn't appear in deltas
   219→            debug!("Container in delta value (unexpected), converting to null");
   220→            serde_json::Value::Null
   221→        }
   222→    }
   223→}
   224→
   225→// Loro Layer Handler
   226→
   227→/// Handle layer modified by Lua via direct FFI access
   228→///
   229→/// **Context**: Lua called push/set/etc on a LoroList/LoroMap
   230→/// **We do**: Check permission, commit transaction, let Loro observer handle notifications
   231→///
   232→/// **Note**: By the time this is called, the change is already in the Loro doc (via FFI).
   233→/// We can't reject it here, but we log a warning if permission would be denied.
   234→/// Future: Lua bindings should check can_local_write() before allowing the operation.
   235→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
   236→pub async fn handle_layer_modified_by_lua(state: &mut ScribeState, layer_name: String) {
   237→    debug!(layer_name = %layer_name, "Layer modified by Lua, committing transaction");
   238→
   239→    // Check if we have permission to write to this layer
   240→    // Note: Changes are already made via FFI, this is defense-in-depth logging
   241→    if !Permissions::can_local_write(state, &layer_name) {
   242→        warn!(
   243→            layer = %layer_name,
   244→            our_did = %state.our_did,
   245→            "Local write to layer without permission (changes already applied via FFI)"
   246→        );
   247→        // TODO: In future, Lua bindings should check permission before allowing write
   248→        // For now, we still commit to avoid leaving Loro in inconsistent state
   249→    }
   250→
   251→    // Commit the Loro transaction to trigger native observer
   252→    // This makes the observer fire immediately with delta information
   253→    if let Some(layer) = state.layers.get(&layer_name) {
   254→        layer.commit();
   255→    }
   256→
   257→    // Mark layer as dirty for periodic flush (every 10s)
   258→    state.dirty_layers.insert(layer_name.clone());
   259→
   260→    // NOTE: We don't manually notify observers here!
   261→    // The commit() above triggers Loro's native observer (setup in handle_subscribe_loro_changes)
   262→    // which will automatically:
   263→    // - Send LoroChangeEvent with delta to UI
   264→    // - Notify query subscribers
   265→    // - Broadcast to peers
   266→    //
   267→    // Dirty layer will be flushed to storage by periodic timer (every 10s)
   268→}
   269→
   270→// Startup Observer Setup
   271→
   272→/// Set up Loro observers for all layers at Scribe startup
   273→///
   274→/// **Context**: Called from `pre_start` to ensure observers are ready before any updates
   275→/// **Why**: Loro's `import()` triggers observers automatically, so we need them set up
   276→/// **Handles**: Peer broadcasts (to subscribers) + UI notifications (to loro_observers)
   277→///
   278→/// This ensures both local changes (via commit) and remote changes (via import)
   279→/// go through the same observer-based notification path.
   280→#[instrument(skip_all, fields(page_id = %state.page_id))]
   281→pub fn setup_observers_for_all_layers(state: &mut ScribeState) {
   282→    let layer_names: Vec<String> = state.layers.keys().cloned().collect();
   283→
   284→    for layer_name in layer_names {
   285→        setup_layer_observer(state, &layer_name);
   286→    }
   287→
   288→    info!(
   289→        page_id = %state.page_id,
   290→        layer_count = state.loro_subscriptions.len(),
   291→        "Set up Loro observers for all layers"
   292→    );
   293→}
   294→
   295→/// Set up Loro observer for a single layer
   296→///
   297→/// **Context**: Sets up the observer infrastructure for peer broadcasts and UI notifications
   298→/// **Observer fires**: On commit() AND import() - both trigger subscribe_root
   299→///
   300→/// **Public**: Called from mod.rs when new layers are dynamically created
   301→#[instrument(skip(state), fields(page_id = %state.page_id))]
   302→pub fn setup_layer_observer(state: &mut ScribeState, layer_name: &str) {
   303→    // Skip if already set up
   304→    if state.loro_subscriptions.contains_key(layer_name) {
   305→        return;
   306→    }
   307→
   308→    let layer = match state.layers.get(layer_name) {
   309→        Some(l) => l,
   310→        None => {
   311→            warn!(layer_name = %layer_name, "Layer not found for observer setup");
   312→            return;
   313→        }
   314→    };
   315→
   316→    // Create internal channel for observer signals (includes ops for reactive bindings)
   317→    let (signal_tx, mut signal_rx) = tokio::sync::mpsc::unbounded_channel::<ObserverSignal>();
   318→
   319→    // Clone for the async task
   320→    let layer_for_task = layer.clone();
   321→    let layer_name_for_task = layer_name.to_string();
   322→    let subscribers_for_task = state.subscribers.clone();
   323→    let local_only_for_task = state.local_only_layers.clone();
   324→    let page_id_for_task = state.page_id.clone();
   325→    let page_update_subscribers_for_task = state.page_update_subscribers.clone();
   326→
   327→    // Clone pending_update_source for the synchronous callback
   328→    let pending_update_source = state.pending_update_source.clone();
   329→
   330→    // Spawn async task to handle observer signals
   331→    // Note: Derivation is handled in handle_apply_update using ops, not here
   332→    tokio::spawn(async move {
   333→        while let Some(signal) = signal_rx.recv().await {
   334→            let state_vector = layer_for_task.version_vector();
   335→
   336→            // Prepare ops for reactive bindings (Some if non-empty, None otherwise)
   337→            let ops = if signal.ops.is_empty() { None } else { Some(signal.ops) };
   338→
   339→            // Skip expensive get_content() only for List deltas (surgical conversion always works).
   340→            // For Map/Text deltas, always provide full_data so non-keyed Map bindings can
   341→            // fall back to Replace when delta conversion returns empty.
   342→            let full_data = if matches!(&signal.delta, Some(LoroDelta::List { .. })) {
   343→                None
   344→            } else {
   345→                Some(layer_for_task.get_content(&layer_name_for_task))
   346→            };
   347→
   348→            let page_update = PageUpdate::LayerChanged {
   349→                layer: layer_name_for_task.clone(),
   350→                from_peer: None,  // Local change
   351→                ops,
   352→                delta: signal.delta,
   353→                state_vector,
   354→                full_data,
   355→                created: false,
   356→            };
   357→            if let Ok(subs) = page_update_subscribers_for_task.read() {
   358→                for tx in subs.iter() {
   359→                    let _ = tx.try_send(page_update.clone());
   360→                }
   361→                if !subs.is_empty() {
   362→                    debug!(
   363→                        layer_name = %layer_name_for_task,
   364→                        subscriber_count = subs.len(),
   365→                        "Sent PageUpdate::LayerChanged"
   366→                    );
   367→                }
   368→            }
   369→
   370→            // Check if layer is local-only (sync: false in permit)
   371→            // If so, skip peer broadcasting entirely
   372→            if let Ok(local_only) = local_only_for_task.read() {
   373→                if local_only.contains(&layer_name_for_task) {
   374→                    debug!(
   375→                        layer_name = %layer_name_for_task,
   376→                        "Skipping peer broadcast for local-only layer (sync: false)"
   377→                    );
   378→                    continue;
   379→                }
   380→            }
   381→
   382→            // Skip peer broadcast for remote updates (sender exclusion)
   383→            // Remote updates are forwarded via broadcast_update() in apply.rs which has proper sender exclusion
   384→            // Broadcasting here would send the update back to the original sender, causing a sync storm
   385→            if signal.from_peer.is_some() {
   386→                debug!(
   387→                    layer_name = %layer_name_for_task,
   388→                    "Skipping observer peer broadcast for remote update (handled by broadcast_update)"
   389→                );
   390→                continue;
   391→            }
   392→
   393→            // Broadcast incremental updates to peer subscribers
   394→            // Uses per-subscriber export_updates(their_vector) instead of full snapshot
   395→            let current_vector = layer_for_task.version_vector();
   396→
   397→            if let Ok(subs) = subscribers_for_task.read() {
   398→                debug!(
   399→                    page_id = %page_id_for_task,
   400→                    layer_name = %layer_name_for_task,
   401→                    subscriber_count = subs.len(),
   402→                    "Observer broadcasting to subscribers"
   403→                );
   404→                for ((user_did, device_id), info) in subs.iter() {
   405→                    if !info.can_receive_layer(&layer_name_for_task, &page_id_for_task) {
   406→                        continue;
   407→                    }
   408→
   409→                    // Incremental export: use subscriber's last known vector
   410→                    // Falls back to full snapshot for first sync (no vector cached)
   411→                    let update = if let Some(their_vector) = info.vectors.get(&*layer_name_for_task) {
   412→                        layer_for_task.export_updates(their_vector)
   413→                            .unwrap_or_else(|_| layer_for_task.export_snapshot())
   414→                    } else {
   415→                        layer_for_task.export_snapshot()
   416→                    };
   417→
   418→                    let update_size = update.len();
   419→                    let payload = BroadcastPayload {
   420→                        page_id: page_id_for_task.clone(),
   421→                        layer_name: layer_name_for_task.clone(),
   422→                        layer_type: domains::LayerType::from_layer_name(&layer_name_for_task),
   423→                        update,
   424→                        state_vector: current_vector.clone(),
   425→                    };
   426→
   427→                    match info.broadcast_tx.try_send(payload) {
   428→                        Ok(()) => {
   429→                            debug!(
   430→                                user_did = %user_did,
   431→                                layer_name = %layer_name_for_task,
   432→                                update_size = update_size,
   433→                                "Sent incremental broadcast to subscriber"
   434→                            );
   435→                        }
   436→                        Err(mpsc::error::TrySendError::Full(_)) => {
   437→                            warn!(user_did = %user_did, device_id = %device_id, "Peer broadcast channel full");
   438→                        }
   439→                        Err(mpsc::error::TrySendError::Closed(_)) => {
   440→                            debug!(user_did = %user_did, "Peer broadcast channel closed");
   441→                        }
   442→                    }
   443→                }
   444→            }
   445→        }
   446→        debug!(layer_name = %layer_name_for_task, "Observer task ended");
   447→    });
   448→
   449→    // Subscribe to Loro changes - extract ops and delta for reactive bindings
   450→    let subscription = layer.subscribe_root(move |diff_event: loro::event::DiffEvent| {
   451→        // Extract structured ops for reactive Lua bindings (surgical UI updates)
   452→        let ops = diff_event_to_ops(&diff_event);
   453→
   454→        // Extract delta for legacy VecModel operations
   455→        let delta = diff_event.events.first()
   456→            .and_then(|container_diff| convert_loro_diff_to_delta(&container_diff.diff));
   457→
   458→        // Read pending_update_source to determine if this is a remote update
   459→        // Remote updates should not trigger peer broadcast (handled by broadcast_update with sender exclusion)
   460→        let from_peer = pending_update_source.lock().ok().and_then(|g| g.clone());
   461→
   462→        let _ = signal_tx.send(ObserverSignal { delta, ops, from_peer });
   463→    });
   464→
   465→    // Store subscription
   466→    state.loro_subscriptions.insert(layer_name.to_string(), subscription);
   467→    debug!(layer_name = %layer_name, "Set up Loro observer for layer");
   468→}
   469→
   470→// Pending Update Source Helpers
   471→
   472→/// Set pending update source before import()
   473→///
   474→/// **Context**: Called in handle_apply_update before import()
   475→/// **Usage**: Observer reads this to populate `from_peer` in PageEvent
   476→pub fn set_pending_update_source(state: &ScribeState, from_peer: Option<(String, String)>) {
   477→    if let Ok(mut guard) = state.pending_update_source.lock() {
   478→        *guard = from_peer;
   479→    }
   480→}
   481→
   482→/// Clear pending update source after import()
   483→///
   484→/// **Context**: Called in handle_apply_update after import()
   485→/// **Important**: Must be called to reset for next local operation
   486→pub fn clear_pending_update_source(state: &ScribeState) {
   487→    if let Ok(mut guard) = state.pending_update_source.lock() {
   488→        *guard = None;
   489→    }
   490→}
