     1→//! Apply update handling for Scribe actor
     2→//!
     3→//! Handles incoming layer updates (local or remote), including permission checks,
     4→//! validation, and CRDT merge.
     5→//!
     6→//! Note: Derivation is now handled externally by kunki/LuaRuntime which
     7→//! subscribes to PageUpdate::LayerChanged events.
     8→//!
     9→//! ## Key Types
    10→//!
    11→//! - `UpdateContext`: Computed context for an incoming update - all decisions made upfront
    12→//! - `ApplyOutcome`: Result of applying an update (Applied or Rejected)
    13→
    14→use logging_utils::ShortLayer;
    15→use tracing::{debug, error, info, warn, instrument};
    16→
    17→use domains::Layer;
    18→
    19→use super::broadcast::{broadcast_update, notify_layer_discovered};
    20→use crate::loro_observer::{set_pending_update_source, clear_pending_update_source, setup_layer_observer};
    21→use crate::permit::{Permissions, PermitContext};
    22→use crate::state::ScribeState;
    23→use crate::JsonOp;
    24→use crate::state::normalize_layer_name;
    25→
    26→// Update Context - Centralized Decision Logic
    27→
    28→/// Context for an incoming update - computed once, used throughout
    29→///
    30→/// **Design**: All decisions about how to handle an update are computed upfront.
    31→/// This makes the apply flow clearer and easier to test.
    32→#[derive(Debug)]
    33→pub struct UpdateContext {
    34→    /// Layer being updated
    35→    pub layer_name: String,
    36→    /// Source of update: None = local, Some = remote peer (user_did, device_id)
    37→    pub from_peer: Option<(String, String)>,
    38→    /// Role of the peer (for validation) - "node", "owner", "viewer", etc.
    39→    pub peer_role: String,
    40→
    41→    /// Is this a remote update (from a peer)?
    42→    pub is_remote: bool,
    43→    /// Is this layer local-only (never synced)?
    44→    pub is_local_only: bool,
    45→    /// Does this update need Lua validation?
    46→    pub should_validate: bool,
    47→    /// Should we broadcast after applying?
    48→    pub should_broadcast: bool,
    49→    /// Is this a new layer (needs creation)?
    50→    pub is_new_layer: bool,
    51→}
    52→
    53→impl UpdateContext {
    54→    /// Create context for an incoming update
    55→    ///
    56→    /// **Context**: Computes all decisions based on state and update metadata
    57→    /// **Note**: Permission checks are done separately (may reject before context is useful)
    58→    pub fn new(
    59→        state: &ScribeState,
    60→        layer_name: &str,
    61→        from_peer: Option<(String, String)>,
    62→    ) -> Self {
    63→        let is_remote = from_peer.is_some();
    64→        let is_local_only = Permissions::is_local_only(layer_name);
    65→        let is_new_layer = !state.layers.contains_key(layer_name);
    66→
    67→        // Determine peer role for validation
    68→        let peer_role = if let Some(ref peer) = from_peer {
    69→            get_peer_role(state, &peer.0)
    70→        } else {
    71→            "local".to_string()
    72→        };
    73→
    74→        // Should validate: remote update AND ValidationHandle exists
    75→        let should_validate = is_remote && state.validation_handle.is_some();
    76→
    77→        // Should broadcast: remote update (local updates use observer)
    78→        let should_broadcast = is_remote;
    79→
    80→        Self {
    81→            layer_name: layer_name.to_string(),
    82→            from_peer,
    83→            peer_role,
    84→            is_remote,
    85→            is_local_only,
    86→            should_validate,
    87→            should_broadcast,
    88→            is_new_layer,
    89→        }
    90→    }
    91→}
    92→
    93→// Apply Outcome - Event-Driven Pattern
    94→
    95→/// Outcome of applying an update
    96→///
    97→/// **Design**: Separates the "what happened" from "what to do next"
    98→/// This enables cleaner outcome handling and better error messages
    99→#[derive(Debug)]
   100→pub enum ApplyOutcome {
   101→    /// Update was successfully applied
   102→    Applied {
   103→        /// Layer that was updated
   104→        layer_name: String,
   105→        /// Ops extracted from update (for derivation)
   106→        ops: Vec<JsonOp>,
   107→        /// Was a new layer created?
   108→        created_layer: bool,
   109→    },
   110→    /// Update was rejected
   111→    Rejected {
   112→        /// Reason for rejection
   113→        reason: String,
   114→    },
   115→}
   116→
   117→// Apply Update Handler
   118→
   119→/// Handle layer update (local or remote)
   120→///
   121→/// **Context**: Edit from UI or sync push from peer
   122→/// **We do**: Permission check, validation, CRDT merge
   123→/// **Broadcast**: Handled automatically by Loro observer (set up at startup)
   124→/// **Returns**: Ok(()) on success, Err(message) on failure
   125→#[instrument(skip(state, update, permit), fields(page_id = %state.page_id, layer = %ShortLayer(layer_name)))]
   126→pub async fn handle_apply_update(
   127→    state: &mut ScribeState,
   128→    layer_name: &str,
   129→    update: &[u8],
   130→    from_peer: Option<(String, String)>,
   131→    permit: Option<&str>,
   132→) -> std::result::Result<(), String> {
   133→    let _ = permit; // Permit is used for subscription in Courier, not here
   134→
   135→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
   136→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
   137→    let layer_name = layer_name.as_str();
   138→
   139→    // Build context - computes all decisions upfront
   140→    let ctx = UpdateContext::new(state, layer_name, from_peer.clone());
   141→
   142→    // Step 1: Apply the update (with permission checks, validation, CRDT merge)
   143→    let outcome = apply_update_core(state, &ctx, update).await;
   144→
   145→    // Step 2: Handle the outcome
   146→    match outcome {
   147→        ApplyOutcome::Applied { layer_name, ops: _, created_layer } => {
   148→            // Mark layer as dirty for persistence
   149→            state.dirty_layers.insert(layer_name.clone());
   150→            debug!(layer = %layer_name, created = created_layer, "Update applied successfully");
   151→
   152→            // Post-apply handling for remote updates
   153→            if ctx.is_remote {
   154→                handle_post_apply(state, &layer_name, ctx.from_peer.clone()).await;
   155→            }
   156→
   157→            // Update sender's vector
   158→            if let Some(ref peer) = ctx.from_peer {
   159→                update_sender_vector(state, peer, &layer_name);
   160→            }
   161→
   162→            // Broadcast to eligible subscribers
   163→            if ctx.should_broadcast {
   164→                broadcast_update(state, &layer_name, ctx.from_peer.as_ref()).await;
   165→            }
   166→
   167→            // Note: Derivation is now handled externally by kunki/LuaRuntime
   168→            // which subscribes to PageUpdate::LayerChanged events
   169→
   170→            Ok(())
   171→        }
   172→        ApplyOutcome::Rejected { reason } => {
   173→            warn!(layer = %layer_name, reason = %reason, "Update rejected");
   174→            Err(reason)
   175→        }
   176→    }
   177→}
   178→
   179→/// Core apply logic - returns ApplyOutcome
   180→///
   181→/// **Context**: Separated from handle_apply_update for cleaner testing
   182→/// **Returns**: ApplyOutcome::Applied or ApplyOutcome::Rejected
   183→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
   184→async fn apply_update_core(
   185→    state: &mut ScribeState,
   186→    ctx: &UpdateContext,
   187→    update: &[u8],
   188→) -> ApplyOutcome {
   189→    // Step 1: Permission check - reject local_only layers from remote
   190→    if ctx.is_remote && ctx.is_local_only {
   191→        return ApplyOutcome::Rejected {
   192→            reason: "local_only layer cannot be updated by remote peer".to_string(),
   193→        };
   194→    }
   195→
   196→    // Step 2: Permission check for remote updates
   197→    if let Some(ref peer) = ctx.from_peer {
   198→        if !Permissions::can_write(state, peer, &ctx.layer_name) {
   199→            return ApplyOutcome::Rejected {
   200→                reason: "Permission denied: cannot write to layer".to_string(),
   201→            };
   202→        }
   203→    }
   204→
   205→    // Step 3: Extract ops for validation (using optimized pre-commit method)
   206→    let extracted_ops = if ctx.should_validate {
   207→        // Use Layer::extract_ops_from_bytes (5-10x faster than old fork+diff)
   208→        match Layer::extract_ops_from_bytes(update) {
   209→            Ok(ops) => Some(ops),
   210→            Err(e) => {
   211→                // Log extraction failure - validation will proceed with empty ops
   212→                // This could mask invalid updates, so log at warn level
   213→                warn!(layer = %ctx.layer_name, error = %e, "Failed to extract ops from update, proceeding with empty ops");
   214→                None
   215→            }
   216→        }
   217→    } else {
   218→        None
   219→    };
   220→
   221→    // Step 4: Validate with Lua (if needed)
   222→    if ctx.should_validate {
   223→        if let Err(e) = validate_update_with_context(state, ctx, &extracted_ops).await {
   224→            return ApplyOutcome::Rejected { reason: e };
   225→        }
   226→    }
   227→
   228→    // Step 5: Create layer if needed (remote only)
   229→    let created_layer = if ctx.is_new_layer {
   230→        if ctx.is_remote {
   231→            create_layer_from_peer(state, &ctx.layer_name);
   232→            true
   233→        } else {
   234→            return ApplyOutcome::Rejected {
   235→                reason: "Layer not found".to_string(),
   236→            };
   237→        }
   238→    } else {
   239→        false
   240→    };
   241→
   242→    // Step 6: Apply CRDT update
   243→    if let Err(e) = apply_crdt_update(state, &ctx.layer_name, update, ctx.from_peer.clone()) {
   244→        return ApplyOutcome::Rejected { reason: e };
   245→    }
   246→
   247→    ApplyOutcome::Applied {
   248→        layer_name: ctx.layer_name.clone(),
   249→        ops: extracted_ops.unwrap_or_default(),
   250→        created_layer,
   251→    }
   252→}
   253→
   254→// Helper Functions
   255→
   256→/// Validate update using ValidationHandle (kunki) or fallback to Lua runtime
   257→///
   258→/// **Context**: Business logic validation for remote updates
   259→/// **Returns**: Ok(()) if validation passed, Err(message) if rejected
   260→/// **Timeout**: 5 seconds for ValidationHandle (kunki), immediate for Lua runtime
   261→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
   262→async fn validate_update_with_context(
   263→    state: &ScribeState,
   264→    ctx: &UpdateContext,
   265→    extracted_ops: &Option<Vec<JsonOp>>,
   266→) -> Result<(), String> {
   267→    let Some(ref ops) = extracted_ops else {
   268→        return Ok(()); // No ops to validate
   269→    };
   270→
   271→    if ops.is_empty() {
   272→        return Ok(()); // Empty ops = nothing to validate
   273→    }
   274→
   275→    // Extract actual DID from from_peer, not the role
   276→    let from_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str()).unwrap_or("local");
   277→
   278→    // Use ValidationHandle (kunki mode with presence_lib)
   279→    let Some(ref validation_handle) = state.validation_handle else {
   280→        // No validation available - allow update (viewer/owner mode without kunki)
   281→        // This is expected in viewer/owner mode but unexpected in node mode without kunki
   282→        warn!(layer = %ctx.layer_name, from_did = %from_did, "No ValidationHandle available, allowing remote update without validation");
   283→        return Ok(());
   284→    };
   285→
   286→    use tokio::time::{timeout, Duration};
   287→
   288→    let validation_future = validation_handle.validate_ops(
   289→        &state.page_id,
   290→        &ctx.layer_name,
   291→        ops,
   292→        from_did,
   293→        &ctx.peer_role,
   294→    );
   295→
   296→    match timeout(Duration::from_secs(5), validation_future).await {
   297→        Ok(Ok((true, _))) => {
   298→            debug!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, "Validation passed");
   299→            Ok(())
   300→        }
   301→        Ok(Ok((false, error_msg))) => {
   302→            let msg = error_msg.unwrap_or_else(|| "Validation failed".to_string());
   303→            warn!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, error = %msg, "Validation rejected update");
   304→            Err(format!("Validation failed: {}", msg))
   305→        }
