     1→//! Broadcast handling for Scribe actor
     2→//!
     3→//! Handles layer update broadcasting to subscribers and page update emission.
     4→
     5→use tokio::sync::mpsc;
     6→use tracing::{info, instrument, warn};
     7→
     8→use crate::message::{BroadcastPayload, PageUpdate};
     9→use crate::state::ScribeState;
    10→
    11→// Layer Broadcasting
    12→
    13→/// Broadcast layer update to all eligible subscribers
    14→///
    15→/// **Context**: Layer has been updated, notify all subscribers
    16→/// **We do**: Send incremental or full snapshot to each subscriber
    17→/// **Cleanup**: Remove subscribers whose channels are closed (disconnected)
    18→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
    19→pub async fn broadcast_update(
    20→    state: &mut ScribeState,
    21→    layer_name: &str,
    22→    from_peer: Option<&(String, String)>,
    23→) {
    24→    let Some(layer) = state.layers.get(layer_name) else {
    25→        return;
    26→    };
    27→
    28→    let current_vector = layer.version_vector();
    29→
    30→    // Track subscribers to remove (channel closed = peer disconnected)
    31→    let mut to_remove: Vec<(String, String)> = Vec::new();
    32→
    33→    if let Ok(mut subs) = state.subscribers.write() {
    34→        for ((user_did, device_id), info) in subs.iter_mut() {
    35→            // Skip sender
    36→            if from_peer == Some(&(user_did.clone(), device_id.clone())) {
    37→                continue;
    38→            }
    39→
    40→            // Check can receive (fixed layers OR pattern-based)
    41→            if !info.can_receive_layer(layer_name, &state.page_id) {
    42→                continue;
    43→            }
    44→
    45→            // Incremental export: use subscriber's last known vector
    46→            // Falls back to full snapshot for first sync (no vector cached)
    47→            let update = if let Some(their_vector) = info.vectors.get(layer_name) {
    48→                layer.export_updates(their_vector)
    49→                    .unwrap_or_else(|_| layer.export_snapshot())
    50→            } else {
    51→                layer.export_snapshot()
    52→            };
