     1→//! Dynamic Layer Management
     2→//!
     3→//! Schema validation, path generation, and permit preparation for dynamic layers.
     4→//! Uses PermitIssuer trait — never touches signing keys directly.
     5→
     6→use tracing::{info, warn};
     7→
     8→use domains::Layer;
     9→
    10→use crate::state::ScribeState;
    11→use crate::storage::PermitIssuer;
    12→use crate::loro_observer;
    13→
    14→/// Handle CreateDynamicLayer message
    15→///
    16→/// **Context**: Lua app calls scribe:create_layer("channels/{id}/messages", "general")
    17→/// **We do**: Validate schema exists in permit, generate full path with our DID, create layer
    18→/// **Returns**: Full layer name (bare, without page_id prefix)
    19→pub fn handle_create_dynamic_layer(
    20→    state: &mut ScribeState,
    21→    schema_key: &str,
    22→    layer_id: &str,
    23→) -> Result<String, String> {
    24→    let permit = state.our_permit.as_ref()
    25→        .ok_or_else(|| "No permit available".to_string())?;
    26→
    27→    // Validate schema exists in our permit's dynamic_layer_schemas
    28→    let schemas = permit.dynamic_layer_schemas();
    29→    let _schema = schemas.get(schema_key)
    30→        .ok_or_else(|| format!("Schema '{}' not found in permit", schema_key))?;
    31→
    32→    // Generate full layer path with our DID
    33→    // Schema: "channels/{id}/messages" → Path: "channels/{our_did}/{layer_id}/messages"
    34→    let bare_path = generate_dynamic_path(schema_key, &state.our_did, layer_id);
    35→    let full_name = format!("{}/{}", state.page_id, bare_path);
    36→
    37→    // Check if layer already exists
    38→    if state.layers.contains_key(&bare_path) {
    39→        info!(layer = %bare_path, "Dynamic layer already exists");
    40→        return Ok(full_name);
    41→    }
    42→
    43→    // Create the layer
    44→    info!(
    45→        page_id = %state.page_id,
    46→        schema = %schema_key,
    47→        layer = %bare_path,
    48→        "Creating dynamic layer"
    49→    );
    50→    state.layers.insert(bare_path.clone(), Layer::new());
    51→    state.mark_layer_local_only_if_needed(&bare_path);
    52→
    53→    // Set up observer for the new layer
    54→    loro_observer::setup_layer_observer(state, &bare_path);
    55→
    56→    Ok(full_name)
    57→}
    58→
    59→/// Generate a dynamic layer path from schema pattern, creator DID, and layer ID
    60→///
    61→/// **Pattern**: `channels/{id}/messages` → `channels/{did}/{layer_id}/messages`
    62→/// **Pattern**: `orders/{id}` → `orders/{did}/{layer_id}`
    63→///
    64→/// The DID is inserted after the first literal segment, and `{id}` is replaced with layer_id.
    65→fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
    66→    let parts: Vec<&str> = schema_key.split('/').collect();
    67→    let mut result = Vec::new();
    68→
    69→    if parts.is_empty() {
    70→        return format!("{}/{}", our_did, layer_id);
    71→    }
    72→
    73→    // First segment: literal
    74→    result.push(parts[0].to_string());
    75→
    76→    // Insert our DID as the second segment (namespace)
    77→    result.push(our_did.to_string());
    78→
    79→    // Remaining segments: replace {id} with layer_id, keep literals
    80→    for part in &parts[1..] {
    81→        if *part == "{id}" {
    82→            result.push(layer_id.to_string());
    83→        } else {
    84→            result.push(part.to_string());
    85→        }
    86→    }
    87→
    88→    result.join("/")
    89→}
    90→
    91→/// Determine recipients and create layer permits for a new dynamic layer
    92→///
    93→/// **Context**: Called by Scribe when detecting a new dynamic layer from a peer.
    94→/// **Returns**: Ready-to-send permits — courier just distributes them.
    95→/// **Uses**: PermitIssuer trait (context-aware gurkha) — never touches signing keys.
    96→pub fn prepare_layer_permits(
    97→    permit_issuer: &dyn PermitIssuer,
    98→    page_id: &str,
    99→    layer_name: &str,
   100→    schema: &gurkha::DynamicLayerSchema,
   101→    creator_did: &str,
   102→    connected_peers: &[(String, String)],  // (did, role)
   103→) -> Result<Vec<(String, String)>, String> {
   104→    let mut permits = Vec::new();
   105→
   106→    match schema.grant {
   107→        gurkha::GrantType::Role => {
   108→            // Role-granted: all peers with matching roles get access
   109→            for (did, role) in connected_peers {
   110→                if let Some(perms) = schema.role_permissions.get(role) {
   111→                    match permit_issuer.issue_layer_permit(did, layer_name, perms.clone()) {
   112→                        Ok((token, _cid)) => {
   113→                            info!(
   114→                                page_id = %page_id,
   115→                                layer = %layer_name,
   116→                                recipient = %did,
   117→                                role = %role,
   118→                                "Issued role-based layer permit"
   119→                            );
   120→                            permits.push((did.clone(), token));
   121→                        }
   122→                        Err(e) => {
   123→                            warn!(
   124→                                page_id = %page_id,
   125→                                layer = %layer_name,
   126→                                recipient = %did,
   127→                                error = %e,
   128→                                "Failed to issue layer permit"
   129→                            );
   130→                        }
   131→                    }
   132→                }
   133→            }
   134→        }
   135→        gurkha::GrantType::Explicit => {
   136→            // Explicit-granted: creator + named participants only
   137→            let default_config = schema.permissions.clone().unwrap_or(
   138→                gurkha::LayerConfig { sync: true, write: true, layer_type: None }
   139→            );
   140→
   141→            // Creator always gets access
   142→            match permit_issuer.issue_layer_permit(creator_did, layer_name, default_config.clone()) {
   143→                Ok((token, _cid)) => {
   144→                    info!(
   145→                        page_id = %page_id,
   146→                        layer = %layer_name,
   147→                        creator = %creator_did,
   148→                        "Issued creator layer permit"
   149→                    );
   150→                    permits.push((creator_did.to_string(), token));
   151→                }
   152→                Err(e) => {
   153→                    warn!(
   154→                        page_id = %page_id,
   155→                        layer = %layer_name,
   156→                        error = %e,
   157→                        "Failed to issue creator layer permit"
   158→                    );
   159→                }
   160→            }
   161→
   162→            // TODO: Named participants (from layer metadata) — Phase 2d
   163→        }
   164→    }
   165→
   166→    Ok(permits)
   167→}
   168→
   169→/// Validate that a layer path created by a peer matches their DID (namespace security)
   170→///
   171→/// **Context**: Node receives a new layer from a peer. Before accepting, verify
   172→/// that the creator's DID is in the layer path (prevents namespace forgery).
   173→///
   174→/// **Returns**: true if the layer path contains the sender's DID
   175→pub fn validate_creator_namespace(layer_name: &str, page_id: &str, sender_did: &str) -> bool {
   176→    let page_prefix = format!("{}/", page_id);
   177→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
   178→
   179→    // The creator's DID must be the second segment in the path
   180→    let parts: Vec<&str> = bare_path.split('/').collect();
   181→    if parts.len() < 2 {
   182→        return false;
   183→    }
   184→
   185→    parts[1] == sender_did
   186→}
