        page_id: page_id.to_string(),
        layers: HashMap::new(),
        layer_storage: null_layer_storage(),
        vector_storage: null_vector_storage(),
        peer_resolver: None,
        permit_issuer: None,
        sync_config: None,
        sync_event_tx: None,
        validation_handle: None,
        our_permit: None,
        our_did: String::new(),
        our_username: String::new(),
        is_node: false,
    }
}

/// Create ScribeArgs with layers
pub fn scribe_args_with_layers(page_id: &str, layer_names: &[&str]) -> ScribeArgs {
    let mut layers = HashMap::new();
    for name in layer_names {
        layers.insert(name.to_string(), Layer::new());
    }

    ScribeArgs {
        page_id: page_id.to_string(),
        layers,
        layer_storage: null_layer_storage(),
        vector_storage: null_vector_storage(),
        peer_resolver: None,
        permit_issuer: None,
        sync_config: None,
        sync_event_tx: None,
        validation_handle: None,
        our_permit: None,
        our_did: String::new(),
        our_username: String::new(),
        is_node: false,
