            mode: SyncMode::Broadcast,
            sync_target: None,
        }),
        sync_event_tx: None,
        validation_handle: None,
        our_permit: None,
        our_did: "did:key:node123".to_string(),
        our_username: "test_node".to_string(),
        is_node: true,
    }
