    layer_name: &str,
    path: &str,
    item: serde_json::Value,
) -> Result<()> {
    info!("ListPush operation");

    // Ensure layer exists
    let is_new_layer = ensure_layer_exists(state, layer_name);

    let unit = state.units.get_mut(layer_name)
        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;

    if path.is_empty() {
