        list.push(loro_value)
            .map_err(|e| ScribeError::CrdtError(format!("ListPush: {}", e)))?;
        unit.layer().commit();
    } else {
        // Template pattern: use root map with nested path
        unit.layer().list_push(path, &item)
            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
    }

