     1→//! Peer — single participant using MockConnection only
     2→//!
     3→//! No generics, no IrohConnection support. Fast, in-memory protocol testing.
     4→
     5→use std::sync::Arc;
     6→use std::time::Duration;
     7→
     8→use anyhow::Result;
     9→use tokio::sync::{mpsc, RwLock};
    10→use tracing::info;
    11→use transport::{MockBlobStore, MockConnection, NodeId, mock_connection_pair, node_id_from_secret};
    12→
    13→use butler::{Butler, LayerCache, RedbStore, signup};
    14→use courier::coordinator::{Coordinator, CoordinatorMessage, CourierMode};
    15→use courier::peer_actor::BlobStore;
    16→use courier::trace::MessageTrace;
    17→use courier::CourierEvent;
    18→use ractor::{Actor, ActorRef};
    19→
    20→/// Mock-only test peer
    21→pub struct Peer {
    22→    pub name: String,
    23→    pub node_id: NodeId,
    24→    pub mode: CourierMode,
    25→    pub coordinator: ActorRef<CoordinatorMessage<MockConnection>>,
    26→    pub butler: Arc<Butler>,
    27→    pub events: mpsc::Receiver<CourierEvent>,
    28→    _temp_dir: tempfile::TempDir,
    29→}
    30→
    31→impl Peer {
    32→    /// Create a new mock peer
    33→    ///
    34→    /// Pass `message_tx` from `Tracer::new()` to enable protocol tracing,
    35→    /// or `None` for tests that don't need it.
    36→    pub async fn new(
    37→        name: &str,
    38→        mode: CourierMode,
    39→        blobs: Arc<MockBlobStore>,
    40→        message_tx: Option<mpsc::UnboundedSender<MessageTrace>>,
    41→    ) -> Result<Self> {
    42→        let temp_dir = tempfile::tempdir()?;
    43→        let db_path = temp_dir.path().join(format!("{}.redb", name));
    44→
    45→        // Storage
    46→        let store = Arc::new(RedbStore::open(&db_path)?);
    47→        let layer_cache = Arc::new(RwLock::new(LayerCache::new(store.clone(), 100)));
    48→        let assets_path = temp_dir.path().join("assets");
    49→        let asset_store = Arc::new(butler::AssetStore::new(&assets_path)?);
    50→
    51→        // Wire sync_event channel so Scribe -> EnsureSync -> Coordinator works
    52→        let (sync_tx, mut sync_rx) = mpsc::channel::<butler::SyncEvent>(100);
    53→        let butler = Arc::new(Butler::new(store.clone(), layer_cache, asset_store, Some(sync_tx)));
    54→
    55→        // Create identity
    56→        let signup_result = signup(&store, name, "password")?;
    57→        butler.set_identity(signup_result.identity).await;
    58→
    59→        // Derive node_id from device key
    60→        let device_key = butler.device_key().await?;
    61→        let node_id = node_id_from_secret(&device_key);
    62→
    63→        // Event channel
    64→        let (event_tx, event_rx) = mpsc::channel::<CourierEvent>(100);
    65→
    66→        // Connect request channel (unused for mock — we inject connections directly)
    67→        let (connect_tx, _connect_rx) = mpsc::channel::<courier::ConnectRequest>(16);
    68→
    69→        // Coordinator
    70→        let blob = BlobStore::Mock(blobs);
    71→        let (coordinator, _) = Actor::spawn(
    72→            Some(format!("coordinator-{}-{}", name, node_id)),
    73→            Coordinator::<MockConnection>::new(),
    74→            (node_id, mode, butler.clone(), blob, Some(connect_tx), Some(event_tx), message_tx),
    75→        )
    76→        .await?;
    77→
    78→        // Forward EnsureSync from Scribe to Coordinator
    79→        let coord = coordinator.clone();
    80→        tokio::spawn(async move {
    81→            while let Some(event) = sync_rx.recv().await {
    82→                match event {
    83→                    butler::SyncEvent::EnsureSync { user_did } => {
    84→                        let _ = coord.cast(CoordinatorMessage::EnsureSync { user_did });
    85→                    }
    86→                    butler::SyncEvent::NewDynamicLayer { page_id, layer_name, permits } => {
    87→                        let _ = coord.cast(CoordinatorMessage::DistributeLayerPermits {
    88→                            page_id, layer_name, permits,
    89→                        });
    90→                    }
    91→                }
    92→            }
    93→        });
    94→
    95→        info!("Peer '{}' created: node_id={}, mode={:?}", name, node_id, mode);
    96→
    97→        Ok(Self {
    98→            name: name.to_string(),
    99→            node_id,
   100→            mode,
   101→            coordinator,
   102→            butler,
   103→            events: event_rx,
   104→            _temp_dir: temp_dir,
   105→        })
   106→    }
   107→
   108→    /// Connect to another mock peer using in-memory channels
   109→    pub fn connect_to(&self, other: &Peer) -> Result<()> {
   110→        let (conn_to_other, conn_to_self) = mock_connection_pair(self.node_id, other.node_id);
   111→
   112→        self.coordinator
   113→            .cast(CoordinatorMessage::Connected {
   114→                node_id: other.node_id,
   115→                conn: conn_to_other,
   116→            })
   117→            .map_err(|e| anyhow::anyhow!("Failed to inject connection: {:?}", e))?;
   118→
   119→        other
   120→            .coordinator
   121→            .cast(CoordinatorMessage::Connected {
   122→                node_id: self.node_id,
   123→                conn: conn_to_self,
   124→            })
   125→            .map_err(|e| anyhow::anyhow!("Failed to inject connection: {:?}", e))?;
   126→
   127→        info!("Mock connection: {} <-> {}", self.name, other.name);
   128→        Ok(())
   129→    }
   130→
   131→    /// Initiate handshake with a permit
   132→    pub fn handshake(&self, node_id: NodeId, permit: String) -> Result<()> {
   133→        self.coordinator
   134→            .cast(CoordinatorMessage::Connect { node_id, permit })
   135→            .map_err(|e| anyhow::anyhow!("Failed to send Connect: {:?}", e))
   136→    }
   137→
   138→    /// Wait for PeerAuthenticated event, returns (did, username)
   139→    pub async fn wait_authenticated(&mut self, timeout: Duration) -> Result<(String, String)> {
   140→        let deadline = tokio::time::Instant::now() + timeout;
   141→        loop {
   142→            match tokio::time::timeout_at(deadline, self.events.recv()).await {
   143→                Ok(Some(CourierEvent::PeerAuthenticated { did, username, .. })) => {
   144→                    info!("Peer '{}' authenticated with: {}", self.name, username);
   145→                    return Ok((did, username));
   146→                }
   147→                Ok(Some(CourierEvent::ConnectionFailed { node_id, error })) => {
   148→                    return Err(anyhow::anyhow!("Connection failed to {}: {}", node_id, error));
   149→                }
   150→                Ok(Some(_)) => continue,
   151→                Ok(None) => return Err(anyhow::anyhow!("Event channel closed")),
   152→                Err(_) => return Err(anyhow::anyhow!("Timeout waiting for authentication")),
   153→            }
   154→        }
   155→    }
   156→
   157→    /// Wait for any CourierEvent
   158→    pub async fn wait_event(&mut self, timeout: Duration) -> Result<CourierEvent> {
   159→        tokio::time::timeout(timeout, self.events.recv())
   160→            .await
   161→            .map_err(|_| anyhow::anyhow!("Timeout waiting for event"))?
   162→            .ok_or_else(|| anyhow::anyhow!("Event channel closed"))
   163→    }
   164→
   165→    /// Shutdown the peer
   166→    pub async fn shutdown(&self) {
   167→        let _ = self.coordinator.cast(CoordinatorMessage::Shutdown);
   168→    }
   169→}
   170→
   171→impl Drop for Peer {
   172→    fn drop(&mut self) {
   173→        let _ = self.coordinator.cast(CoordinatorMessage::Shutdown);
   174→    }
   175→}
