    18→/// Owner writes to map layer (reactions), node receives via SyncOffer
    19→///
    20→/// **Bug coverage**: "Permission denied: cannot write to layer" where
    21→/// node's Scribe rejects owner SyncOffers because Permissions::can_write()
    22→/// fails on all 3 paths (subscriber, sync_target, stored permit).
    23→///
    24→/// Uses "reactions" — the map layer defined in osvauld-demos's permit_template.json.
    25→#[tokio::test]
    26→async fn test_owner_layer_sync_to_node() -> Result<()> {
    27→    init_tracing();
    28→
    29→    let mut s = Scenario::builder()
    30→        .app("osvauld-demos")
    31→        .published()
    32→        .build()
    33→        .await?;
    34→
    35→    let page_id = s.space().page_id.clone();
    36→
    37→    // Give time for PageAnnounceAck + Scribe subscription
    38→    sleep(Duration::from_millis(500)).await;
    39→
    40→    // Owner opens page and writes to a map layer
    41→    let owner_scribe = s.owner().butler.open_page(&page_id).await?;
    42→
    43→    // Write data to "reactions" (a map layer in the osvauld-demos permit)
    44→    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
    45→    owner_scribe.cast(ScribeMessage::EnsureLoroMap {
    46→        layer_name: "reactions".to_string(),
    47→        reply: reply_tx,
    48→    }).map_err(|e| anyhow::anyhow!("Failed to ensure map: {:?}", e))?;
    49→    reply_rx.await??;
    50→
    51→    owner_scribe.cast(ScribeMessage::MapInsert {
    52→        layer_name: "reactions".to_string(),
    53→        path: String::new(),
    54→        key: "msg1".to_string(),
    55→        value: serde_json::json!({"emoji": "thumbs_up", "user": "owner"}),
    56→    }).map_err(|e| anyhow::anyhow!("Failed to insert: {:?}", e))?;
    57→
    58→    // Wait for layer data to arrive on node
    59→    let node_data = wait_for_layer_data(
    60→        &s.node().butler,
    61→        &page_id,
    62→        "reactions",
    63→        Duration::from_secs(10),
    64→    ).await?;
    65→
    66→    assert!(!node_data.is_empty(), "Node should have received reactions layer data");
    67→
    68→    s.shutdown().await;
    69→    Ok(())
    70→}
