     1→//! Thin wrapper around courier::MessageTrace for test assertions
     2→//!
     3→//! Collects protocol messages from the courier trace channel and provides
     4→//! assertion methods for verifying message sequences.
     5→
     6→use std::sync::{Arc, Mutex};
     7→
     8→use courier::trace::{MessageTrace, TraceDirection};
     9→use tokio::sync::mpsc;
    10→
    11→/// Protocol message tracer for integration tests
    12→///
    13→/// Create with `Tracer::new()`, pass the sender to Coordinator,
    14→/// then use assertion methods after running protocol operations.
    15→#[derive(Clone)]
    16→pub struct Tracer {
    17→    messages: Arc<Mutex<Vec<MessageTrace>>>,
    18→}
    19→
    20→impl Tracer {
    21→    /// Create a new tracer and its sender channel
    22→    ///
    23→    /// Pass the sender to Coordinator's Arguments tuple.
    24→    /// The tracer spawns a background task to collect messages.
    25→    pub fn new() -> (Self, mpsc::UnboundedSender<MessageTrace>) {
    26→        let (tx, mut rx) = mpsc::unbounded_channel();
    27→        let messages = Arc::new(Mutex::new(Vec::new()));
    28→        let messages_clone = messages.clone();
    29→
    30→        // Spawn collector task
    31→        tokio::spawn(async move {
    32→            while let Some(trace) = rx.recv().await {
    33→                let mut msgs = messages_clone.lock().expect("tracer lock poisoned");
    34→                msgs.push(trace);
    35→            }
    36→        });
    37→
    38→        (Self { messages }, tx)
    39→    }
    40→
    41→    /// Get all collected messages
    42→    pub fn messages(&self) -> Vec<MessageTrace> {
    43→        let msgs = self.messages.lock().expect("tracer lock poisoned");
    44→        msgs.clone()
    45→    }
    46→
    47→    /// Get message type name sequence
    48→    pub fn sequence(&self) -> Vec<&'static str> {
    49→        let msgs = self.messages.lock().expect("tracer lock poisoned");
    50→        msgs.iter().map(|m| m.msg_name).collect()
    51→    }
    52→
    53→    /// Assert exact message sequence matches
    54→    pub fn assert_sequence(&self, expected: &[&str]) {
    55→        let actual = self.sequence();
    56→        assert_eq!(
    57→            actual, expected,
    58→            "\nMessage sequence mismatch!\nExpected: {:?}\nActual:   {:?}\n\nFull trace:\n{}",
    59→            expected, actual, self.format_trace()
    60→        );
    61→    }
    62→
    63→    /// Assert expected messages appear in order (other messages allowed in between)
    64→    pub fn assert_contains_sequence(&self, expected: &[&str]) {
    65→        let msgs = self.messages.lock().expect("tracer lock poisoned");
    66→        let mut expected_iter = expected.iter();
    67→        let mut current = expected_iter.next();
    68→
    69→        for msg in msgs.iter() {
    70→            if let Some(exp) = current {
    71→                if msg.msg_name == *exp {
    72→                    current = expected_iter.next();
    73→                }
    74→            }
    75→        }
    76→
    77→        if current.is_some() {
    78→            let actual = self.sequence();
    79→            panic!(
    80→                "\nExpected subsequence not found!\nExpected: {:?}\nActual:   {:?}\n\nFull trace:\n{}",
    81→                expected, actual, self.format_trace()
    82→            );
    83→        }
    84→    }
    85→
    86→    /// Assert a message type appears exactly N times
    87→    pub fn assert_count(&self, msg_type: &str, expected: usize) {
    88→        let actual = self.messages_of_type(msg_type).len();
    89→        assert_eq!(
    90→            actual, expected,
    91→            "\nCount mismatch for '{}'! Expected: {}, Actual: {}\n\nFull trace:\n{}",
    92→            msg_type, expected, actual, self.format_trace()
    93→        );
    94→    }
    95→
    96→    /// Get messages of a specific type
    97→    pub fn messages_of_type(&self, type_name: &str) -> Vec<MessageTrace> {
    98→        let msgs = self.messages.lock().expect("tracer lock poisoned");
    99→        msgs.iter()
   100→            .filter(|m| m.msg_name == type_name)
   101→            .cloned()
   102→            .collect()
   103→    }
   104→
   105→    /// Format trace for debug output
   106→    pub fn format_trace(&self) -> String {
   107→        let msgs = self.messages.lock().expect("tracer lock poisoned");
   108→        let start = msgs.first().map(|m| m.timestamp);
   109→
   110→        msgs.iter()
   111→            .map(|m| {
   112→                let elapsed = start
   113→                    .map(|s| m.timestamp.duration_since(s))
   114→                    .unwrap_or_default();
   115→                let dir = match m.direction {
   116→                    TraceDirection::Sent => "->",
   117→                    TraceDirection::Received => "<-",
   118→                };
   119→                format!(
   120→                    "[{:>6.3}s] {} {} (node={}, peer={})",
   121→                    elapsed.as_secs_f64(),
   122→                    dir,
   123→                    m.msg_name,
   124→                    m.node_id,
   125→                    m.peer_node_id,
   126→                )
   127→            })
   128→            .collect::<Vec<_>>()
   129→            .join("\n")
   130→    }
   131→
   132→    /// Print trace to stdout
   133→    pub fn dump(&self) {
   134→        println!(
   135→            "\n=== Message Trace ===\n{}\n=====================",
   136→            self.format_trace()
   137→        );
   138→    }
   139→}
