     1→//! E-Commerce derivation tests
     2→//!
     3→//! Tests the derivation pipeline: customer order → node derivation → orders_summary.
     4→//!
     5→//! **Bug coverage**: "order made on viewer not visible on owner" — derivation
     6→//! on_source_change pattern matching fails because Scribe normalizes layer names
     7→//! to bare form but Lua registers prefixed patterns.
     8→
     9→use std::time::Duration;
    10→
    11→use anyhow::Result;
    12→use tokio::time::sleep;
    13→
    14→use butler::{PageUpdate, ScribeMessage};
    15→use lua_runtime::{LuaRuntime, LuaRuntimeConfig, LuaCommand, ActorScribeHandle};
    16→
    17→use crate::fixtures::{init_tracing, app_dir};
    18→use crate::scenario::Scenario;
    19→
    20→/// Simulate what kunki's NodeRuntimeManager does: get app files, find entry_node,
    21→/// start LuaRuntime with init.lua + node.lua, and set up PageUpdate bridge
    22→async fn start_node_runtime(
    23→    butler: &std::sync::Arc<butler::Butler>,
    24→    page_id: &str,
    25→    scribe_ref: &ractor::ActorRef<ScribeMessage>,
    26→) -> Result<(std::thread::JoinHandle<()>, tokio::sync::mpsc::Sender<LuaCommand>)> {
    27→    let apps = butler.apps().list(page_id)
    28→        .map_err(|e| anyhow::anyhow!("Failed to list apps: {}", e))?;
    29→
    30→    if apps.is_empty() {
    31→        return Err(anyhow::anyhow!("Page has no apps"));
    32→    }
    33→
    34→    for app_name in &apps {
    35→        let (tx, rx) = tokio::sync::oneshot::channel();
    36→        scribe_ref.cast(ScribeMessage::GetAppFiles {
    37→            app_name: app_name.clone(),
    38→            reply: tx,
    39→        }).map_err(|e| anyhow::anyhow!("Failed to get app files: {:?}", e))?;
    40→
    41→        let files = rx.await?
    42→            .map_err(|e| anyhow::anyhow!("GetAppFiles error: {}", e))?;
    43→
    44→        let manifest_str = match files.get("manifest.json") {
    45→            Some(m) => m,
    46→            None => continue,
    47→        };
    48→
    49→        let manifest: serde_json::Value = serde_json::from_str(manifest_str)?;
    50→        let entry_node = match manifest.get("entry_node").and_then(|v| v.as_str()) {
    51→            Some(e) => e.to_string(),
    52→            None => continue,
    53→        };
    54→
    55→        let node_script = files.get(&entry_node)
    56→            .ok_or_else(|| anyhow::anyhow!("Node script '{}' not found", entry_node))?;
    57→
    58→        let init_code = files.get("init.lua").cloned();
    59→        let lua_code = match &init_code {
    60→            Some(init) => format!("{}\n{}", init, node_script),
    61→            None => node_script.clone(),
    62→        };
    63→
    64→        let identity = butler.user_info().await?;
    65→
    66→        let (thread, cmd_tx) = LuaRuntime::spawn(LuaRuntimeConfig {
    67→            page_id: page_id.to_string(),
    68→            app_name: app_name.clone(),
    69→            scribe: ActorScribeHandle::new(scribe_ref.clone()),
    70→            user_did: identity.did.clone(),
    71→            user_name: "node".to_string(),
    72→            user_role: "node".to_string(),
    73→            lua_code,
    74→            ui_enabled: false,
    75→            ui_tx: None,
    76→            query_tx: None,
    77→            navigate_tx: None,
    78→        }).map_err(|e| anyhow::anyhow!("Failed to spawn LuaRuntime: {}", e))?;
    79→
    80→        // Trigger initial derivation rebuild (same as kunki)
    81→        if init_code.is_some() {
    82→            cmd_tx.send(LuaCommand::RebuildDerivation).await
    83→                .map_err(|e| anyhow::anyhow!("Failed to send RebuildDerivation: {}", e))?;
    84→        }
    85→
    86→        // Subscribe to page updates and set up bridge (same as kunki's node_runtime)
    87→        let (page_update_tx, mut page_update_rx) = tokio::sync::mpsc::channel(256);
    88→        scribe_ref.cast(ScribeMessage::SubscribeToPageUpdates {
    89→            tx: page_update_tx,
    90→        }).map_err(|e| anyhow::anyhow!("Failed to subscribe to page updates: {:?}", e))?;
    91→
    92→        let bridge_cmd_tx = cmd_tx.clone();
    93→        tokio::spawn(async move {
    94→            while let Some(update) = page_update_rx.recv().await {
    95→                match update {
    96→                    PageUpdate::LayerChanged { layer, ops, full_data, delta, created, .. } => {
    97→                        if created {
    98→                            let _ = bridge_cmd_tx.send(LuaCommand::LayerDiscovered {
    99→                                layer_name: layer,
   100→                            }).await;
   101→                        } else {
   102→                            let _ = bridge_cmd_tx.send(LuaCommand::LoroChanged {
   103→                                layer_name: layer,
   104→                                ops,
   105→                                delta,
   106→                                full_data,
   107→                            }).await;
   108→                        }
   109→                    }
   110→                    _ => {}
   111→                }
   112→            }
   113→        });
   114→
   115→        return Ok((thread, cmd_tx));
   116→    }
   117→
   118→    Err(anyhow::anyhow!("No app with entry_node found"))
   119→}
