   121→/// Full ecomm derivation pipeline with automatic trigger
   122→///
   123→/// After customer writes an order, the node's derivation is automatically
   124→/// triggered via on_source_change and produces orders_summary.
   125→#[tokio::test]
   126→async fn test_ecomm_derivation_auto_trigger() -> Result<()> {
   127→    init_tracing();
   128→
   129→    let ecomm_dir = app_dir("my-shop");
   130→    assert!(ecomm_dir.exists(), "sample_apps/my-shop must exist: {:?}", ecomm_dir);
   131→
   132→    let mut s = Scenario::builder()
   133→        .app("my-shop")
   134→        .published()
   135→        .build()
   136→        .await?;
   137→
   138→    let page_id = s.space().page_id.clone();
   139→    sleep(Duration::from_millis(500)).await;
   140→
   141→    // Node: start runtime with PageUpdate bridge
   142→    let node_scribe = s.node().butler.open_page(&page_id).await?;
   143→    let (_thread, cmd_tx) = start_node_runtime(
   144→        &s.node().butler, &page_id, &node_scribe,
   145→    ).await?;
   146→
   147→    // Give runtime time to initialize derivation rules
   148→    sleep(Duration::from_millis(500)).await;
   149→
   150→    // Customer writes an order directly to node's scribe
   151→    let customer_did = "did:key:z6MkTestCustomer";
   152→    let order_layer = format!("orders/{}", customer_did);
   153→
   154→    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
   155→    node_scribe.cast(ScribeMessage::EnsureLoroList {
   156→        layer_name: order_layer.clone(),
   157→        reply: reply_tx,
   158→    }).map_err(|e| anyhow::anyhow!("Failed to ensure list: {:?}", e))?;
   159→    reply_rx.await??;
   160→
   161→    node_scribe.cast(ScribeMessage::ListPush {
   162→        layer_name: order_layer.clone(),
   163→        path: String::new(),
   164→        item: serde_json::json!({
   165→            "id": "order-001",
   166→            "status": "submitted",
   167→            "total": 199.99,
   168→            "quantity": 2,
   169→            "created_at": 1700000000,
   170→            "submitted_at": 1700000060,
   171→            "updated_at": 1700000060,
   172→        }),
   173→    }).map_err(|e| anyhow::anyhow!("Failed to push order: {:?}", e))?;
   174→
   175→    // Derivation should auto-trigger via PageUpdate bridge
   176→    sleep(Duration::from_secs(2)).await;
   177→
   178→    // Verify: derived/orders_summary should have the order
   179→    let (tx, rx) = tokio::sync::oneshot::channel();
   180→    node_scribe.cast(ScribeMessage::GetLayerJson {
   181→        layer_name: "derived/orders_summary".to_string(),
   182→        reply: tx,
   183→    }).map_err(|e| anyhow::anyhow!("Failed to get layer: {:?}", e))?;
   184→
   185→    let summary = rx.await?;
   186→    let summary_data = summary.expect("derived/orders_summary should exist");
   187→    let summary_obj = summary_data.as_object()
   188→        .expect("orders_summary should be a map");
   189→
   190→    assert!(
   191→        !summary_obj.is_empty(),
   192→        "derived/orders_summary should have entries — derivation should auto-trigger on layer changes"
   193→    );
   194→
   195→    let order_entry = summary_obj.get("order-001")
   196→        .expect("Should have order-001 in summary");
   197→    assert_eq!(order_entry.get("status").and_then(|v| v.as_str()), Some("submitted"));
   198→    assert_eq!(order_entry.get("total").and_then(|v| v.as_f64()), Some(199.99));
   199→    assert_eq!(
   200→        order_entry.get("customer").and_then(|v| v.as_str()),
   201→        Some(customer_did),
   202→        "Derived entry should have customer DID"
   203→    );
   204→
   205→    let _ = cmd_tx.send(LuaCommand::Shutdown).await;
   206→    s.shutdown().await;
   207→    Ok(())
   208→}
