     1→//! Dynamic Layer Storage Operations
     2→//!
     3→//! Three tables for the two-tier permit model:
     4→//! - **Layer permits**: per-peer per-dynamic-layer UCAN tokens
     5→//! - **Dynamic layer metadata**: tracks which layers are dynamic (for reconnect)
     6→//! - **Viewer layer consents**: per-viewer per-layer consent tokens
     7→
     8→use redb::{ReadableTable, ReadableDatabase};
     9→use crate::error::Result;
    10→use tracing::instrument;
    11→use super::{
    12→    RedbStore, LAYER_PERMITS, DYNAMIC_LAYER_META, VIEWER_LAYER_CONSENTS,
    13→};
    14→
    15→impl RedbStore {
    16→    // ── Layer Permit Operations ──────────────────────────────────────────
    17→    // Key: {page_id}/{user_did}/{layer_name} → permit token string
    18→    // Multiple permits per peer per page (one per dynamic layer)
    19→
    20→    /// Store a layer permit for a peer (additive).
    21→    ///
    22→    /// **Context**: Node detected new dynamic layer, issued permit for peer.
    23→    #[instrument(skip_all)]
    24→    pub fn store_layer_permit(
    25→        &self,
    26→        page_id: &str,
    27→        user_did: &str,
    28→        layer_name: &str,
    29→        permit_token: &str,
    30→    ) -> Result<()> {
    31→        let key = format!("{}/{}/{}", page_id, user_did, layer_name);
    32→        let write_txn = self.db.begin_write()?;
    33→        {
    34→            let mut table = write_txn.open_table(LAYER_PERMITS)?;
    35→            table.insert(key.as_str(), permit_token)?;
    36→        }
    37→        write_txn.commit()?;
    38→        Ok(())
    39→    }
    40→
    41→    /// Load all layer permits for a peer on a page.
    42→    ///
    43→    /// **Context**: Used during reconnect to determine which dynamic layers peer has access to.
    44→    /// **Returns**: Vec of (layer_name, permit_token) tuples.
    45→    #[instrument(skip_all)]
    46→    pub fn get_layer_permits(
    47→        &self,
    48→        page_id: &str,
    49→        user_did: &str,
    50→    ) -> Result<Vec<(String, String)>> {
    51→        let prefix = format!("{}/{}/", page_id, user_did);
    52→        let read_txn = self.db.begin_read()?;
    53→        let table = read_txn.open_table(LAYER_PERMITS)?;
    54→
    55→        let mut permits = Vec::new();
    56→        for result in table.range(prefix.as_str()..)? {
    57→            let (key, value) = result?;
    58→            let key_str = key.value();
    59→
    60→            if !key_str.starts_with(&prefix) {
    61→                break;
    62→            }
    63→
    64→            if let Some(layer_name) = key_str.strip_prefix(&prefix) {
    65→                permits.push((layer_name.to_string(), value.value().to_string()));
    66→            }
    67→        }
    68→        Ok(permits)
    69→    }
    70→
    71→    /// Remove a layer permit for a peer.
    72→    ///
    73→    /// **Context**: Called during revocation or cleanup.
    74→    #[instrument(skip_all)]
    75→    pub fn remove_layer_permit(
    76→        &self,
    77→        page_id: &str,
    78→        user_did: &str,
    79→        layer_name: &str,
    80→    ) -> Result<bool> {
    81→        let key = format!("{}/{}/{}", page_id, user_did, layer_name);
    82→        let write_txn = self.db.begin_write()?;
    83→        let removed = {
    84→            let mut table = write_txn.open_table(LAYER_PERMITS)?;
    85→            let result = table.remove(key.as_str())?.is_some();
    86→            result
    87→        };
    88→        write_txn.commit()?;
    89→        Ok(removed)
    90→    }
    91→
    92→    /// Check if a peer has a layer permit for a specific dynamic layer.
    93→    #[instrument(skip_all)]
    94→    pub fn has_layer_permit(
    95→        &self,
    96→        page_id: &str,
    97→        user_did: &str,
    98→        layer_name: &str,
    99→    ) -> Result<bool> {
   100→        let key = format!("{}/{}/{}", page_id, user_did, layer_name);
   101→        let read_txn = self.db.begin_read()?;
   102→        let table = read_txn.open_table(LAYER_PERMITS)?;
   103→        let result = table.get(key.as_str())?.is_some();
   104→        Ok(result)
   105→    }
   106→
   107→    // ── Dynamic Layer Metadata Operations ────────────────────────────────
   108→    // Key: {page_id}/{layer_name} → meta JSON bytes
   109→    // Tracks which layers are dynamic (schema, creator, grant type)
   110→
   111→    /// Record that a layer is dynamic.
   112→    ///
   113→    /// **Context**: Node detected new dynamic layer from peer sync.
   114→    /// Stores metadata for reconnect enumeration and permit recomputation.
   115→    #[instrument(skip_all)]
   116→    pub fn store_dynamic_layer_meta(
   117→        &self,
   118→        page_id: &str,
   119→        layer_name: &str,
   120→        meta_json: &[u8],
   121→    ) -> Result<()> {
   122→        let key = format!("{}/{}", page_id, layer_name);
   123→        let write_txn = self.db.begin_write()?;
   124→        {
   125→            let mut table = write_txn.open_table(DYNAMIC_LAYER_META)?;
   126→            table.insert(key.as_str(), meta_json)?;
   127→        }
   128→        write_txn.commit()?;
   129→        Ok(())
   130→    }
   131→
   132→    /// List all dynamic layers for a page.
   133→    ///
   134→    /// **Context**: Used during peer reconnect to enumerate dynamic layers
   135→    /// and compute which permits are missing.
   136→    /// **Returns**: Vec of (layer_name, meta_json_bytes) tuples.
   137→    #[instrument(skip_all)]
   138→    pub fn list_dynamic_layers(
   139→        &self,
   140→        page_id: &str,
   141→    ) -> Result<Vec<(String, Vec<u8>)>> {
   142→        let prefix = format!("{}/", page_id);
   143→        let read_txn = self.db.begin_read()?;
   144→        let table = read_txn.open_table(DYNAMIC_LAYER_META)?;
   145→
   146→        let mut layers = Vec::new();
   147→        for result in table.range(prefix.as_str()..)? {
   148→            let (key, value) = result?;
   149→            let key_str = key.value();
   150→
   151→            if !key_str.starts_with(&prefix) {
   152→                break;
   153→            }
   154→
   155→            if let Some(layer_name) = key_str.strip_prefix(&prefix) {
   156→                layers.push((layer_name.to_string(), value.value().to_vec()));
   157→            }
   158→        }
   159→        Ok(layers)
   160→    }
   161→
   162→    /// Get metadata for a specific dynamic layer.
   163→    #[instrument(skip_all)]
   164→    pub fn get_dynamic_layer_meta(
   165→        &self,
   166→        page_id: &str,
   167→        layer_name: &str,
   168→    ) -> Result<Option<Vec<u8>>> {
   169→        let key = format!("{}/{}", page_id, layer_name);
   170→        let read_txn = self.db.begin_read()?;
   171→        let table = read_txn.open_table(DYNAMIC_LAYER_META)?;
   172→
   173→        match table.get(key.as_str())? {
   174→            Some(guard) => Ok(Some(guard.value().to_vec())),
   175→            None => Ok(None),
   176→        }
   177→    }
   178→
   179→    // ── Viewer Layer Consent Operations ──────────────────────────────────
   180→    // Key: {viewer_did}/{page_id}/{layer_name} → consent token string
   181→    // Tracks per-layer consent from viewer (dynamic layers need separate consent)
   182→
   183→    /// Store viewer's consent for a dynamic layer.
   184→    ///
   185→    /// **Context**: Node receives LayerConsentGrant from viewer.
   186→    /// Required before node can sync that dynamic layer to the viewer.
   187→    #[instrument(skip_all)]
   188→    pub fn store_viewer_layer_consent(
   189→        &self,
   190→        viewer_did: &str,
   191→        page_id: &str,
   192→        layer_name: &str,
   193→        consent_token: &str,
   194→    ) -> Result<()> {
   195→        let key = format!("{}/{}/{}", viewer_did, page_id, layer_name);
   196→        let write_txn = self.db.begin_write()?;
   197→        {
   198→            let mut table = write_txn.open_table(VIEWER_LAYER_CONSENTS)?;
   199→            table.insert(key.as_str(), consent_token)?;
   200→        }
   201→        write_txn.commit()?;
   202→        Ok(())
   203→    }
   204→
   205→    /// Check if viewer has consented to a dynamic layer.
   206→    ///
   207→    /// **Context**: Node checks before syncing a dynamic layer to a peer.
   208→    /// Both layer permit AND consent must be present before sync.
   209→    #[instrument(skip_all)]
   210→    pub fn has_viewer_layer_consent(
   211→        &self,
   212→        viewer_did: &str,
   213→        page_id: &str,
   214→        layer_name: &str,
   215→    ) -> Result<bool> {
   216→        let key = format!("{}/{}/{}", viewer_did, page_id, layer_name);
   217→        let read_txn = self.db.begin_read()?;
   218→        let table = read_txn.open_table(VIEWER_LAYER_CONSENTS)?;
   219→        Ok(table.get(key.as_str())?.is_some())
   220→    }
   221→
   222→    /// Get viewer's layer consent token.
   223→    ///
   224→    /// **Context**: Node needs consent token for proof chain during sync.
   225→    #[instrument(skip_all)]
   226→    pub fn get_viewer_layer_consent(
   227→        &self,
   228→        viewer_did: &str,
   229→        page_id: &str,
   230→        layer_name: &str,
   231→    ) -> Result<Option<String>> {
   232→        let key = format!("{}/{}/{}", viewer_did, page_id, layer_name);
   233→        let read_txn = self.db.begin_read()?;
   234→        let table = read_txn.open_table(VIEWER_LAYER_CONSENTS)?;
   235→
   236→        match table.get(key.as_str())? {
   237→            Some(guard) => Ok(Some(guard.value().to_string())),
   238→            None => Ok(None),
   239→        }
   240→    }
   241→}
