     1→//! Presence heartbeat and multi-user sync tests
     2→//!
     3→//! Verifies that:
     4→//! 1. Presence layer updates propagate between users via node
     5→//! 2. When a user disconnects, their presence becomes stale
     6→//! 3. Heartbeat interval updates last_seen
     7→
     8→use std::collections::HashMap;
     9→use std::thread::JoinHandle;
    10→use std::time::Duration;
    11→
    12→use anyhow::Result;
    13→use ractor::ActorRef;
    14→use tokio::sync::mpsc;
    15→use tokio::time::sleep;
    16→
    17→use butler::ScribeMessage;
