    22→
    23→/// Holds a running Lua app with presence
    24→struct PresenceApp {
    25→    cmd_tx: mpsc::Sender<LuaCommand>,
    26→    runtime_handle: JoinHandle<()>,
    27→}
    28→
    29→impl PresenceApp {
    30→    async fn shutdown(self) {
    31→        let _ = self.cmd_tx.send(LuaCommand::Shutdown).await;
    32→        let _ = self.runtime_handle.join();
    33→    }
    34→}
    35→
    36→/// Spawn a Lua runtime with fast presence heartbeat (2 seconds)
    37→fn spawn_presence_app(
    38→    page_id: &str,
    39→    user_did: &str,
    40→    user_name: &str,
    41→    scribe_ref: ActorRef<ScribeMessage>,
    42→) -> Result<PresenceApp> {
    43→    let lua_code = format!(
    44→        r#"
    45→local page_id = "{page_id}"
    46→local my_did = "{user_did}"
    47→local my_name = "{user_name}"
    48→
    49→local presence_layer = scribe:map(page_id .. "/presence")
    50→
    51→local function write_presence()
    52→    presence_layer:set(my_did, {{
    53→        did = my_did,
    54→        status = "online",
    55→        name = my_name,
    56→        last_seen = os.time(),
    57→    }})
    58→end
    59→
    60→function on_init()
    61→    write_presence()
    62→    timer.setInterval(2000, function()
    63→        write_presence()
    64→    end)
    65→end
    66→"#,
    67→        page_id = page_id,
    68→        user_did = user_did,
    69→        user_name = user_name
    70→    );
    71→
    72→    let (runtime_handle, cmd_tx) = LuaRuntime::spawn(LuaRuntimeConfig {
    73→        page_id: page_id.to_string(),
    74→        app_name: format!("presence-{}", user_name),
    75→        scribe: ActorScribeHandle::new(scribe_ref),
    76→        user_did: user_did.to_string(),
    77→        user_name: user_name.to_string(),
    78→        user_role: "collaborator".to_string(),
    79→        lua_code,
    80→        ui_enabled: false,
    81→        ui_tx: None,
    82→        query_tx: None,
    83→        navigate_tx: None,
    84→    })
    85→    .map_err(|e| anyhow::anyhow!("Failed to spawn Lua runtime: {}", e))?;
    86→
    87→    Ok(PresenceApp { cmd_tx, runtime_handle })
    88→}
    89→
    90→/// Query presence layer and return all entries
    91→async fn query_presence(
    92→    scribe_ref: &ActorRef<ScribeMessage>,
    93→    layer_name: &str,
    94→) -> Result<HashMap<String, serde_json::Value>> {
    95→    let (tx, rx) = tokio::sync::oneshot::channel();
    96→    scribe_ref
    97→        .cast(ScribeMessage::GetLayerJson {
    98→            layer_name: layer_name.to_string(),
    99→            reply: tx,
   100→        })
   101→        .map_err(|e| anyhow::anyhow!("Failed to send GetLayerJson: {:?}", e))?;
   102→
   103→    let data = rx
   104→        .await
   105→        .map_err(|_| anyhow::anyhow!("Failed to receive response"))?
   106→        .ok_or_else(|| anyhow::anyhow!("Presence layer '{}' does not exist", layer_name))?;
   107→
   108→    let map: HashMap<String, serde_json::Value> = data
   109→        .as_object()
   110→        .map(|obj| obj.iter().map(|(k, v)| (k.clone(), v.clone())).collect())
   111→        .unwrap_or_default();
   112→
   113→    Ok(map)
   114→}
   115→
   116→/// Count online users (those with last_seen within threshold seconds)
   117→fn count_online(presence: &HashMap<String, serde_json::Value>, threshold_secs: i64) -> usize {
   118→    let now = std::time::SystemTime::now()
   119→        .duration_since(std::time::UNIX_EPOCH)
   120→        .unwrap()
   121→        .as_secs() as i64;
   122→
   123→    presence
   124→        .values()
   125→        .filter(|entry| {
   126→            entry
   127→                .get("last_seen")
   128→                .and_then(|v| v.as_i64())
   129→                .map(|last_seen| now - last_seen < threshold_secs)
   130→                .unwrap_or(false)
   131→        })
   132→        .count()
   133→}
   134→
   135→/// Local presence write + stale detection
   136→///
   137→/// **Note**: Cross-peer presence sync requires a presence layer in the permit
   138→/// template. The osvauld-demos app doesn't define one, so this test verifies
   139→/// local presence behavior: write, heartbeat, and stale detection on a single peer.
   140→///
   141→/// Spawns two presence apps on the owner's Scribe. Verifies both entries exist,
   142→/// kills one app, and checks that its presence becomes stale.
   143→#[tokio::test]
   144→async fn test_presence_local_stale_detection() -> Result<()> {
   145→    init_tracing();
   146→
   147→    let mut s = Scenario::builder()
   148→        .app("osvauld-demos")
   149→        .published()
   150→        .build()
   151→        .await?;
   152→
   153→    let page_id = s.space().page_id.clone();
   154→    let owner_info = s.owner().butler.user_info().await?;
   155→    let scribe_ref = s.owner().butler.open_page(&page_id).await?;
   156→
   157→    // Spawn two presence apps writing to the same Scribe (simulating multi-user)
   158→    let app1 = spawn_presence_app(&page_id, &owner_info.did, "user1", scribe_ref.clone())?;
   159→    let app2 = spawn_presence_app(&page_id, "did:key:z6MkTestUser2", "user2", scribe_ref.clone())?;
   160→
   161→    // Wait for initial writes
   162→    sleep(Duration::from_secs(2)).await;
   163→
   164→    let presence_layer = format!("{}/presence", page_id);
   165→    let presence = query_presence(&scribe_ref, &presence_layer).await?;
   166→
   167→    assert_eq!(presence.len(), 2, "Should have 2 presence entries");
   168→    assert_eq!(count_online(&presence, 10), 2, "Both users should be online");
   169→
   170→    // Kill user2's app
   171→    app2.shutdown().await;
   172→
   173→    // Wait for user2 to become stale (>10 seconds without heartbeat)
   174→    sleep(Duration::from_secs(15)).await;
   175→
   176→    let presence = query_presence(&scribe_ref, &presence_layer).await?;
   177→    assert_eq!(presence.len(), 2, "Should still have 2 presence entries");
   178→    assert_eq!(count_online(&presence, 10), 1, "Only 1 user should be online (user2 is stale)");
   179→
   180→    app1.shutdown().await;
   181→    s.shutdown().await;
   182→
   183→    Ok(())
   184→}
