   186→/// Fast heartbeat test — verify heartbeat updates last_seen
   187→#[tokio::test]
   188→async fn test_presence_heartbeat_fast() -> Result<()> {
   189→    init_tracing();
   190→
   191→    let mut s = Scenario::builder()
   192→        .app("osvauld-demos")
   193→        .published()
   194→        .build()
   195→        .await?;
   196→
   197→    let page_id = s.space().page_id.clone();
   198→    let owner_info = s.owner().butler.user_info().await?;
   199→    let user_did = owner_info.did.clone();
   200→
   201→    let scribe_ref = s.owner().butler.open_page(&page_id).await?;
   202→    let app = spawn_presence_app(&page_id, &user_did, "test_user", scribe_ref.clone())?;
   203→
   204→    // Wait for initial write
   205→    sleep(Duration::from_secs(1)).await;
   206→
   207→    // Query initial
   208→    let presence_layer = format!("{}/presence", page_id);
   209→    let presence = query_presence(&scribe_ref, &presence_layer).await?;
   210→    let initial_last_seen = presence
   211→        .get(&user_did)
   212→        .and_then(|v| v.get("last_seen"))
   213→        .and_then(|v| v.as_i64())
   214→        .expect("Should have last_seen");
   215→
   216→    // Wait for heartbeat (2s interval + buffer)
   217→    sleep(Duration::from_secs(3)).await;
   218→
   219→    // Query updated
   220→    let presence = query_presence(&scribe_ref, &presence_layer).await?;
   221→    let updated_last_seen = presence
   222→        .get(&user_did)
   223→        .and_then(|v| v.get("last_seen"))
   224→        .and_then(|v| v.as_i64())
