```rust
#[tokio::test]
async fn test_owner_layer_sync_to_node() -> Result<()> {
    init_tracing();

    // 1. Setup: published scenario (owner+node connected, page imported)
    let mut s = Scenario::builder()
        .app("osvauld-demos")
        .published()
        .build()
        .await?;

    let page_id = s.space().page_id.clone();
    sleep(Duration::from_millis(500)).await;  // Allow subscriptions

    // 2. Owner opens page and writes data
    let owner_scribe = s.owner().butler.open_page(&page_id).await?;

    // Ensure layer exists
    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
    owner_scribe.cast(ScribeMessage::EnsureLoroMap {
        layer_name: "reactions".to_string(),
        reply: reply_tx,
    })?;
    reply_rx.await??;

    // Write data
    owner_scribe.cast(ScribeMessage::MapInsert {
        layer_name: "reactions".to_string(),
        path: String::new(),
        key: "msg1".to_string(),
        value: serde_json::json!({"emoji": "thumbs_up"}),
    })?;

    // 3. Verify node receives data
    let node_data = wait_for_layer_data(
        &s.node().butler,
        &page_id,
        "reactions",
        Duration::from_secs(10),
    ).await?;

    assert!(!node_data.is_empty());

    s.shutdown().await;
    Ok(())
}
```

