     1→//! Apply update handling for Scribe actor
     2→//!
     3→//! Handles incoming layer updates (local or remote), including permission checks,
     4→//! validation, and CRDT merge.
     5→//!
     6→//! Note: Derivation is now handled externally by kunki/LuaRuntime which
     7→//! subscribes to PageUpdate::LayerChanged events.
     8→//!
     9→//! ## Key Types
    10→//!
    11→//! - `UpdateContext`: Computed context for an incoming update - all decisions made upfront
    12→//! - `ApplyOutcome`: Result of applying an update (Applied or Rejected)
    13→
    14→use logging_utils::ShortLayer;
    15→use tracing::{debug, error, info, warn, instrument};
    16→
    17→use domains::Layer;
    18→
    19→use super::broadcast::{broadcast_update, notify_layer_discovered};
    20→use crate::layer_unit::LayerUnit;
    21→use crate::loro_observer::{set_pending_update_source, clear_pending_update_source, setup_layer_observer};
    22→use crate::permit::{Permissions, PermitContext};
    23→use crate::state::ScribeState;
    24→use crate::JsonOp;
    25→use crate::state::normalize_layer_name;
    26→
    27→// Update Context - Centralized Decision Logic
    28→
    29→/// Context for an incoming update - computed once, used throughout
    30→///
    31→/// **Design**: All decisions about how to handle an update are computed upfront.
    32→/// This makes the apply flow clearer and easier to test.
    33→#[derive(Debug)]
    34→pub struct UpdateContext {
    35→    /// Layer being updated
    36→    pub layer_name: String,
    37→    /// Source of update: None = local, Some = remote peer (user_did, device_id)
    38→    pub from_peer: Option<(String, String)>,
    39→    /// Role of the peer (for validation) - "node", "owner", "viewer", etc.
    40→    pub peer_role: String,
    41→
    42→    /// Is this a remote update (from a peer)?
    43→    pub is_remote: bool,
    44→    /// Is this layer local-only (never synced)?
    45→    pub is_local_only: bool,
    46→    /// Does this update need Lua validation?
    47→    pub should_validate: bool,
    48→    /// Should we broadcast after applying?
    49→    pub should_broadcast: bool,
    50→    /// Is this a new layer (needs creation)?
    51→    pub is_new_layer: bool,
    52→}
    53→
    54→impl UpdateContext {
    55→    /// Create context for an incoming update
    56→    ///
    57→    /// **Context**: Computes all decisions based on state and update metadata
    58→    /// **Note**: Permission checks are done separately (may reject before context is useful)
    59→    pub fn new(
    60→        state: &ScribeState,
    61→        layer_name: &str,
    62→        from_peer: Option<(String, String)>,
    63→    ) -> Self {
    64→        let is_remote = from_peer.is_some();
    65→        let is_local_only = Permissions::is_local_only(layer_name);
    66→        let is_new_layer = !state.units.contains_key(layer_name);
    67→
    68→        // Determine peer role for validation
    69→        let peer_role = if let Some(ref peer) = from_peer {
    70→            get_peer_role(state, &peer.0)
    71→        } else {
    72→            "local".to_string()
    73→        };
    74→
    75→        // Should validate: remote update AND ValidationHandle exists
    76→        let should_validate = is_remote && state.validation_handle.is_some();
    77→
    78→        // Should broadcast: remote update (local updates use observer)
    79→        let should_broadcast = is_remote;
    80→
    81→        Self {
    82→            layer_name: layer_name.to_string(),
    83→            from_peer,
    84→            peer_role,
    85→            is_remote,
    86→            is_local_only,
    87→            should_validate,
    88→            should_broadcast,
    89→            is_new_layer,
    90→        }
    91→    }
    92→}
    93→
    94→// Apply Outcome - Event-Driven Pattern
    95→
    96→/// Outcome of applying an update
    97→///
    98→/// **Design**: Separates the "what happened" from "what to do next"
    99→/// This enables cleaner outcome handling and better error messages
   100→#[derive(Debug)]
   101→pub enum ApplyOutcome {
   102→    /// Update was successfully applied
   103→    Applied {
   104→        /// Layer that was updated
   105→        layer_name: String,
   106→        /// Ops extracted from update (for derivation)
   107→        ops: Vec<JsonOp>,
   108→        /// Was a new layer created?
   109→        created_layer: bool,
   110→    },
   111→    /// Update was rejected
   112→    Rejected {
   113→        /// Reason for rejection
   114→        reason: String,
   115→    },
   116→}
   117→
   118→// Apply Update Handler
   119→
   120→/// Handle layer update (local or remote)
   121→///
   122→/// **Context**: Edit from UI or sync push from peer
   123→/// **We do**: Permission check, validation, CRDT merge
   124→/// **Broadcast**: Handled automatically by Loro observer (set up at startup)
   125→/// **Returns**: Ok(()) on success, Err(message) on failure
   126→#[instrument(skip(state, update, permit), fields(page_id = %state.page_id, layer = %ShortLayer(layer_name)))]
   127→pub async fn handle_apply_update(
   128→    state: &mut ScribeState,
   129→    layer_name: &str,
   130→    update: &[u8],
   131→    from_peer: Option<(String, String)>,
   132→    permit: Option<&str>,
   133→) -> std::result::Result<(), String> {
   134→    let _ = permit; // Permit is used for subscription in Courier, not here
   135→
   136→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
   137→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
   138→    let layer_name = layer_name.as_str();
   139→
   140→    // Build context - computes all decisions upfront
   141→    let ctx = UpdateContext::new(state, layer_name, from_peer.clone());
   142→
   143→    // Step 1: Apply the update (with permission checks, validation, CRDT merge)
   144→    let outcome = apply_update_core(state, &ctx, update).await;
   145→
   146→    // Step 2: Handle the outcome
   147→    match outcome {
   148→        ApplyOutcome::Applied { layer_name, ops: _, created_layer } => {
   149→            // Mark layer as dirty for persistence
   150→            if let Some(unit) = state.units.get_mut(&layer_name) {
   151→                unit.mark_dirty();
   152→            }
   153→            debug!(layer = %layer_name, created = created_layer, "Update applied successfully");
   154→
   155→            // Post-apply handling for remote updates
   156→            if ctx.is_remote {
   157→                handle_post_apply(state, &layer_name, ctx.from_peer.clone()).await;
   158→            }
   159→
   160→            // Update sender's vector
   161→            if let Some(ref peer) = ctx.from_peer {
   162→                update_sender_vector(state, peer, &layer_name);
   163→            }
   164→
   165→            // Broadcast to eligible subscribers
   166→            if ctx.should_broadcast {
   167→                broadcast_update(state, &layer_name, ctx.from_peer.as_ref()).await;
   168→            }
   169→
   170→            // Note: Derivation is now handled externally by kunki/LuaRuntime
   171→            // which subscribes to PageUpdate::LayerChanged events
   172→
   173→            Ok(())
   174→        }
   175→        ApplyOutcome::Rejected { reason } => {
   176→            warn!(layer = %layer_name, reason = %reason, "Update rejected");
   177→            Err(reason)
   178→        }
   179→    }
   180→}
   181→
   182→/// Core apply logic - returns ApplyOutcome
   183→///
   184→/// **Context**: Separated from handle_apply_update for cleaner testing
   185→/// **Returns**: ApplyOutcome::Applied or ApplyOutcome::Rejected
   186→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
   187→async fn apply_update_core(
   188→    state: &mut ScribeState,
   189→    ctx: &UpdateContext,
   190→    update: &[u8],
   191→) -> ApplyOutcome {
   192→    // Step 1: Permission check - reject local_only layers from remote
   193→    if ctx.is_remote && ctx.is_local_only {
   194→        return ApplyOutcome::Rejected {
   195→            reason: "local_only layer cannot be updated by remote peer".to_string(),
   196→        };
   197→    }
   198→
   199→    // Step 2: Permission check for remote updates
   200→    if let Some(ref peer) = ctx.from_peer {
   201→        if !Permissions::can_write(state, peer, &ctx.layer_name) {
   202→            return ApplyOutcome::Rejected {
   203→                reason: "Permission denied: cannot write to layer".to_string(),
   204→            };
   205→        }
   206→    }
   207→
   208→    // Step 3: Extract ops for validation (using optimized pre-commit method)
   209→    let extracted_ops = if ctx.should_validate {
   210→        // Use Layer::extract_ops_from_bytes (5-10x faster than old fork+diff)
   211→        match Layer::extract_ops_from_bytes(update) {
   212→            Ok(ops) => Some(ops),
   213→            Err(e) => {
   214→                // Log extraction failure - validation will proceed with empty ops
   215→                // This could mask invalid updates, so log at warn level
   216→                warn!(layer = %ctx.layer_name, error = %e, "Failed to extract ops from update, proceeding with empty ops");
   217→                None
   218→            }
   219→        }
   220→    } else {
   221→        None
   222→    };
   223→
   224→    // Step 4: Validate with Lua (if needed)
   225→    if ctx.should_validate {
   226→        if let Err(e) = validate_update_with_context(state, ctx, &extracted_ops).await {
   227→            return ApplyOutcome::Rejected { reason: e };
   228→        }
   229→    }
   230→
   231→    // Step 5: Create layer if needed (remote only)
   232→    let created_layer = if ctx.is_new_layer {
   233→        if ctx.is_remote {
   234→            create_layer_from_peer(state, &ctx.layer_name);
   235→            true
   236→        } else {
   237→            return ApplyOutcome::Rejected {
   238→                reason: "Layer not found".to_string(),
   239→            };
   240→        }
   241→    } else {
   242→        false
   243→    };
   244→
   245→    // Step 6: Apply CRDT update
   246→    if let Err(e) = apply_crdt_update(state, &ctx.layer_name, update, ctx.from_peer.clone()) {
   247→        return ApplyOutcome::Rejected { reason: e };
   248→    }
   249→
   250→    ApplyOutcome::Applied {
   251→        layer_name: ctx.layer_name.clone(),
   252→        ops: extracted_ops.unwrap_or_default(),
   253→        created_layer,
   254→    }
   255→}
   256→
   257→// Helper Functions
   258→
   259→/// Validate update using ValidationHandle (kunki) or fallback to Lua runtime
   260→///
   261→/// **Context**: Business logic validation for remote updates
   262→/// **Returns**: Ok(()) if validation passed, Err(message) if rejected
   263→/// **Timeout**: 5 seconds for ValidationHandle (kunki), immediate for Lua runtime
   264→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
   265→async fn validate_update_with_context(
   266→    state: &ScribeState,
   267→    ctx: &UpdateContext,
   268→    extracted_ops: &Option<Vec<JsonOp>>,
   269→) -> Result<(), String> {
   270→    let Some(ref ops) = extracted_ops else {
   271→        return Ok(()); // No ops to validate
   272→    };
   273→
   274→    if ops.is_empty() {
   275→        return Ok(()); // Empty ops = nothing to validate
   276→    }
   277→
   278→    // Extract actual DID from from_peer, not the role
   279→    let from_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str()).unwrap_or("local");
   280→
   281→    // Use ValidationHandle (kunki mode with presence_lib)
   282→    let Some(ref validation_handle) = state.validation_handle else {
   283→        // No validation available - allow update (viewer/owner mode without kunki)
   284→        // This is expected in viewer/owner mode but unexpected in node mode without kunki
   285→        warn!(layer = %ctx.layer_name, from_did = %from_did, "No ValidationHandle available, allowing remote update without validation");
   286→        return Ok(());
   287→    };
   288→
   289→    use tokio::time::{timeout, Duration};
   290→
   291→    let validation_future = validation_handle.validate_ops(
   292→        &state.page_id,
   293→        &ctx.layer_name,
   294→        ops,
   295→        from_did,
   296→        &ctx.peer_role,
   297→    );
   298→
   299→    match timeout(Duration::from_secs(5), validation_future).await {
   300→        Ok(Ok((true, _))) => {
   301→            debug!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, "Validation passed");
   302→            Ok(())
   303→        }
   304→        Ok(Ok((false, error_msg))) => {
   305→            let msg = error_msg.unwrap_or_else(|| "Validation failed".to_string());
   306→            warn!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, error = %msg, "Validation rejected update");
   307→            Err(format!("Validation failed: {}", msg))
   308→        }
   309→        Ok(Err(e)) => {
   310→            warn!(layer = %ctx.layer_name, error = %e, "Validation error, rejecting update");
   311→            Err(format!("Validation error: {}", e))
   312→        }
   313→        Err(_) => {
   314→            warn!(layer = %ctx.layer_name, "Validation timeout (5s), rejecting update");
   315→            Err("Validation timeout".to_string())
   316→        }
   317→    }
   318→}
   319→
   320→/// Create a new layer from peer sync
   321→///
   322→/// **Context**: Peer sent update for a layer we don't have yet
   323→/// **We do**: Create layer, set up observer, notify UI
   324→#[instrument(skip(state), fields(page_id = %state.page_id))]
   325→fn create_layer_from_peer(state: &mut ScribeState, layer_name: &str) {
   326→    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
   327→    let layer_name = normalize_layer_name(layer_name, &state.page_id);
   328→    let layer_name = layer_name.as_str();
   329→    let mut unit = LayerUnit::new_empty();
   330→    unit.set_local_only(!state.should_sync_layer(layer_name));
   331→    unit.mark_dirty();
   332→    state.units.insert(layer_name.to_string(), unit);
   333→    info!(layer = %layer_name, "Created new layer from peer sync");
   334→
   335→    // Set up Loro observer for new layer to enable sync broadcasts
   336→    setup_layer_observer(state, layer_name);
   337→
   338→    // Notify UI subscribers about the new layer
   339→    notify_layer_discovered(state, layer_name);
   340→}
   341→
   342→/// Apply CRDT update to layer
   343→///
   344→/// **Context**: Actually merge the update into the layer
   345→/// **We do**: Set pending source, apply, clear pending source
   346→#[instrument(skip(state, update), fields(page_id = %state.page_id, layer = %layer_name))]
   347→fn apply_crdt_update(
   348→    state: &mut ScribeState,
   349→    layer_name: &str,
   350→    update: &[u8],
   351→    from_peer: Option<(String, String)>,
   352→) -> Result<(), String> {
   353→    // Set pending update source BEFORE apply() so observer knows who caused this change
   354→    set_pending_update_source(state, from_peer);
   355→
   356→    // Get the layer and apply update
   357→    let result = if let Some(unit) = state.units.get(layer_name) {
   358→        unit.layer().apply(update)
   359→    } else {
   360→        clear_pending_update_source(state);
   361→        return Err("Layer not found".to_string());
   362→    };
   363→
   364→    if let Err(e) = result {
   365→        // Clear on error too
   366→        clear_pending_update_source(state);
   367→        error!(error = %e, "Failed to apply update to layer");
   368→        return Err(format!("Failed to apply update: {}", e));
   369→    }
   370→
   371→    // Clear pending update source AFTER apply() (observer already captured it)
   372→    clear_pending_update_source(state);
   373→
   374→    Ok(())
   375→}
   376→
   377→/// Handle post-apply actions for remote updates
   378→///
   379→/// **Context**: Remote update was successfully applied
   380→/// **We do**: Flush app layers immediately
   381→/// **Note**: UI notification is handled by Loro observer (no duplicate emit here)
   382→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
   383→async fn handle_post_apply(
   384→    state: &mut ScribeState,
   385→    layer_name: &str,
   386→    _from_peer: Option<(String, String)>,
   387→) {
   388→    // For app layers, flush immediately to storage so restart loads new code
   389→    if layer_name.starts_with("app:") {
   390→        if let Some(unit) = state.units.get_mut(layer_name) {
   391→            let snapshot = unit.layer().export_snapshot();
   392→            if let Err(e) = state.layer_storage.save_layer(layer_name, &snapshot) {
   393→                error!(layer = %layer_name, error = %e, "Failed to save app layer immediately");
   394→            } else {
   395→                info!(layer = %layer_name, "Saved app layer immediately for restart");
   396→                // Remove from dirty since we just saved it
   397→                unit.clear_dirty();
   398→            }
   399→        }
   400→    }
   401→
   402→    // Note: UI notification via emit_layer_changed_after_apply was removed
   403→    // The Loro observer handles PageUpdate::LayerChanged for all changes (local and remote)
   404→    // This prevents duplicate notifications
   405→}
   406→
   407→/// Update sender's peer vector after receiving their update
   408→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
   409→fn update_sender_vector(state: &mut ScribeState, peer: &(String, String), layer_name: &str) {
   410→    if let Some(unit) = state.units.get(layer_name) {
   411→        if let Ok(mut subs) = state.subscribers.write() {
   412→            if let Some(info) = subs.get_mut(peer) {
   413→                let current_vector = unit.layer().version_vector();
   414→                info.vectors.insert(layer_name.to_string(), current_vector);
   415→                debug!(user_did = %peer.0, "Updated sender's peer vector");
   416→            }
   417→        }
   418→    }
   419→}
   420→
   421→/// Get role for a peer from their stored permit
   422→///
   423→/// **Context**: Determining role for Lua validation
   424→/// **Checks**:
   425→/// 1. Sync target (owner/viewer mode) -> our role's counterpart
   426→/// 2. Stored permit (node mode) -> extract role from permit
   427→/// 3. Default -> "peer"
   428→#[instrument(skip(state), fields(page_id = %state.page_id))]
   429→fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
   430→    // If peer is our sync target, they are the "node" from our perspective
   431→    if let Some(ref config) = state.sync_config {
   432→        if let Some(ref sync_target) = config.sync_target {
   433→            if sync_target == peer_did {
   434→                return "node".to_string();
   435→            }
   436→        }
   437→    }
   438→
   439→    // Node mode: look up peer's stored permit and extract role via PermitContext
   440→    if let Some(ref resolver) = state.peer_resolver {
   441→        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
   442→            let role = PermitContext::from_token(&permit_token, &state.page_id, peer_did)
   443→                .map(|ctx| ctx.permit().relationship().unwrap_or("peer").to_string())
   444→                .unwrap_or_else(|_| "peer".to_string());
   445→            debug!(peer_did = %peer_did, role = %role, "Got peer role from stored permit via PermitContext");
   446→            return role;
   447→        }
   448→    }
   449→
   450→    // Default role
   451→    "peer".to_string()
   452→}
   453→

