     1→//! Layer Pattern Authorization
     2→//!
     3→//! Functions for checking if a permit authorizes access to a layer.
     4→//! Supports two-tier access: page permit (static layers) + layer permits (dynamic layers).
     5→
     6→/// Check if permit authorizes access to a layer
     7→///
     8→/// With fully-resolved permits, this is a simple map lookup.
     9→/// Layer keys in the permit are already expanded (e.g., "abc123/products").
    10→///
    11→/// # Arguments
    12→/// * `permit` - The viewer's permit
    13→/// * `layer_name` - Name of the layer to access (bare or full)
    14→/// * `operation` - Operation to check: "read", "write", "sync"
    15→///
    16→/// # Returns
    17→/// `true` if the permit authorizes this layer access
    18→pub fn can_access_layer(permit: &crate::parser::Permit, layer_name: &str, operation: &str) -> bool {
    19→    let page_id = permit.get_fact("page_id")
    20→        .and_then(|v| v.as_str())
    21→        .unwrap_or("");
    22→
    23→    // Try direct lookup first
    24→    if let Some(config) = permit.layers().get(layer_name) {
    25→        return check_operation(config, operation);
    26→    }
    27→
    28→    // Try with page_id prefix (for bare names like "products")
    29→    let full_name = format!("{}/{}", page_id, layer_name);
    30→    if let Some(config) = permit.layers().get(&full_name) {
    31→        return check_operation(config, operation);
    32→    }
    33→
    34→    // Try stripping page_id prefix (for full names when permit has bare)
    35→    let page_prefix = format!("{}/", page_id);
    36→    if let Some(bare) = layer_name.strip_prefix(&page_prefix) {
    37→        if let Some(config) = permit.layers().get(bare) {
    38→            return check_operation(config, operation);
    39→        }
    40→    }
    41→
    42→    tracing::debug!("[can_access_layer] No layer match for '{}'", layer_name);
    43→    false
    44→}
    45→
    46→/// Check access across a page permit + set of layer permits (two-tier model)
    47→///
    48→/// **Context**: Dynamic layers are authorized via separate layer permits.
    49→/// This function checks if any permit in the set grants access to the layer.
    50→///
    51→/// Access check = page permit layers ∪ all layer permit layers
    52→pub fn can_access_with_layer_permits(
    53→    page_permit: &crate::parser::Permit,
    54→    layer_permits: &[crate::parser::Permit],
    55→    layer_name: &str,
    56→    page_id: &str,
    57→    did: &str,
    58→    operation: &str,
    59→) -> bool {
    60→    // Check page permit first
    61→    if can_access_layer(page_permit, layer_name, operation) {
    62→        return true;
    63→    }
    64→
    65→    // Check each layer permit
    66→    for lp in layer_permits {
    67→        if can_access_layer(lp, layer_name, operation) {
    68→            return true;
    69→        }
    70→    }
    71→
    72→    // Schema fallback: creator can access dynamic layers matching their own DID in path
    73→    if matches_creator_schema(page_permit, layer_name, page_id, did, operation) {
    74→        return true;
    75→    }
    76→
    77→    false
    78→}
    79→
    80→/// Schema fallback for creator access to dynamic layers
    81→///
    82→/// **Context**: When a creator creates a dynamic layer, they can access it immediately
    83→/// via schema matching (before the node issues a layer permit). The layer path must
    84→/// contain the creator's DID to prove ownership.
    85→///
    86→/// **Example**: Creator with DID `did:key:alice` and schema `channels/{id}/messages`
    87→/// can access `page1/channels/did:key:alice/general/messages` because:
    88→/// 1. Schema `channels/{id}/messages` exists in their permit
    89→/// 2. The path contains their DID after stripping page_id prefix
    90→pub fn matches_creator_schema(
    91→    permit: &crate::parser::Permit,
    92→    layer_name: &str,
    93→    page_id: &str,
    94→    our_did: &str,
    95→    operation: &str,
    96→) -> bool {
    97→    let schemas = permit.dynamic_layer_schemas();
    98→    if schemas.is_empty() {
    99→        return false;
   100→    }
   101→
   102→    // Strip page_id prefix to get bare layer path
   103→    let page_prefix = format!("{}/", page_id);
   104→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
   105→
   106→    // For creator access, the path must contain the creator's DID
   107→    // Path format: {schema_prefix}/{creator_did}/{id_segments}/{schema_suffix}
   108→    if !bare_path.contains(our_did) {
   109→        return false;
   110→    }
   111→
   112→    // Try to match against each schema pattern
   113→    // Schema pattern: "channels/{id}/messages"
   114→    // Layer path:     "channels/did:key:alice/general/messages"
   115→    // We need to check if the path matches the schema with DID inserted
   116→    for (schema_pattern, schema) in schemas {
   117→        if matches_dynamic_path(bare_path, schema_pattern, our_did) {
   118→            let config = schema.permissions.as_ref().cloned().unwrap_or(
   119→                crate::parser::LayerConfig { sync: true, write: true, layer_type: None }
   120→            );
   121→            if check_operation(&config, operation) {
   122→                return true;
   123→            }
   124→        }
   125→    }
   126→
   127→    false
   128→}
   129→
   130→/// Check if a layer path matches a dynamic schema pattern with a DID inserted
   131→///
   132→/// Schema patterns use `{id}` as wildcard. For creator access, the DID is
   133→/// inserted as an additional path segment after the first literal segment.
   134→///
   135→/// **Pattern**: `channels/{id}/messages`
   136→/// **Path**:    `channels/did:key:alice/general/messages`
   137→///
   138→/// The DID segment (`did:key:alice`) is the creator's namespace.
   139→/// The `{id}` matches the user-chosen ID (`general`).
   140→fn matches_dynamic_path(bare_path: &str, schema_pattern: &str, creator_did: &str) -> bool {
   141→    let path_parts: Vec<&str> = bare_path.split('/').collect();
   142→    let pattern_parts: Vec<&str> = schema_pattern.split('/').collect();
   143→
   144→    // Dynamic path has one extra segment (the DID) compared to schema pattern
   145→    if path_parts.len() != pattern_parts.len() + 1 {
   146→        return false;
   147→    }
   148→
   149→    // First segment must match literally
   150→    if path_parts.is_empty() || pattern_parts.is_empty() || path_parts[0] != pattern_parts[0] {
   151→        return false;
   152→    }
   153→
   154→    // Second segment in path must be the creator's DID
   155→    if path_parts.len() < 2 || path_parts[1] != creator_did {
   156→        return false;
   157→    }
   158→
   159→    // Remaining segments: match path[2..] against pattern[1..]
   160→    for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
   161→        if *pat_seg != "{id}" && path_seg != pat_seg {
   162→            return false;
   163→        }
   164→    }
   165→
   166→    true
   167→}
   168→
   169→/// Check if a layer config allows the given operation
   170→fn check_operation(config: &crate::parser::LayerConfig, operation: &str) -> bool {
   171→    match operation {
   172→        "read" => config.sync,
   173→        "write" => config.write,
   174→        "sync" => config.sync,
   175→        _ => false,
   176→    }
   177→}
