   416→/// Sync binding data to UI after processing through transform/sort/filter
   417→fn sync_binding_to_ui(
   418→    lua: &Lua,
   419→    this: &ScribeBindings,
   420→    ui_property: &str,
   421→    data: &serde_json::Value,
   422→    layer_name: Option<&str>,
   423→) -> LuaResult<()> {
   424→    let manager = this.binding_manager.lock();
   425→
   426→    if let Some(binding) = manager.get_binding(ui_property) {
   427→        // Process through binding options
   428→        let processed = process_binding_data(lua, binding, data, layer_name)?;
   429→
   430→        // Send to UI (skip if data_to_ui_mutation returns None for empty/null data)
   431→        if let Some(ref ui_tx) = this.ui_tx {
   432→            if let Some(mutation) = super::binding::data_to_ui_mutation(&this.page_id, ui_property, processed) {
   433→                if let Err(e) = ui_tx.try_send(mutation) {
