            unit.mark_dirty();
            info!(layer = %layer_name, "Layer replaced successfully");
            Ok(())
        }
        Err(e) => {
            error!(layer = %layer_name, error = %e, "Failed to parse snapshot for layer replacement");
            Err(format!("Failed to parse snapshot: {}", e))
        }
    };

