     1→//! Typed CRDT operation handlers
     2→//!
     3→//! Handles list, map, and counter operations for Scribe actor.
     4→//! **Broadcast**: Handled automatically by Loro observer after commit()
     5→//!
     6→//! **Path convention**:
     7→//! - Empty path ("") = use layer_name as container name directly (Lua bindings)
     8→//! - Non-empty path = use root map pattern with nested containers (template actions)
     9→
    10→use tracing::{debug, info, instrument};
    11→
    12→use crate::{ScribeError, Result};
    13→use domains::json_to_loro_value;
    14→
    15→use crate::layer_unit::LayerUnit;
    16→use crate::state::ScribeState;
    17→use crate::loro_observer;
    18→
    19→// Typed CRDT Operation Handlers
    20→
    21→/// Helper to ensure a layer exists, returns true if layer was newly created
    22→fn ensure_layer_exists(state: &mut ScribeState, layer_name: &str) -> bool {
    23→    let is_new = !state.units.contains_key(layer_name);
    24→    if is_new {
    25→        let mut unit = LayerUnit::new_empty();
    26→        unit.set_local_only(!state.should_sync_layer(layer_name));
    27→        state.units.insert(layer_name.to_string(), unit);
    28→        debug!(layer = %layer_name, "Created new layer");
    29→    }
    30→    is_new
    31→}
    32→
    33→/// Handle list push operation (append)
    34→///
    35→/// **Broadcast**: Loro observer triggers broadcast after commit()
    36→/// **Path**: Empty = use layer_name as container; non-empty = root map pattern
    37→#[instrument(skip(state, item), fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
    38→pub async fn handle_list_push(
    39→    state: &mut ScribeState,
    40→    layer_name: &str,
    41→    path: &str,
    42→    item: serde_json::Value,
    43→) -> Result<()> {
    44→    info!("ListPush operation");
    45→
    46→    // Ensure layer exists
    47→    let is_new_layer = ensure_layer_exists(state, layer_name);
    48→
    49→    let unit = state.units.get_mut(layer_name)
    50→        .ok_or_else(|| ScribeError::LayerNotFound(layer_name.to_string()))?;
    51→
    52→    if path.is_empty() {
    53→        // Lua pattern: use layer_name as container name directly
    54→        let list = unit.layer().loro().get_list(layer_name);
    55→        let loro_value = json_to_loro_value(&item);
    56→        list.push(loro_value)
    57→            .map_err(|e| ScribeError::CrdtError(format!("ListPush: {}", e)))?;
    58→        unit.layer().commit();
    59→    } else {
    60→        // Template pattern: use root map with nested path
    61→        unit.layer().list_push(path, &item)
    62→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
    63→    }
    64→
    65→    unit.mark_dirty();
    66→
