     1→//! Unified Lua Runtime
     2→//!
     3→//! Single runtime implementation used by both shell (viewer) and kunki (node).
     4→//!
     5→//! ## Features
     6→//!
     7→//! - **OS thread spawning**: Uses `std::thread::spawn` (mlua::Lua is NOT Send for tokio)
     8→//! - **Timer support**: JS-style `setTimeout`/`setInterval` via Scheduler
     9→//! - **Validation**: Built-in `validate_ops()` method for permission checking
    10→//! - **Optional UI**: Enable/disable UI bindings based on configuration
    11→//!
    12→//! ## Usage
    13→//!
    14→//! ```ignore
    15→//! let (thread, cmd_tx) = LuaRuntime::spawn(LuaRuntimeConfig {
    16→//!     page_id: "page123".into(),
    17→//!     app_name: "My App".into(),
    18→//!     scribe,
    19→//!     user_did: "did:key:...".into(),
    20→//!     user_name: "Alice".into(),
    21→//!     user_role: "viewer".into(),
    22→//!     lua_code: app_lua,
    23→//!     ui_enabled: true,
    24→//!     ui_tx: Some(ui_channel),
    25→//!     query_tx: Some(query_channel),
    26→//! })?;
    27→//! ```
    28→
    29→use std::collections::HashMap;
    30→use std::sync::{Arc, RwLock};
    31→
    32→use mlua::{Function, Lua, ObjectLike, Table, UserData, UserDataMethods, Value};
    33→use parking_lot::Mutex;
    34→use serde_json::Value as JsonValue;
    35→use tokio::sync::mpsc;
    36→use tracing::{debug, info, trace, warn};
    37→
    38→use butler::LoroDelta;
    39→use crate::scribe_handle::ScribeHandle;
    40→
    41→use crate::bindings::{
    42→    json_to_lua, lua_to_json, process_binding_data, BindingManager,
    43→    DerivationBindings, EmojiBindings, LayoutBindings, PageBindings, PeersBindings,
    44→    PermitBindings, ScribeBindings, UiBindings, UiSharedState,
    45→};
    46→use crate::commands::{DebugState, LuaCommand, UiEventType, ValidationContext, ValidationResult};
    47→use crate::event_bus::EventDelivery;
    48→use crate::scheduler::Scheduler;
    49→use crate::ui_types::{UiMutation, UiQuery};
    50→use crate::{LUA_API_MODULE, LUA_DATE_MODULE, LUA_PRESENCE_MODULE, LUA_BINDING_MODULE};
    51→
    52→// Configuration
    53→
    54→/// Configuration for creating a LuaRuntime
    55→pub struct LuaRuntimeConfig {
    56→    /// Page ID this runtime is for
    57→    pub page_id: String,
    58→
    59→    /// App name (for logging)
    60→    pub app_name: String,
    61→
    62→    /// Reference to the Scribe handle for CRDT operations
    63→    pub scribe: Arc<dyn ScribeHandle>,
    64→
    65→    /// User's DID
    66→    pub user_did: String,
    67→
    68→    /// User's display name
    69→    pub user_name: String,
    70→
    71→    /// User's role (owner, viewer, collaborator, etc.)
    72→    pub user_role: String,
    73→
    74→    /// Lua code to execute
    75→    pub lua_code: String,
    76→
    77→    /// Enable UI bindings (ui:set, ui:get, etc.)
    78→    pub ui_enabled: bool,
    79→
    80→    /// Channel for sending UI mutations (required if ui_enabled)
    81→    pub ui_tx: Option<mpsc::Sender<UiMutation>>,
    82→
    83→    /// Channel for sending UI queries (required if ui_enabled)
    84→    pub query_tx: Option<mpsc::Sender<UiQuery>>,
    85→
    86→    /// Channel for in-page app navigation (page:open_app triggers tab switch)
    87→    pub navigate_tx: Option<std::sync::mpsc::Sender<String>>,
    88→}
    89→
    90→// Buffered UI Bindings (for headless/test mode)
    91→
    92→/// Buffered UI bindings for headless runtime
    93→///
    94→/// Stores properties in-memory and buffers all mutations for test inspection.
    95→/// Implements the full ui:set/get/push/insert/remove/clear/update/subscribe/emit API.
    96→pub struct BufferedUiBindings {
    97→    state: Arc<std::sync::Mutex<BufferedUiState>>,
    98→}
    99→
   100→/// Internal state for BufferedUiBindings
   101→pub struct BufferedUiState {
   102→    /// Property values (scalar values set via ui:set)
   103→    pub properties: HashMap<String, serde_json::Value>,
   104→    /// Accumulated mutations (for test inspection via drain_mutations)
   105→    pub mutations: Vec<UiMutation>,
   106→    /// Model data (arrays set via ui:set with array values)
   107→    pub models: HashMap<String, Vec<serde_json::Value>>,
   108→}
   109→
   110→impl BufferedUiState {
   111→    fn new() -> Self {
   112→        Self {
   113→            properties: HashMap::new(),
   114→            mutations: Vec::new(),
   115→            models: HashMap::new(),
   116→        }
   117→    }
   118→}
   119→
   120→impl BufferedUiBindings {
   121→    pub fn new() -> Self {
   122→        Self {
   123→            state: Arc::new(std::sync::Mutex::new(BufferedUiState::new())),
   124→        }
   125→    }
   126→
   127→    /// Get the shared state for external inspection
   128→    pub fn state(&self) -> Arc<std::sync::Mutex<BufferedUiState>> {
   129→        self.state.clone()
   130→    }
   131→}
   132→
   133→impl UserData for BufferedUiBindings {
   134→    fn add_methods<M: UserDataMethods<Self>>(methods: &mut M) {
   135→        methods.add_method("get", |lua, this, key: String| {
   136→            let state = this.state.lock().unwrap();
   137→            match state.properties.get(&key) {
   138→                Some(v) => json_to_lua(lua, v),
   139→                None => Ok(Value::Nil),
   140→            }
   141→        });
   142→
   143→        methods.add_method("set", |_lua, this, (key, value): (String, Value)| {
   144→            let json_value =
   145→                lua_to_json(&value).map_err(|e| mlua::Error::RuntimeError(e.to_string()))?;
   146→            let mut state = this.state.lock().unwrap();
   147→
   148→            if let serde_json::Value::Array(ref items) = json_value {
   149→                state.models.insert(key.clone(), items.clone());
   150→                state.mutations.push(UiMutation {
   151→                    app_id: String::new(),
   152→                    properties: vec![],
   153→                    model_ops: vec![crate::ui_types::VecModelOp::Replace {
   154→                        model_name: key,
   155→                        items: items.clone(),
   156→                    }],
   157→                });
   158→            } else {
   159→                state.properties.insert(key.clone(), json_value.clone());
   160→                state.mutations.push(UiMutation {
   161→                    app_id: String::new(),
   162→                    properties: vec![crate::ui_types::PropertyUpdate {
   163→                        key,
   164→                        value: json_value,
   165→                    }],
   166→                    model_ops: vec![],
   167→                });
   168→            }
   169→            Ok(())
   170→        });
   171→
   172→        methods.add_method("push", |_lua, this, (model_name, item): (String, Value)| {
   173→            let item_json =
   174→                lua_to_json(&item).map_err(|e| mlua::Error::RuntimeError(e.to_string()))?;
   175→            let mut state = this.state.lock().unwrap();
   176→            state.models.entry(model_name.clone()).or_default().push(item_json.clone());
   177→            state.mutations.push(UiMutation {
   178→                app_id: String::new(),
   179→                properties: vec![],
   180→                model_ops: vec![crate::ui_types::VecModelOp::Push {
   181→                    model_name,
   182→                    item: item_json,
   183→                }],
   184→            });
   185→            Ok(())
   186→        });
   187→
   188→        methods.add_method(
   189→            "insert",
   190→            |_lua, this, (model_name, index, item): (String, usize, Value)| {
   191→                let item_json =
   192→                    lua_to_json(&item).map_err(|e| mlua::Error::RuntimeError(e.to_string()))?;
   193→                let mut state = this.state.lock().unwrap();
   194→                let model = state.models.entry(model_name.clone()).or_default();
   195→                if index <= model.len() {
   196→                    model.insert(index, item_json.clone());
   197→                }
   198→                state.mutations.push(UiMutation {
   199→                    app_id: String::new(),
   200→                    properties: vec![],
   201→                    model_ops: vec![crate::ui_types::VecModelOp::Insert {
   202→                        model_name,
   203→                        index,
   204→                        item: item_json,
   205→                    }],
   206→                });
   207→                Ok(())
   208→            },
   209→        );
   210→
   211→        methods.add_method("remove", |_lua, this, (model_name, index): (String, usize)| {
   212→            let mut state = this.state.lock().unwrap();
   213→            if let Some(model) = state.models.get_mut(&model_name) {
   214→                if index < model.len() {
   215→                    model.remove(index);
   216→                }
   217→            }
   218→            state.mutations.push(UiMutation {
   219→                app_id: String::new(),
   220→                properties: vec![],
   221→                model_ops: vec![crate::ui_types::VecModelOp::Remove {
   222→                    model_name,
   223→                    index,
   224→                }],
   225→            });
   226→            Ok(())
   227→        });
   228→
   229→        methods.add_method("clear", |_lua, this, model_name: String| {
   230→            let mut state = this.state.lock().unwrap();
   231→            state.models.insert(model_name.clone(), vec![]);
   232→            state.mutations.push(UiMutation {
   233→                app_id: String::new(),
   234→                properties: vec![],
   235→                model_ops: vec![crate::ui_types::VecModelOp::Clear {
   236→                    model_name,
   237→                }],
   238→            });
   239→            Ok(())
   240→        });
   241→
   242→        methods.add_method(
   243→            "update",
   244→            |_lua, this, (model_name, index, item): (String, usize, Value)| {
   245→                let item_json =
   246→                    lua_to_json(&item).map_err(|e| mlua::Error::RuntimeError(e.to_string()))?;
   247→                let mut state = this.state.lock().unwrap();
   248→                if let Some(model) = state.models.get_mut(&model_name) {
   249→                    if index < model.len() {
   250→                        model[index] = item_json.clone();
   251→                    }
   252→                }
   253→                state.mutations.push(UiMutation {
   254→                    app_id: String::new(),
   255→                    properties: vec![],
   256→                    model_ops: vec![crate::ui_types::VecModelOp::Set {
   257→                        model_name,
   258→                        index,
   259→                        item: item_json,
   260→                    }],
   261→                });
   262→                Ok(())
   263→            },
   264→        );
   265→
   266→        methods.add_method(
   267→            "subscribe",
   268→            |_lua, _this, _args: mlua::MultiValue| Ok(0i64),
   269→        );
   270→        methods.add_method("unsubscribe", |_lua, _this, _id: i64| Ok(false));
   271→        methods.add_method("emit", |_lua, _this, _args: (String, Value)| Ok(0i64));
   272→    }
   273→}
