   275→// Timer Bindings
   276→
   277→/// Register timer functions on a Lua table
   278→///
   279→/// Creates timer.setTimeout, timer.setInterval, timer.clear as regular functions
   280→/// that can be called with dot syntax (timer.setInterval(ms, callback))
   281→fn register_timer_functions(lua: &Lua, scheduler: Arc<Mutex<Scheduler>>) -> mlua::Result<Table> {
   282→    let timer_table = lua.create_table()?;
   283→
   284→    // timer.setTimeout(ms, callback) -> id
   285→    let sched = scheduler.clone();
   286→    timer_table.set("setTimeout", lua.create_function(move |lua, (ms, callback): (u64, Function)| {
   287→        let id = {
   288→            let mut scheduler = sched.lock();
   289→            scheduler.register_timer(ms, false)
   290→        };
   291→        let timers: Table = lua.globals().get("_timers")?;
   292→        timers.set(id, callback)?;
   293→        trace!(timer_id = id, ms, "setTimeout registered");
   294→        Ok(id)
   295→    })?)?;
   296→
   297→    // timer.setInterval(ms, callback) -> id
   298→    let sched = scheduler.clone();
   299→    timer_table.set("setInterval", lua.create_function(move |lua, (ms, callback): (u64, Function)| {
   300→        let id = {
   301→            let mut scheduler = sched.lock();
   302→            scheduler.register_timer(ms, true)
   303→        };
   304→        let timers: Table = lua.globals().get("_timers")?;
   305→        timers.set(id, callback)?;
   306→        trace!(timer_id = id, ms, "setInterval registered");
   307→        Ok(id)
   308→    })?)?;
   309→
   310→    // timer.clear(id)
   311→    let sched = scheduler.clone();
   312→    timer_table.set("clear", lua.create_function(move |lua, id: u64| {
   313→        {
   314→            let mut scheduler = sched.lock();
   315→            scheduler.clear_timer(id);
   316→        }
   317→        let timers: Table = lua.globals().get("_timers")?;
   318→        timers.set(id, Value::Nil)?;
   319→        trace!(timer_id = id, "Timer cleared");
   320→        Ok(())
   321→    })?)?;
   322→
   323→    Ok(timer_table)
   324→}
