   326→// Lua Runtime
   327→
   328→/// Result of a single step of the event loop
   329→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
   330→pub enum StepResult {
   331→    /// A command was processed
   332→    Processed,
   333→    /// No command available (idle)
   334→    Idle,
   335→    /// Shutdown was requested
   336→    Shutdown,
   337→}
   338→
   339→/// Unified Lua runtime for both shell and node
   340→pub struct LuaRuntime {
   341→    /// Lua state
   342→    lua: Lua,
   343→
   344→    /// Page ID
   345→    page_id: String,
   346→
   347→    /// Timer scheduler (shared with TimerBindings)
   348→    scheduler: Arc<Mutex<Scheduler>>,
   349→
   350→    /// Command receiver
   351→    cmd_rx: mpsc::Receiver<LuaCommand>,
   352→
   353→    /// UI mutation sender (if UI enabled)
   354→    ui_tx: Option<mpsc::Sender<UiMutation>>,
   355→
   356→    /// UI shared state (for event bus, pending mutations)
   357→    ui_shared: Arc<Mutex<UiSharedState>>,
   358→
   359→    /// Binding manager for declarative layer → UI sync
   360→    binding_manager: Arc<Mutex<BindingManager>>,
   361→
   362→    /// Scribe handle for fetching layer data
   363→    scribe: Arc<dyn ScribeHandle>,
   364→
   365→    /// Whether UI is enabled
   366→    ui_enabled: bool,
   367→
   368→    /// Cached handler existence (populated after on_init)
   369→    handler_cache: HandlerCache,
   370→}
   371→
   372→/// Cache of which Lua handler functions exist (avoids repeated globals lookups)
   373→struct HandlerCache {
   374→    on_loro_change: bool,
   375→    on_layer_discovered: bool,
   376→    on_ephemeral: bool,
   377→    on_peer_joined: bool,
   378→    on_peer_left: bool,
   379→    on_asset_uploaded: bool,
   380→    on_key_pressed: bool,
   381→    on_text_input: bool,
   382→    on_shutdown: bool,
   383→}
   384→
   385→impl HandlerCache {
   386→    fn populate(lua: &Lua) -> Self {
   387→        let has = |name: &str| -> bool {
   388→            lua.globals().get::<Function>(name).is_ok()
   389→        };
   390→        Self {
   391→            on_loro_change: has("on_loro_change"),
   392→            on_layer_discovered: has("on_layer_discovered"),
   393→            on_ephemeral: has("on_ephemeral"),
   394→            on_peer_joined: has("on_peer_joined"),
   395→            on_peer_left: has("on_peer_left"),
   396→            on_asset_uploaded: has("on_asset_uploaded"),
   397→            on_key_pressed: has("on_key_pressed"),
   398→            on_text_input: has("on_text_input"),
   399→            on_shutdown: has("on_shutdown"),
   400→        }
   401→    }
   402→}
   403→
   404→impl LuaRuntime {
   405→    /// Spawn Lua runtime on an OS thread
   406→    ///
   407→    /// **Threading**: Uses `std::thread::spawn` because mlua::Lua is NOT Send for tokio
   408→    /// **Returns**: (thread handle, command sender)
   409→    pub fn spawn(
   410→        config: LuaRuntimeConfig,
   411→    ) -> Result<(std::thread::JoinHandle<()>, mpsc::Sender<LuaCommand>), String> {
   412→        let (cmd_tx, cmd_rx) = mpsc::channel(64);
   413→
   414→        let handle = std::thread::spawn(move || {
   415→            let mut runtime = match Self::new_internal(config, cmd_rx) {
   416→                Ok(r) => r,
   417→                Err(e) => {
   418→                    tracing::error!(error = %e, "Failed to create LuaRuntime");
   419→                    return;
   420→                }
   421→            };
   422→
   423→            runtime.run();
   424→        });
   425→
   426→        Ok((handle, cmd_tx))
   427→    }
   428→
   429→    /// Create a headless runtime on the current thread (for testing)
   430→    ///
   431→    /// **Returns**: (runtime, command sender)
   432→    /// **Usage**: Test harness creates runtime, sends commands, calls step() to pump
   433→    pub fn new_headless(
   434→        config: LuaRuntimeConfig,
   435→    ) -> Result<(Self, mpsc::Sender<LuaCommand>), String> {
   436→        let (cmd_tx, cmd_rx) = mpsc::channel(64);
   437→        let runtime = Self::new_internal(config, cmd_rx)?;
   438→        Ok((runtime, cmd_tx))
   439→    }
   440→
   441→    /// Call on_init handler (separated from run() for test harness)
   442→    ///
   443→    /// **Context**: Runs the Lua on_init function and re-populates handler cache
   444→    pub fn call_on_init(&mut self) {
   445→        if self.has_function("on_init") {
   446→            if let Err(e) = self.call_no_args::<()>("on_init") {
   447→                warn!(page_id = %self.page_id, error = %e, "on_init failed");
   448→            } else {
   449→                debug!(page_id = %self.page_id, "on_init completed");
   450→            }
   451→            self.flush_mutations();
   452→            self.handler_cache = HandlerCache::populate(&self.lua);
   453→        }
   454→    }
   455→
   456→    /// Process a single step of the event loop
   457→    ///
   458→    /// Fires due timers and tries to receive one command.
   459→    /// Returns StepResult indicating what happened.
   460→    pub fn step(&mut self) -> StepResult {
   461→        // Fire any due timers
   462→        self.fire_due_timers();
   463→
   464→        // Try to receive one command (non-blocking)
   465→        match self.cmd_rx.try_recv() {
   466→            Ok(cmd) => {
   467→                let should_exit = self.handle_command(cmd);
   468→                self.flush_mutations();
   469→                if should_exit {
   470→                    StepResult::Shutdown
   471→                } else {
   472→                    StepResult::Processed
   473→                }
   474→            }
   475→            Err(tokio::sync::mpsc::error::TryRecvError::Empty) => StepResult::Idle,
   476→            Err(tokio::sync::mpsc::error::TryRecvError::Disconnected) => StepResult::Shutdown,
   477→        }
   478→    }
   479→
   480→    /// Create runtime (internal, called on the OS thread)
   481→    fn new_internal(
   482→        config: LuaRuntimeConfig,
   483→        cmd_rx: mpsc::Receiver<LuaCommand>,
   484→    ) -> Result<Self, String> {
   485→        let lua = Lua::new();
   486→        let scheduler = Arc::new(Mutex::new(Scheduler::new()));
   487→        let ui_shared = Arc::new(Mutex::new(UiSharedState::new()));
   488→
   489→        // Create _timers table for storing callbacks
   490→        let timers_table: Table = lua
   491→            .create_table()
   492→            .map_err(|e| format!("Failed to create _timers table: {}", e))?;
   493→        lua.globals()
   494→            .set("_timers", timers_table)
   495→            .map_err(|e| format!("Failed to set _timers global: {}", e))?;
   496→
   497→        // Register timer API (using table with functions for dot syntax)
   498→        let timer_table = register_timer_functions(&lua, scheduler.clone())
   499→            .map_err(|e| format!("Failed to create timer table: {}", e))?;
   500→        lua.globals()
   501→            .set("timer", timer_table)
   502→            .map_err(|e| format!("Failed to set timer global: {}", e))?;
   503→
   504→        // Register scribe bindings (unified CRDT API)
   505→        // Use with_ui() when UI is enabled to support scribe:bind()
   506→        let our_name = Some(config.user_name.clone());
   507→        let scribe = if config.ui_enabled {
   508→            if let Some(ref ui_tx) = config.ui_tx {
   509→                ScribeBindings::with_ui(
   510→                    config.scribe.clone(),
   511→                    config.page_id.clone(),
   512→                    config.user_did.clone(),
   513→                    our_name,
   514→                    ui_tx.clone(),
   515→                )
   516→            } else {
   517→                ScribeBindings::new(
   518→                    config.scribe.clone(),
   519→                    config.page_id.clone(),
   520→                    config.user_did.clone(),
   521→                    our_name,
   522→                )
   523→            }
   524→        } else {
   525→            ScribeBindings::new(
   526→                config.scribe.clone(),
   527→                config.page_id.clone(),
   528→                config.user_did.clone(),
   529→                our_name,
   530→            )
   531→        };
   532→        let binding_manager = scribe.binding_manager();
   533→        lua.globals()
   534→            .set("scribe", scribe)
   535→            .map_err(|e| format!("Failed to set scribe global: {}", e))?;
   536→
   537→        // Register derivation bindings
   538→        let derivation = DerivationBindings::new(config.scribe.clone());
   539→        lua.globals()
   540→            .set("derivation", derivation)
   541→            .map_err(|e| format!("Failed to set derivation global: {}", e))?;
   542→
   543→        // Register permit bindings
   544→        let permit = PermitBindings::new(
   545→            config.page_id.clone(),
   546→            config.user_did.clone(),
   547→            config.user_name.clone(),
   548→            config.user_role.clone(),
   549→        );
   550→        lua.globals()
   551→            .set("permit", permit)
   552→            .map_err(|e| format!("Failed to set permit global: {}", e))?;
   553→
   554→        // Register peers bindings
   555→        let peers = PeersBindings::new(config.scribe.clone());
   556→        lua.globals()
   557→            .set("peers", peers)
   558→            .map_err(|e| format!("Failed to set peers global: {}", e))?;
   559→
   560→        // Register page bindings
   561→        let page = PageBindings {
   562→            handlers: Arc::new(RwLock::new(Vec::new())),
   563→            page_id: config.page_id.clone(),
   564→            navigate_tx: config.navigate_tx,
   565→        };
   566→        lua.globals()
   567→            .set("page", page)
   568→            .map_err(|e| format!("Failed to set page global: {}", e))?;
   569→
   570→        // Register UI bindings (real or stub)
   571→        if config.ui_enabled {
   572→            if let (Some(ui_tx), Some(query_tx)) = (config.ui_tx.clone(), config.query_tx.clone()) {
   573→                let ui = UiBindings {
   574→                    app_id: config.page_id.clone(),
   575→                    ui_tx,
   576→                    query_tx,
   577→                    shared: ui_shared.clone(),
   578→                };
   579→                lua.globals()
   580→                    .set("ui", ui)
   581→                    .map_err(|e| format!("Failed to set ui global: {}", e))?;
   582→
   583→                // UI-only bindings: layout, emoji
   584→                let layout = LayoutBindings::new();
   585→                lua.globals()
   586→                    .set("layout", layout)
   587→                    .map_err(|e| format!("Failed to set layout global: {}", e))?;
   588→
   589→                let emoji = EmojiBindings;
   590→                lua.globals()
   591→                    .set("emoji", emoji)
   592→                    .map_err(|e| format!("Failed to set emoji global: {}", e))?;
   593→            } else {
   594→                return Err("ui_enabled=true requires ui_tx and query_tx".into());
   595→            }
   596→        } else {
   597→            let ui = BufferedUiBindings::new();
   598→            lua.globals()
   599→                .set("ui", ui)
   600→                .map_err(|e| format!("Failed to set ui global: {}", e))?;
   601→        }
   602→
   603→        // Load API module
   604→        let api_module: Value = lua
   605→            .load(LUA_API_MODULE)
   606→            .eval()
   607→            .map_err(|e| format!("Failed to load api module: {}", e))?;
   608→        lua.globals()
   609→            .set("api", api_module)
   610→            .map_err(|e| format!("Failed to set api global: {}", e))?;
   611→
   612→        // Load datetime module
   613→        let datetime_module: Value = lua
   614→            .load(LUA_DATE_MODULE)
   615→            .eval()
   616→            .map_err(|e| format!("Failed to load datetime module: {}", e))?;
   617→        lua.globals()
   618→            .set("datetime", datetime_module)
   619→            .map_err(|e| format!("Failed to set datetime global: {}", e))?;
   620→
   621→        // Load presence module
   622→        let presence_module: Value = lua
   623→            .load(LUA_PRESENCE_MODULE)
   624→            .eval()
   625→            .map_err(|e| format!("Failed to load presence module: {}", e))?;
   626→        lua.globals()
   627→            .set("presence_lib", presence_module)
   628→            .map_err(|e| format!("Failed to set presence_lib global: {}", e))?;
   629→
   630→        // Load binding module for reactive UI updates
   631→        let binding_module: Value = lua
   632→            .load(LUA_BINDING_MODULE)
   633→            .eval()
   634→            .map_err(|e| format!("Failed to load binding module: {}", e))?;
   635→        lua.globals()
   636→            .set("binding", binding_module)
   637→            .map_err(|e| format!("Failed to set binding global: {}", e))?;
   638→
   639→        // Load app code
   640→        lua.load(&config.lua_code)
   641→            .exec()
   642→            .map_err(|e| format!("Failed to load Lua code: {}", e))?;
   643→
   644→        info!(
   645→            page_id = %config.page_id,
   646→            app_name = %config.app_name,
   647→            ui_enabled = config.ui_enabled,
   648→            "LuaRuntime created"
   649→        );
   650→
   651→        let handler_cache = HandlerCache::populate(&lua);
   652→
   653→        Ok(Self {
   654→            lua,
   655→            page_id: config.page_id,
   656→            scheduler,
   657→            cmd_rx,
   658→            ui_tx: config.ui_tx,
   659→            ui_shared,
   660→            binding_manager,
   661→            scribe: config.scribe,
   662→            ui_enabled: config.ui_enabled,
   663→            handler_cache,
   664→        })
   665→    }
   666→
   667→    /// Run the event loop (blocking)
   668→    fn run(&mut self) {
   669→        info!(page_id = %self.page_id, "Lua runtime event loop started");
   670→
   671→        self.call_on_init();
   672→
   673→        loop {
   674→            match self.step() {
   675→                StepResult::Shutdown => return,
   676→                StepResult::Processed => {
   677→                    // Processed a command, loop immediately to check for more
   678→                }
   679→                StepResult::Idle => {
   680→                    // No command available — sleep briefly to yield CPU, then retry
   681→                    // Timer resolution is handled by fire_due_timers() in step()
   682→                    let sleep_ms = {
   683→                        let scheduler = self.scheduler.lock();
   684→                        scheduler.time_until_next().min(std::time::Duration::from_millis(16))
   685→                    };
   686→                    std::thread::sleep(sleep_ms.min(std::time::Duration::from_millis(1)));
   687→                }
   688→            }
   689→        }
   690→    }
   691→
   692→    /// Check if a Lua function is defined
   693→    fn has_function(&self, name: &str) -> bool {
   694→        self.lua.globals().get::<Function>(name).is_ok()
   695→    }
   696→
   697→    /// Call a Lua function with no arguments
   698→    fn call_no_args<R: mlua::FromLuaMulti>(&self, name: &str) -> Result<R, String> {
   699→        let func: Function = self
   700→            .lua
   701→            .globals()
   702→            .get(name)
   703→            .map_err(|e| format!("Function '{}' not found: {}", name, e))?;
   704→
   705→        func.call(())
   706→            .map_err(|e| format!("Error calling '{}': {}", name, e))
   707→    }
   708→
   709→    /// Handle a command
   710→    ///
   711→    /// Returns true if shutdown was requested
   712→    fn handle_command(&mut self, cmd: LuaCommand) -> bool {
   713→        match cmd {
   714→            LuaCommand::Shutdown => {
