  1053→    /// Fire a single timer callback
  1054→    fn fire_timer(&self, timer_id: u64) {
  1055→        let timers: Result<Table, _> = self.lua.globals().get("_timers");
  1056→        if let Ok(timers) = timers {
  1057→            let callback: Result<Function, _> = timers.get(timer_id);
  1058→            if let Ok(func) = callback {
  1059→                if let Err(e) = func.call::<()>(()) {
  1060→                    warn!(timer_id, error = %e, "Timer callback error");
  1061→                }
  1062→            }
  1063→
  1064→            // Remove one-shot timer callback
  1065→            let is_one_shot = {
  1066→                let scheduler = self.scheduler.lock();
  1067→                !scheduler.timers.contains_key(&timer_id)
  1068→            };
  1069→            if is_one_shot {
  1070→                let _ = timers.set(timer_id, Value::Nil);
  1071→            }
  1072→        }
  1073→    }
