  1179→    /// Handle UI event
  1180→    fn handle_ui_event(&self, event: UiEventType) -> Result<(), String> {
  1181→        match event {
  1182→            UiEventType::KeyPressed { key } => {
  1183→                if self.handler_cache.on_key_pressed {
  1184→                    let func: Function = self.lua.globals().get("on_key_pressed").unwrap();
  1185→                    if let Err(e) = func.call::<()>(key) {
  1186→                        warn!(error = %e, "on_key_pressed error");
  1187→                    }
  1188→                }
  1189→            }
  1190→            UiEventType::TextChanged { element: _, text } => {
  1191→                if self.handler_cache.on_text_input {
  1192→                    let func: Function = self.lua.globals().get("on_text_input").unwrap();
  1193→                    if let Err(e) = func.call::<()>(text) {
  1194→                        warn!(error = %e, "on_text_input error");
  1195→                    }
  1196→                }
  1197→            }
  1198→            UiEventType::Custom { name, data } => {
  1199→                // Dispatch to event bus
  1200→                let event = crate::event_bus::Event::new(&name, crate::event_bus::EventSource::Human)
  1201→                    .with_data(data);
  1202→
  1203→                let deliveries = self.ui_shared.lock().event_bus.emit(event);
  1204→                for (subscriber_id, _callback_key, delivery) in deliveries {
  1205→                    self.dispatch_event_delivery(subscriber_id, delivery);
  1206→                }
  1207→            }
  1208→            _ => {}
  1209→        }
  1210→        Ok(())
  1211→    }
  1212→
  1213→    /// Dispatch event delivery to subscriber
  1214→    fn dispatch_event_delivery(&self, subscriber_id: u64, delivery: EventDelivery) {
  1215→        let shared = self.ui_shared.lock();
  1216→        if let Some(registry_key) = shared.callback_keys.get(&subscriber_id) {
  1217→            let callback: Result<Function, _> = self.lua.registry_value(registry_key);
  1218→            drop(shared);
  1219→
  1220→            if let Ok(callback) = callback {
  1221→                match delivery {
  1222→                    EventDelivery::Single(evt) => {
  1223→                        if let Ok(event_lua) =
  1224→                            crate::bindings::event_to_lua(&self.lua, &evt)
  1225→                        {
  1226→                            let _ = callback.call::<()>(event_lua);
  1227→                        }
  1228→                    }
  1229→                    EventDelivery::Batch(events) => {
  1230→                        if let Ok(events_lua) = self.lua.create_table() {
  1231→                            for (i, evt) in events.iter().enumerate() {
  1232→                                if let Ok(event_lua) =
  1233→                                    crate::bindings::event_to_lua(&self.lua, evt)
  1234→                                {
  1235→                                    let _ = events_lua.set(i + 1, event_lua);
  1236→                                }
  1237→                            }
  1238→                            let _ = callback.call::<()>(events_lua);
  1239→                        }
  1240→                    }
  1241→                }
  1242→            }
  1243→        }
  1244→    }
