  1246→    /// Flush accumulated UI mutations
  1247→    fn flush_mutations(&self) {
  1248→        if !self.ui_enabled {
  1249→            return;
  1250→        }
  1251→
  1252→        let mut shared = self.ui_shared.lock();
  1253→        let properties = std::mem::take(&mut shared.pending_properties);
  1254→        let model_ops = std::mem::take(&mut shared.pending_model_ops);
  1255→        drop(shared);
  1256→
  1257→        if properties.is_empty() && model_ops.is_empty() {
  1258→            return;
  1259→        }
  1260→
  1261→        let mutation = UiMutation {
  1262→            app_id: self.page_id.clone(),
  1263→            properties,
  1264→            model_ops,
  1265→        };
  1266→
  1267→        debug!(
  1268→            page_id = %self.page_id,
  1269→            prop_count = mutation.properties.len(),
  1270→            op_count = mutation.model_ops.len(),
  1271→            "Flushing UI mutations"
  1272→        );
  1273→
  1274→        if let Some(ref tx) = self.ui_tx {
  1275→            if let Err(e) = tx.try_send(mutation) {
  1276→                warn!(page_id = %self.page_id, error = %e, "Failed to send mutation");
  1277→            }
  1278→        }
  1279→    }
