  1353→    /// Validate operations against app's validation logic
  1354→    pub fn validate_ops(&self, ctx: &ValidationContext) -> Result<ValidationResult, String> {
  1355→        if !self.has_function("validate_ops") {
  1356→            return Ok(ValidationResult::default());
  1357→        }
  1358→
  1359→        let ops_json = serde_json::to_value(&ctx.ops)
  1360→            .map_err(|e| format!("Failed to serialize ops: {}", e))?;
  1361→        let ops_lua =
  1362→            json_to_lua(&self.lua, &ops_json).map_err(|e| format!("Ops to Lua: {}", e))?;
  1363→
  1364→        let func: Function = self.lua.globals().get("validate_ops").unwrap();
  1365→        let result: bool = func
  1366→            .call((
  1367→                ctx.layer_name.clone(),
  1368→                ops_lua,
  1369→                ctx.from_did.clone(),
  1370→                ctx.role.clone(),
  1371→                ctx.page_id.clone(),
  1372→            ))
  1373→            .map_err(|e| format!("validate_ops error: {}", e))?;
  1374→
  1375→        Ok(ValidationResult {
  1376→            valid: result,
  1377→            error: if result {
  1378→                None
  1379→            } else {
  1380→                Some("Validation failed".into())
  1381→            },
  1382→            failed_op_index: None,
  1383→        })
  1384→    }
  1385→}
