    17→/// Single-app test runner
    18→///
    19→/// Wraps a headless LuaRuntime with MockScribeHandle for easy testing.
    20→pub struct AppTestRunner {
    21→    runtime: LuaRuntime,
    22→    cmd_tx: mpsc::Sender<LuaCommand>,
    23→    mock_state: Arc<Mutex<MockScribeState>>,
