    29→impl AppTestRunner {
    30→    /// Load an app from a directory
    31→    ///
    32→    /// Reads manifest.json + app.lua (or entry_logic from manifest).
    33→    /// Creates MockScribeHandle + headless LuaRuntime.
    34→    pub fn load(
    35→        app_dir: &Path,
    36→        role: &str,
    37→        did: &str,
    38→        name: &str,
    39→    ) -> Result<Self, String> {
    40→        // Read manifest
    41→        let manifest_path = app_dir.join("manifest.json");
    42→        let manifest_str = std::fs::read_to_string(&manifest_path)
    43→            .map_err(|e| format!("Failed to read manifest.json: {}", e))?;
    44→        let manifest: serde_json::Value = serde_json::from_str(&manifest_str)
    45→            .map_err(|e| format!("Failed to parse manifest.json: {}", e))?;
    46→
    47→        // Get entry logic file name
    48→        let entry_logic = manifest
    49→            .get("entry_logic")
    50→            .and_then(|v| v.as_str())
    51→            .unwrap_or("app.lua");
    52→
    53→        // Read Lua code
    54→        let lua_path = app_dir.join(entry_logic);
    55→        let lua_code = std::fs::read_to_string(&lua_path)
    56→            .map_err(|e| format!("Failed to read {}: {}", entry_logic, e))?;
    57→
    58→        // Also check for init.lua (derivation rules)
    59→        let init_path = app_dir.join("init.lua");
    60→        let full_code = if init_path.exists() {
    61→            let init_code = std::fs::read_to_string(&init_path)
    62→                .map_err(|e| format!("Failed to read init.lua: {}", e))?;
    63→            format!("{}\n{}", init_code, lua_code)
    64→        } else {
    65→            lua_code
    66→        };
    67→
    68→        let app_name = manifest
    69→            .get("name")
    70→            .and_then(|v| v.as_str())
    71→            .unwrap_or("test-app")
    72→            .to_string();
    73→
    74→        Self::from_code(&full_code, &app_name, role, did, name)
    75→    }
