   184→    /// Process a single step (fire timers + try one command)
   185→    pub fn tick(&mut self) -> StepResult {
   186→        self.runtime.step()
   187→    }
   188→
   189→    /// Process N steps
   190→    pub fn tick_n(&mut self, n: usize) {
   191→        for _ in 0..n {
   192→            self.runtime.step();
   193→        }
   194→    }
   195→
   196→    /// Process steps until idle (no more commands to process)
   197→    pub fn tick_until_idle(&mut self, max_steps: usize) -> usize {
   198→        let mut steps = 0;
   199→        for _ in 0..max_steps {
   200→            match self.runtime.step() {
   201→                StepResult::Processed => steps += 1,
   202→                StepResult::Idle | StepResult::Shutdown => break,
   203→            }
   204→        }
   205→        steps
   206→    }
   207→
   208→    // -- Command injection --
   209→
   210→    /// Fire a UI callback by name with JSON args
   211→    pub fn fire_callback(&self, name: &str, args: Vec<JsonValue>) -> Result<(), String> {
   212→        self.cmd_tx
   213→            .try_send(LuaCommand::UiCallback {
   214→                callback_name: name.to_string(),
   215→                args,
   216→            })
   217→            .map_err(|e| format!("Failed to send callback: {}", e))
   218→    }
   219→
   220→    /// Fire a key press event
   221→    pub fn fire_key(&self, key: &str) -> Result<(), String> {
   222→        self.cmd_tx
   223→            .try_send(LuaCommand::UiEvent {
   224→                event: UiEventType::KeyPressed {
   225→                    key: key.to_string(),
   226→                },
   227→            })
   228→            .map_err(|e| format!("Failed to send key: {}", e))
   229→    }
   230→
   231→    /// Fire a text input event
   232→    pub fn fire_text_input(&self, text: &str) -> Result<(), String> {
   233→        self.cmd_tx
   234→            .try_send(LuaCommand::UiEvent {
   235→                event: UiEventType::TextChanged {
   236→                    element: String::new(),
   237→                    text: text.to_string(),
   238→                },
   239→            })
   240→            .map_err(|e| format!("Failed to send text: {}", e))
   241→    }
   242→
   243→    /// Inject a Loro change (simulates remote write arriving)
   244→    pub fn inject_loro_change(
   245→        &self,
   246→        layer_name: &str,
   247→        full_data: Option<JsonValue>,
   248→    ) -> Result<(), String> {
   249→        self.cmd_tx
   250→            .try_send(LuaCommand::LoroChanged {
   251→                layer_name: layer_name.to_string(),
   252→                ops: None,
   253→                delta: None,
   254→                full_data,
   255→            })
   256→            .map_err(|e| format!("Failed to inject loro change: {}", e))
   257→    }
   258→
   259→    /// Inject an ephemeral message (simulates remote peer sending)
   260→    pub fn inject_ephemeral(
   261→        &self,
   262→        from_did: &str,
   263→        func: &str,
   264→        args: JsonValue,
   265→    ) -> Result<(), String> {
   266→        self.cmd_tx
   267→            .try_send(LuaCommand::StructuredEphemeral {
   268→                from_did: from_did.to_string(),
   269→                func: func.to_string(),
   270→                args,
   271→            })
   272→            .map_err(|e| format!("Failed to inject ephemeral: {}", e))
   273→    }
   274→
   275→    /// Inject peer joined event
   276→    pub fn inject_peer_joined(&self, did: &str) -> Result<(), String> {
   277→        self.cmd_tx
   278→            .try_send(LuaCommand::PeerJoined {
   279→                user_did: did.to_string(),
   280→            })
   281→            .map_err(|e| format!("Failed to inject peer joined: {}", e))
   282→    }
   283→
   284→    /// Inject peer left event
   285→    pub fn inject_peer_left(&self, did: &str) -> Result<(), String> {
   286→        self.cmd_tx
   287→            .try_send(LuaCommand::PeerLeft {
   288→                user_did: did.to_string(),
   289→            })
   290→            .map_err(|e| format!("Failed to inject peer left: {}", e))
   291→    }
   292→
   293→    // -- Evaluation --
   294→
   295→    /// Evaluate Lua code and return JSON result
   296→    pub fn eval(&self, code: &str) -> Result<JsonValue, String> {
   297→        let (tx, rx) = tokio::sync::oneshot::channel();
   298→        self.cmd_tx
   299→            .try_send(LuaCommand::DebugEval {
   300→                code: code.to_string(),
   301→                response_tx: tx,
   302→            })
   303→            .map_err(|e| format!("Failed to send eval: {}", e))?;
   304→
   305→        // Need to step to process the command
   306→        // The caller should call tick() after this
   307→        // Return a placeholder - actual result comes after tick
   308→        // This design is slightly awkward; let's provide eval_sync instead
   309→        drop(rx);
   310→        Ok(JsonValue::Null)
   311→    }
   312→
   313→    /// Evaluate Lua code synchronously (sends command + ticks to process it)
   314→    pub fn eval_sync(&mut self, code: &str) -> Result<JsonValue, String> {
   315→        let (tx, mut rx) = tokio::sync::oneshot::channel();
   316→        self.cmd_tx
   317→            .try_send(LuaCommand::DebugEval {
   318→                code: code.to_string(),
   319→                response_tx: tx,
   320→            })
   321→            .map_err(|e| format!("Failed to send eval: {}", e))?;
   322→
   323→        // Step to process
   324→        self.runtime.step();
   325→
   326→        rx.try_recv()
   327→            .map_err(|e| format!("Eval response not ready: {}", e))?
   328→            .map_err(|e| format!("Eval error: {}", e))
   329→    }
