     1→//! MockScribeHandle — in-memory ScribeHandle for testing
     2→//!
     3→//! No Loro, no actors, no network. Pure HashMap-based storage.
     4→//! Provides inspection methods for test assertions.
     5→//!
     6→//! **Reactive**: Mutations notify all registered subscribers via `LuaCommand::LoroChanged`
     7→//! with `full_data` (no delta/ops — uses the Replace fallback path, works for both lists and maps).
     8→
     9→use std::collections::HashMap;
    10→use std::sync::{Arc, Mutex};
    11→
    12→use serde_json::Value as JsonValue;
    13→use tokio::sync::mpsc;
    14→
    15→use crate::commands::LuaCommand;
    16→use crate::scribe_handle::ScribeHandle;
    17→
    18→/// Layer storage variants
    19→#[derive(Debug, Clone)]
    20→enum MockLayer {
    21→    List(Vec<JsonValue>),
    22→    Map(HashMap<String, JsonValue>),
    23→}
    24→
    25→/// Shared state for MockScribeHandle
    26→///
    27→/// Wrapped in Arc<Mutex<>> so multiple handles can share state
    28→/// (simulates multiple peers on the same page).
    29→///
    30→/// **Reactive**: Register `lua_tx` channels via `register_subscriber()`.
    31→/// Every mutation sends `LuaCommand::LoroChanged { full_data }` to all subscribers.
    32→///
    33→/// **Layer normalization**: Like the real Scribe, strips `page_id/` prefix from layer names.
    34→/// Lua calls `scribe:list(page_id .. "/messages")` but layers are stored as `"messages"`.
    35→pub struct MockScribeState {
    36→    layers: HashMap<String, MockLayer>,
    37→    ephemerals: Vec<Vec<u8>>,
    38→    subscriber_count: usize,
    39→    /// Page ID for layer name normalization (strips "page_id/" prefix)
    40→    page_id: Option<String>,
    41→    /// Registered Lua runtime channels — notified on every mutation
    42→    subscribers: Vec<mpsc::Sender<LuaCommand>>,
    43→}
    44→
    45→impl MockScribeState {
    46→    fn new() -> Self {
    47→        Self {
    48→            layers: HashMap::new(),
    49→            ephemerals: Vec::new(),
    50→            subscriber_count: 0,
    51→            page_id: None,
    52→            subscribers: Vec::new(),
    53→        }
    54→    }
    55→
    56→    /// Set page ID for layer name normalization
    57→    ///
    58→    /// **Context**: Lua calls `scribe:list(page_id .. "/messages")` with a prefix.
    59→    /// Real Scribe strips this prefix. The mock must do the same.
    60→    pub fn set_page_id(&mut self, page_id: &str) {
    61→        self.page_id = Some(page_id.to_string());
    62→    }
    63→
    64→    /// Normalize layer name — strip `page_id/` prefix (matches real Scribe behavior)
    65→    fn normalize(&self, name: &str) -> String {
    66→        if let Some(ref page_id) = self.page_id {
    67→            let prefix = format!("{}/", page_id);
    68→            if let Some(bare) = name.strip_prefix(&prefix) {
    69→                return bare.to_string();
    70→            }
    71→        }
    72→        name.to_string()
    73→    }
    74→
    75→    /// Register a Lua runtime's command channel for change notifications
    76→    ///
    77→    /// **Context**: Called after `launch_test_slint_app()` returns the `lua_tx`.
    78→    /// All subsequent mutations will send `LoroChanged` to this channel.
    79→    pub fn register_subscriber(&mut self, tx: mpsc::Sender<LuaCommand>) {
    80→        self.subscribers.push(tx);
    81→    }
    82→
    83→    /// Clear all subscribers (stale channels from previous reload cycle)
    84→    pub fn clear_subscribers(&mut self) {
    85→        self.subscribers.clear();
    86→    }
    87→
    88→    /// Notify all subscribers that a layer changed
    89→    ///
    90→    /// **Sends**: `LuaCommand::LoroChanged` with `full_data` (no delta/ops).
    91→    /// This triggers the Replace fallback path in the binding system,
    92→    /// which works for both list and map layers.
    93→    fn notify_change(&self, layer_name: &str) {
    94→        if self.subscribers.is_empty() {
    95→            return;
    96→        }
    97→        let full_data = match self.get_layer_data(layer_name) {
    98→            Some(data) => data,
    99→            None => return,
   100→        };
   101→        for tx in &self.subscribers {
   102→            let _ = tx.try_send(LuaCommand::LoroChanged {
   103→                layer_name: layer_name.to_string(),
   104→                ops: None,
   105→                delta: None,
   106→                full_data: Some(full_data.clone()),
   107→            });
   108→        }
   109→    }
   110→}
   111→
   112→/// In-memory ScribeHandle for testing
   113→///
   114→/// All operations are synchronous and in-memory.
   115→/// Provides inspection methods for assertions.
   116→pub struct MockScribeHandle {
   117→    state: Arc<Mutex<MockScribeState>>,
   118→}
   119→
   120→impl MockScribeHandle {
   121→    /// Create a new MockScribeHandle
   122→    pub fn new() -> Arc<dyn ScribeHandle> {
   123→        Arc::new(Self {
   124→            state: Arc::new(Mutex::new(MockScribeState::new())),
   125→        })
   126→    }
   127→
   128→    /// Create a new MockScribeHandle with shared state (for multi-peer testing)
   129→    pub fn with_shared_state(state: Arc<Mutex<MockScribeState>>) -> Arc<dyn ScribeHandle> {
   130→        Arc::new(Self { state })
   131→    }
   132→
   133→    /// Create shared state for multi-peer scenarios
   134→    pub fn shared_state() -> Arc<Mutex<MockScribeState>> {
   135→        Arc::new(Mutex::new(MockScribeState::new()))
   136→    }
   137→
   138→    /// Get the underlying shared state for inspection
   139→    pub fn state(&self) -> Arc<Mutex<MockScribeState>> {
   140→        self.state.clone()
   141→    }
   142→}
   143→
   144→// -- Inspection methods (for test assertions) --
   145→
   146→impl MockScribeState {
   147→    /// Get all sent ephemerals
   148→    pub fn get_sent_ephemerals(&self) -> Vec<Vec<u8>> {
   149→        self.ephemerals.clone()
   150→    }
   151→
   152→    /// Clear sent ephemerals
   153→    pub fn clear_ephemerals(&mut self) {
   154→        self.ephemerals.clear();
   155→    }
   156→
   157→    /// Get all layer names
   158→    pub fn layer_names(&self) -> Vec<String> {
   159→        self.layers.keys().cloned().collect()
   160→    }
   161→
   162→    /// Get layer data as JSON
   163→    pub fn get_layer_data(&self, name: &str) -> Option<JsonValue> {
   164→        match self.layers.get(name) {
   165→            Some(MockLayer::List(items)) => Some(JsonValue::Array(items.clone())),
   166→            Some(MockLayer::Map(map)) => {
   167→                Some(JsonValue::Object(map.iter().map(|(k, v)| (k.clone(), v.clone())).collect()))
   168→            }
   169→            None => None,
   170→        }
   171→    }
   172→
   173→    /// Set subscriber count (for testing peer count)
   174→    pub fn set_subscriber_count(&mut self, count: usize) {
   175→        self.subscriber_count = count;
   176→    }
   177→
   178→    /// Directly set layer data (for injecting peer writes in tests)
   179→    pub fn inject_list_data(&mut self, name: &str, items: Vec<JsonValue>) {
   180→        self.layers.insert(name.to_string(), MockLayer::List(items));
   181→    }
   182→
   183→    /// Directly set map data (for injecting peer writes in tests)
   184→    pub fn inject_map_data(&mut self, name: &str, data: HashMap<String, JsonValue>) {
   185→        self.layers.insert(name.to_string(), MockLayer::Map(data));
   186→    }
   187→}
   188→
   189→impl ScribeHandle for MockScribeHandle {
   190→    fn ensure_list(&self, layer_name: &str) -> Result<(), String> {
   191→        let mut state = self.state.lock().unwrap();
   192→        let name = state.normalize(layer_name);
   193→        state
   194→            .layers
   195→            .entry(name)
   196→            .or_insert_with(|| MockLayer::List(Vec::new()));
   197→        Ok(())
   198→    }
   199→
   200→    fn ensure_map(&self, layer_name: &str) -> Result<(), String> {
   201→        let mut state = self.state.lock().unwrap();
   202→        let name = state.normalize(layer_name);
   203→        state
   204→            .layers
   205→            .entry(name)
   206→            .or_insert_with(|| MockLayer::Map(HashMap::new()));
   207→        Ok(())
   208→    }
   209→
   210→    fn create_derived_layer(&self, target_layer: &str) -> Result<(), String> {
   211→        self.ensure_list(target_layer)
   212→    }
   213→
   214→    fn list_push(&self, layer_name: &str, _path: &str, item: JsonValue) -> Result<(), String> {
   215→        let mut state = self.state.lock().unwrap();
   216→        let name = state.normalize(layer_name);
   217→        match state.layers.get_mut(&name) {
   218→            Some(MockLayer::List(items)) => {
   219→                items.push(item);
   220→                state.notify_change(&name);
   221→                Ok(())
   222→            }
   223→            Some(MockLayer::Map(_)) => Err(format!("Layer '{}' is a map, not a list", name)),
   224→            None => Err(format!("Layer '{}' does not exist", name)),
   225→        }
   226→    }
   227→
   228→    fn list_insert(
   229→        &self,
   230→        layer_name: &str,
   231→        _path: &str,
   232→        index: usize,
   233→        item: JsonValue,
   234→    ) -> Result<(), String> {
   235→        let mut state = self.state.lock().unwrap();
   236→        let name = state.normalize(layer_name);
   237→        match state.layers.get_mut(&name) {
   238→            Some(MockLayer::List(items)) => {
   239→                if index > items.len() {
   240→                    return Err(format!("Index {} out of bounds (len={})", index, items.len()));
   241→                }
   242→                items.insert(index, item);
   243→                state.notify_change(&name);
   244→                Ok(())
   245→            }
   246→            Some(MockLayer::Map(_)) => Err(format!("Layer '{}' is a map, not a list", name)),
   247→            None => Err(format!("Layer '{}' does not exist", name)),
   248→        }
   249→    }
   250→
   251→    fn list_delete(&self, layer_name: &str, _path: &str, index: usize) -> Result<(), String> {
   252→        let mut state = self.state.lock().unwrap();
   253→        let name = state.normalize(layer_name);
   254→        match state.layers.get_mut(&name) {
   255→            Some(MockLayer::List(items)) => {
   256→                if index >= items.len() {
   257→                    return Err(format!("Index {} out of bounds (len={})", index, items.len()));
   258→                }
   259→                items.remove(index);
   260→                state.notify_change(&name);
   261→                Ok(())
   262→            }
   263→            Some(MockLayer::Map(_)) => Err(format!("Layer '{}' is a map, not a list", name)),
   264→            None => Err(format!("Layer '{}' does not exist", name)),
   265→        }
   266→    }
   267→
   268→    fn list_get(&self, layer_name: &str, index: usize) -> Result<Option<JsonValue>, String> {
   269→        let state = self.state.lock().unwrap();
   270→        let name = state.normalize(layer_name);
   271→        match state.layers.get(&name) {
   272→            Some(MockLayer::List(items)) => Ok(items.get(index).cloned()),
   273→            Some(MockLayer::Map(_)) => Err(format!("Layer '{}' is a map, not a list", name)),
   274→            None => Err(format!("Layer '{}' does not exist", name)),
   275→        }
   276→    }
   277→
   278→    fn list_length(&self, layer_name: &str) -> Result<usize, String> {
   279→        let state = self.state.lock().unwrap();
   280→        let name = state.normalize(layer_name);
   281→        match state.layers.get(&name) {
