   330→            }
   331→            Some(MockLayer::List(_)) => {
   332→                Err(format!("Layer '{}' is a list, not a map", name))
   333→            }
   334→            None => Err(format!("Layer '{}' does not exist", name)),
   335→        }
   336→    }
   337→
   338→    fn map_length(&self, layer_name: &str) -> Result<usize, String> {
