   340→        let name = state.normalize(layer_name);
   341→        match state.layers.get(&name) {
   342→            Some(MockLayer::Map(map)) => Ok(map.len()),
   343→            Some(MockLayer::List(_)) => {
   344→                Err(format!("Layer '{}' is a list, not a map", name))
   345→            }
   346→            None => Err(format!("Layer '{}' does not exist", name)),
   347→        }
   348→    }
   349→
   350→    fn map_keys(&self, layer_name: &str) -> Result<Vec<String>, String> {
   351→        let state = self.state.lock().unwrap();
   352→        let name = state.normalize(layer_name);
   353→        match state.layers.get(&name) {
   354→            Some(MockLayer::Map(map)) => Ok(map.keys().cloned().collect()),
   355→            Some(MockLayer::List(_)) => {
   356→                Err(format!("Layer '{}' is a list, not a map", name))
   357→            }
   358→            None => Err(format!("Layer '{}' does not exist", name)),
   359→        }
   360→    }
   361→
   362→    fn list_layers(&self, pattern: &str) -> Result<Vec<String>, String> {
   363→        let state = self.state.lock().unwrap();
   364→        let names: Vec<String> = state
   365→            .layers
   366→            .keys()
   367→            .filter(|name| matches_glob(name, pattern))
   368→            .cloned()
   369→            .collect();
   370→        Ok(names)
   371→    }
   372→
   373→    fn get_layer_json(&self, layer_name: &str) -> Result<Option<JsonValue>, String> {
   374→        let state = self.state.lock().unwrap();
   375→        let name = state.normalize(layer_name);
   376→        Ok(state.get_layer_data(&name))
   377→    }
   378→
   379→    fn get_layer_data(&self, layer_name: &str) -> Result<JsonValue, String> {
   380→        let state = self.state.lock().unwrap();
   381→        let name = state.normalize(layer_name);
   382→        state
   383→            .get_layer_data(&name)
   384→            .ok_or_else(|| format!("Layer '{}' does not exist", name))
   385→    }
   386→
   387→    fn get_subscriber_count(&self) -> usize {
   388→        self.state.lock().unwrap().subscriber_count
   389→    }
   390→
   391→    fn create_layer(&self, schema_key: &str, layer_id: &str) -> Result<String, String> {
   392→        // Mock: generate a simple layer name from schema_key and layer_id
   393→        // In production, Scribe generates the full path with DID
   394→        let layer_name = format!("mock-page/{}/{}", schema_key.replace("{id}", layer_id), layer_id);
   395→        Ok(layer_name)
   396→    }
   397→
   398→    fn send_ephemeral(&self, payload: Vec<u8>) -> Result<(), String> {
   399→        self.state.lock().unwrap().ephemerals.push(payload);
   400→        Ok(())
   401→    }
   402→}
   403→
   404→/// Simple glob matching for layer names
   405→///
   406→/// Supports `*` as wildcard for any characters within a segment.
   407→fn matches_glob(name: &str, pattern: &str) -> bool {
   408→    if !pattern.contains('*') {
   409→        return name == pattern;
   410→    }
   411→
   412→    // Split on '*' and match greedily
   413→    let parts: Vec<&str> = pattern.split('*').collect();
   414→    if parts.is_empty() {
   415→        return true;
   416→    }
   417→
   418→    let mut pos = 0;
   419→    for (i, part) in parts.iter().enumerate() {
   420→        if part.is_empty() {
   421→            continue;
   422→        }
   423→        match name[pos..].find(part) {
   424→            Some(idx) => {
   425→                // First part must match at start
   426→                if i == 0 && idx != 0 {
   427→                    return false;
   428→                }
   429→                pos += idx + part.len();
   430→            }
   431→            None => return false,
   432→        }
   433→    }
   434→
   435→    // Last part must match at end (unless pattern ends with *)
   436→    if !pattern.ends_with('*') {
   437→        name.ends_with(parts.last().unwrap_or(&""))
   438→    } else {
   439→        true
   440→    }
   441→}
