     1→//! Broadcast handling for Scribe actor
     2→//!
     3→//! Handles layer update broadcasting to subscribers and page update emission.
     4→
     5→use tokio::sync::mpsc;
     6→use tracing::{info, instrument, warn};
     7→
     8→use crate::message::{BroadcastPayload, PageUpdate};
     9→use crate::state::ScribeState;
    10→
    11→// Layer Broadcasting
    12→
    13→/// Broadcast layer update to all eligible subscribers
    14→///
    15→/// **Context**: Layer has been updated, notify all subscribers
    16→/// **We do**: Send incremental or full snapshot to each subscriber
    17→/// **Cleanup**: Remove subscribers whose channels are closed (disconnected)
    18→#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
    19→pub async fn broadcast_update(
    20→    state: &mut ScribeState,
    21→    layer_name: &str,
    22→    from_peer: Option<&(String, String)>,
    23→) {
    24→    let Some(unit) = state.units.get(layer_name) else {
    25→        return;
    26→    };
    27→
    28→    let current_vector = unit.layer().version_vector();
    29→    let layer = unit.layer().clone(); // Clone for use inside subscriber lock
    30→
    31→    // Track subscribers to remove (channel closed = peer disconnected)
    32→    let mut to_remove: Vec<(String, String)> = Vec::new();
    33→
    34→    if let Ok(mut subs) = state.subscribers.write() {
    35→        for ((user_did, device_id), info) in subs.iter_mut() {
    36→            // Skip sender
    37→            if from_peer == Some(&(user_did.clone(), device_id.clone())) {
    38→                continue;
    39→            }
    40→
    41→            // Check can receive (fixed layers OR pattern-based)
    42→            if !info.can_receive_layer(layer_name, &state.page_id) {
    43→                continue;
    44→            }
    45→
    46→            // Incremental export: use subscriber's last known vector
    47→            // Falls back to full snapshot for first sync (no vector cached)
    48→            let update = if let Some(their_vector) = info.vectors.get(layer_name) {
    49→                layer.export_updates(their_vector)
    50→                    .unwrap_or_else(|_| layer.export_snapshot())
    51→            } else {
    52→                layer.export_snapshot()
    53→            };
    54→
    55→            let payload = BroadcastPayload {
    56→                page_id: state.page_id.clone(),
    57→                layer_name: layer_name.to_string(),
    58→                layer_type: domains::LayerType::from_layer_name(layer_name),
    59→                update,
    60→                state_vector: current_vector.clone(),
    61→            };
    62→
    63→            match info.broadcast_tx.try_send(payload) {
    64→                Ok(()) => {
    65→                    // Update their vector on successful send
    66→                    info.vectors.insert(layer_name.to_string(), current_vector.clone());
    67→                }
    68→                Err(mpsc::error::TrySendError::Closed(_)) => {
    69→                    info!(user_did = %user_did, device_id = %device_id, "Subscriber disconnected, removing");
    70→                    to_remove.push((user_did.clone(), device_id.clone()));
    71→                }
    72→                Err(mpsc::error::TrySendError::Full(_)) => {
    73→                    warn!(user_did = %user_did, "Broadcast channel full, update dropped");
    74→                }
    75→            }
    76→        }
    77→
    78→        // Remove disconnected subscribers
    79→        for key in to_remove {
    80→            if let Some(info) = subs.remove(&key) {
    81→                if let Err(e) = state.vector_storage.save_vectors(&key.0, &key.1, &info.vectors) {
    82→                    warn!(error = %e, user_did = %key.0, device_id = %key.1, "Failed to save peer vector on disconnect");
    83→                }
    84→                info!(user_did = %key.0, device_id = %key.1, "Cleaned up disconnected subscriber");
    85→            }
    86→        }
    87→    }
    88→
    89→    // Emit EnsureSync for any sync targets not currently subscribed
    90→    super::reconcile::emit_sync_events_for_missing_targets(state);
    91→}
    92→
    93→// Page Update Emission
    94→
    95→/// Notify page event subscribers of new layer discovery
    96→///
    97→/// **Context**: A new layer was created (from peer sync or local creation)
    98→/// **We do**: Send PageUpdate::LayerChanged with created=true to unified subscribers
    99→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
   100→pub fn notify_layer_discovered(state: &ScribeState, layer_name: &str) {
   101→    let full_data = state.units.get(layer_name)
   102→        .map(|unit| unit.layer().get_content(layer_name))
   103→        .unwrap_or(serde_json::Value::Null);
   104→
   105→    let state_vector = state.units.get(layer_name)
   106→        .map(|unit| unit.layer().version_vector())
   107→        .unwrap_or_default();
   108→
   109→    let update = PageUpdate::LayerChanged {
   110→        layer: layer_name.to_string(),
   111→        from_peer: None,
   112→        ops: None,
   113→        delta: None,
   114→        state_vector: state_vector.clone(),
   115→        full_data: Some(full_data.clone()),
   116→        created: true,
   117→    };
   118→    if let Ok(subs) = state.page_update_subscribers.read() {
   119→        for tx in subs.iter() {
   120→            let _ = tx.try_send(update.clone());
   121→        }
   122→    }
   123→}
   124→

