   150→// Permission Checking
   151→
   152→/// Scribe permission checking methods
   153→pub struct Permissions;
   154→
   155→impl Permissions {
   156→    /// Check if layer is local_only (never synced)
   157→    pub fn is_local_only(layer_name: &str) -> bool {
   158→        // Check all subscribers' policies - if ANY marks it local_only, treat as such
   159→        // Actually, local_only is typically a page-level setting, not per-peer
   160→        // For simplicity, we'll check the layer name
   161→        layer_name == "user_content_doc"
   162→    }
   163→
   164→    /// Check if peer can write to layer
   165→    ///
   166→    /// **Context**: Remote peer is trying to write to this layer
   167→    /// **We check**:
   168→    /// 1. Peer is a subscriber with write permission via permit.can_write_layer()
   169→    /// 2. OR peer is our sync_target (owner/viewer mode - trust sync source)
   170→    /// 3. OR peer has a stored permit with write access (node mode - permit-based sync auth)
   171→    ///
   172→    /// **Security**: For pattern-based layers, gurkha::Permit validates that:
   173→    /// - The layer name matches the expanded pattern
   174→    /// - Patterns with {aud} expand to the peer's actual DID (namespace enforcement)
   175→    pub fn can_write(state: &ScribeState, peer: &(String, String), layer_name: &str) -> bool {
   176→        let peer_did = &peer.0;
   177→
   178→        // 1. Check if peer is a subscriber with write permission
   179→        if let Ok(subs) = state.subscribers.read() {
   180→            if let Some(info) = subs.get(peer) {
   181→                // Use permit's can_write_layer which handles both fixed and pattern-based
   182→                if info.can_write_layer(layer_name, &state.page_id) {
   183→                    trace!(
   184→                        user_did = %peer_did,
   185→                        layer = %layer_name,
   186→                        "Write allowed via subscriber permit"
   187→                    );
   188→                    return true;
   189→                }
   190→            }
   191→        }
   192→
   193→        // 2. Owner/Viewer mode: trust data from our sync_target (the node we sync with)
   194→        // This allows receiving sync updates from the node without explicit subscription
   195→        if let Some(ref config) = state.sync_config {
   196→            if let Some(ref sync_target) = config.sync_target {
   197→                if peer_did == sync_target {
   198→                    debug!(user_did = %peer_did, layer = %layer_name, "Write allowed from sync_target");
   199→                    return true;
   200→                }
   201→            }
   202→        }
   203→
   204→        // 3. Node mode: check stored permit for write access (permit-based auth)
   205→        if let Some(ref resolver) = state.peer_resolver {
   206→            if let Some(permit_token) = resolver.load_user_permit(peer_did) {
   207→                // Parse permit and check write permissions
   208→                if let Ok(permit) = gurkha::Permit::from_token(&permit_token) {
   209→                    if permit.can_write_layer(layer_name, &state.page_id, peer_did) {
   210→                        debug!(user_did = %peer_did, layer = %layer_name, "Write allowed via stored permit");
   211→                        return true;
   212→                    }
   213→                }
   214→            }
   215→        }
   216→
   217→        false
   218→    }
   219→
   220→    /// Check if peer can receive updates for layer
   221→    ///
   222→    /// **Context**: Deciding whether to broadcast layer update to peer
   223→    /// **We check**:
   224→    /// 1. Fixed layer permission exists AND not in no_incoming_updates
   225→    /// 2. OR pattern matches peer's readable_patterns
   226→    ///
   227→    /// **Privacy**: Patterns like {page_id}/*/{aud} ensure:
   228→    /// - Customer A only receives their own layers (shop123/orders/did:key:customer_a)
   229→    /// - Customer B doesn't receive Customer A's layers
   230→    /// - Owner/Admin with {page_id}/*/* pattern receives all layers
   231→    #[allow(dead_code)]
   232→    pub fn can_receive(state: &ScribeState, peer: &(String, String), layer_name: &str) -> bool {
   233→        if let Ok(subs) = state.subscribers.read() {
   234→            if let Some(info) = subs.get(peer) {
   235→                return info.can_receive_layer(layer_name, &state.page_id);
   236→            }
   237→        }
   238→        false
   239→    }
   240→
   241→    /// Check if we (local user) can write to a layer
   242→    ///
   243→    /// **Context**: Local Lua/UI is trying to modify a layer
   244→    /// **We check**: Delegates to ScribeState::can_write_layer()
   245→    ///
   246→    /// **Security**: Ensures local writes respect our permit constraints
   247→    /// (e.g., viewer can only write to their namespaced layers)
   248→    pub fn can_local_write(state: &ScribeState, layer_name: &str) -> bool {
   249→        state.can_write_layer(layer_name)
   250→    }
   251→}
