   253→// Tests
   254→
   255→#[cfg(test)]
   256→mod tests {
   257→    /// Helper to test pattern matching with expansion
   258→    fn matches_with_expansion(layer_name: &str, pattern: &str, page_id: &str, did: &str) -> bool {
   259→        let expanded = gurkha::expand_pattern(pattern, page_id, did);
   260→        gurkha::matches_wildcard(layer_name, &expanded)
   261→    }
   262→
   263→    #[test]
   264→    fn test_wildcard_pattern_matching() {
   265→        // Exact segments with single wildcard
   266→        assert!(gurkha::matches_wildcard("shop123/orders/did:key:customer_a", "shop123/*/did:key:customer_a"));
   267→        assert!(gurkha::matches_wildcard("shop123/cart/did:key:customer_a", "shop123/*/did:key:customer_a"));
   268→
   269→        // Double wildcard (owner/admin pattern)
   270→        assert!(gurkha::matches_wildcard("shop123/orders/did:key:customer_a", "shop123/*/*"));
   271→        assert!(gurkha::matches_wildcard("shop123/anything/anything_else", "shop123/*/*"));
   272→
   273→        // Wrong segment count
   274→        assert!(!gurkha::matches_wildcard("shop123/orders", "shop123/*/did:key:customer_a"));
   275→        assert!(!gurkha::matches_wildcard("shop123/orders/sub/did:key:customer_a", "shop123/*/did:key:customer_a"));
   276→
   277→        // Wrong DID
   278→        assert!(!gurkha::matches_wildcard("shop123/orders/did:key:customer_b", "shop123/*/did:key:customer_a"));
   279→    }
   280→
   281→    #[test]
   282→    fn test_pattern_expansion_and_privacy() {
   283→        let pattern = "{page_id}/*/{aud}";
   284→
   285→        // Expansion matches own DID
   286→        assert!(matches_with_expansion("shop123/orders/did:key:customer_a", pattern, "shop123", "did:key:customer_a"));
   287→        // Expansion rejects other DID
   288→        assert!(!matches_with_expansion("shop123/orders/did:key:customer_b", pattern, "shop123", "did:key:customer_a"));
   289→
   290→        // Owner wildcard pattern matches all
   291→        let owner_pattern = "{page_id}/*/*";
   292→        assert!(matches_with_expansion("shop123/orders/did:key:customer_a", owner_pattern, "shop123", "did:key:owner"));
   293→        assert!(matches_with_expansion("shop123/orders/did:key:customer_b", owner_pattern, "shop123", "did:key:owner"));
   294→    }
   295→
   296→    #[test]
   297→    fn test_privacy_isolation() {
   298→        let pattern = "{page_id}/*/{aud}";
   299→        let layer_a = "shop123/orders/did:key:customer_a";
   300→        let layer_b = "shop123/orders/did:key:customer_b";
   301→
   302→        // Customer A can access their own layer
   303→        assert!(matches_with_expansion(layer_a, pattern, "shop123", "did:key:customer_a"));
   304→        // Customer A cannot access Customer B's layer
   305→        assert!(!matches_with_expansion(layer_b, pattern, "shop123", "did:key:customer_a"));
   306→
   307→        // Customer B can access their own layer
   308→        assert!(matches_with_expansion(layer_b, pattern, "shop123", "did:key:customer_b"));
   309→        // Customer B cannot access Customer A's layer
   310→        assert!(!matches_with_expansion(layer_a, pattern, "shop123", "did:key:customer_b"));
   311→    }
   312→}
