     1→//! Layer Unit — Per-layer compute unit
     2→//!
     3→//! Consolidates all per-layer state (LoroDoc, dirty flag, local-only flag,
     4→//! observer subscription) into a single struct. Makes Scribe a thin router
     5→//! over LayerUnit instances.
     6→//!
     7→//! Also contains dynamic layer management (schema validation, permit preparation).
     8→
     9→mod dynamic;
    10→
    11→pub use dynamic::{handle_create_dynamic_layer, prepare_layer_permits, find_matching_dynamic_schema};
    12→
    13→use domains::Layer;
    14→
    15→/// Per-layer compute unit — owns all state for a single layer
    16→pub struct LayerUnit {
    17→    /// The CRDT document
    18→    layer: Layer,
    19→    /// Needs flush to storage?
    20→    dirty: bool,
    21→    /// sync: false in permit — never broadcast
    22→    is_local_only: bool,
    23→    /// Created via dynamic_layer_schema (not static template)
    24→    pub is_dynamic: bool,
    25→    /// Loro observer subscription (dropped = unsubscribed)
    26→    loro_sub: Option<loro::Subscription>,
    27→}
    28→
    29→impl LayerUnit {
    30→    /// Create a LayerUnit wrapping an existing layer
    31→    pub fn new(layer: Layer) -> Self {
    32→        Self {
    33→            layer,
    34→            dirty: false,
    35→            is_local_only: false,
    36→            is_dynamic: false,
    37→            loro_sub: None,
    38→        }
    39→    }
    40→
    41→    /// Create a LayerUnit with an empty LoroDoc
    42→    pub fn new_empty() -> Self {
    43→        Self::new(Layer::new())
    44→    }
    45→
    46→    // Layer access
    47→
    48→    /// Get a reference to the inner Layer
    49→    pub fn layer(&self) -> &Layer {
    50→        &self.layer
    51→    }
    52→
    53→    /// Get a mutable reference to the inner Layer
    54→    pub fn layer_mut(&mut self) -> &mut Layer {
    55→        &mut self.layer
    56→    }
    57→
    58→    /// Replace the inner layer (e.g. snapshot restore)
    59→    pub fn replace_layer(&mut self, layer: Layer) {
    60→        self.layer = layer;
    61→    }
    62→
    63→    // Dirty tracking
    64→
    65→    /// Mark this layer as needing persistence
    66→    pub fn mark_dirty(&mut self) {
    67→        self.dirty = true;
    68→    }
    69→
    70→    /// Check if this layer needs persistence
    71→    pub fn is_dirty(&self) -> bool {
    72→        self.dirty
    73→    }
    74→
    75→    /// Clear the dirty flag without exporting
    76→    pub fn clear_dirty(&mut self) {
    77→        self.dirty = false;
    78→    }
    79→
    80→    /// Export snapshot if dirty, clear flag. Returns None if clean.
    81→    pub fn take_dirty_snapshot(&mut self) -> Option<Vec<u8>> {
    82→        if self.dirty {
    83→            self.dirty = false;
    84→            Some(self.layer.export_snapshot())
    85→        } else {
    86→            None
    87→        }
    88→    }
    89→
    90→    // Metadata
    91→
    92→    /// Check if this layer is local-only (sync: false)
    93→    pub fn is_local_only(&self) -> bool {
    94→        self.is_local_only
    95→    }
    96→
    97→    /// Set the local-only flag
    98→    pub fn set_local_only(&mut self, val: bool) {
    99→        self.is_local_only = val;
   100→    }
   101→
   102→    /// Check if this layer was created dynamically
   103→    pub fn is_dynamic(&self) -> bool {
   104→        self.is_dynamic
   105→    }
   106→
   107→    // Observer lifecycle
   108→
   109→    /// Check if this layer has an active Loro observer
   110→    pub fn has_observer(&self) -> bool {
   111→        self.loro_sub.is_some()
   112→    }
   113→
   114→    /// Set the Loro observer subscription
   115→    pub fn set_observer(&mut self, sub: loro::Subscription) {
   116→        self.loro_sub = Some(sub);
   117→    }
   118→
   119→    /// Drop the observer (unsubscribes from Loro)
   120→    pub fn clear_observer(&mut self) {
   121→        self.loro_sub = None;
   122→    }
   123→}
