//! Apply update handling for Scribe actor
//!
//! Handles incoming layer updates (local or remote), including permission checks,
//! validation, and CRDT merge.
//!
//! Note: Derivation is now handled externally by kunki/LuaRuntime which
//! subscribes to PageUpdate::LayerChanged events.
//!
//! ## Key Types
//!
//! - `UpdateContext`: Computed context for an incoming update - all decisions made upfront
//! - `ApplyOutcome`: Result of applying an update (Applied or Rejected)

use logging_utils::ShortLayer;
use tracing::{debug, error, info, warn, instrument};

use domains::Layer;

use super::broadcast::{broadcast_update, notify_layer_discovered};
use crate::layer_unit::LayerUnit;
use crate::layer_unit::{find_matching_dynamic_schema, prepare_layer_permits};
use crate::loro_observer::{set_pending_update_source, clear_pending_update_source, setup_layer_observer};
use crate::permit::{Permissions, PermitContext};
use crate::state::ScribeState;
use crate::SyncEvent;
use crate::JsonOp;
use crate::state::normalize_layer_name;

// Update Context - Centralized Decision Logic

/// Context for an incoming update - computed once, used throughout
///
/// **Design**: All decisions about how to handle an update are computed upfront.
/// This makes the apply flow clearer and easier to test.
#[derive(Debug)]
pub struct UpdateContext {
    /// Layer being updated
    pub layer_name: String,
    /// Source of update: None = local, Some = remote peer (user_did, device_id)
    pub from_peer: Option<(String, String)>,
    /// Role of the peer (for validation) - "node", "owner", "viewer", etc.
    pub peer_role: String,

    /// Is this a remote update (from a peer)?
    pub is_remote: bool,
    /// Is this layer local-only (never synced)?
    pub is_local_only: bool,
    /// Does this update need Lua validation?
    pub should_validate: bool,
    /// Should we broadcast after applying?
    pub should_broadcast: bool,
    /// Is this a new layer (needs creation)?
    pub is_new_layer: bool,
}

impl UpdateContext {
    /// Create context for an incoming update
    ///
    /// **Context**: Computes all decisions based on state and update metadata
    /// **Note**: Permission checks are done separately (may reject before context is useful)
    pub fn new(
        state: &ScribeState,
        layer_name: &str,
        from_peer: Option<(String, String)>,
    ) -> Self {
        let is_remote = from_peer.is_some();
        let is_local_only = Permissions::is_local_only(layer_name);
        let is_new_layer = !state.units.contains_key(layer_name);

        // Determine peer role for validation
        let peer_role = if let Some(ref peer) = from_peer {
            get_peer_role(state, &peer.0)
        } else {
            "local".to_string()
        };

        // Should validate: remote update AND ValidationHandle exists
        let should_validate = is_remote && state.validation_handle.is_some();

        // Should broadcast: remote update (local updates use observer)
        let should_broadcast = is_remote;

        Self {
            layer_name: layer_name.to_string(),
            from_peer,
            peer_role,
            is_remote,
            is_local_only,
            should_validate,
            should_broadcast,
            is_new_layer,
        }
    }
}

// Apply Outcome - Event-Driven Pattern

/// Outcome of applying an update
///
/// **Design**: Separates the "what happened" from "what to do next"
/// This enables cleaner outcome handling and better error messages
#[derive(Debug)]
pub enum ApplyOutcome {
    /// Update was successfully applied
    Applied {
        /// Layer that was updated
        layer_name: String,
        /// Ops extracted from update (for derivation)
        ops: Vec<JsonOp>,
        /// Was a new layer created?
        created_layer: bool,
    },
    /// Update was rejected
    Rejected {
        /// Reason for rejection
        reason: String,
    },
}

// Apply Update Handler

/// Handle layer update (local or remote)
///
/// **Context**: Edit from UI or sync push from peer
/// **We do**: Permission check, validation, CRDT merge
/// **Broadcast**: Handled automatically by Loro observer (set up at startup)
/// **Returns**: Ok(()) on success, Err(message) on failure
#[instrument(skip(state, update, permit), fields(page_id = %state.page_id, layer = %ShortLayer(layer_name)))]
pub async fn handle_apply_update(
    state: &mut ScribeState,
    layer_name: &str,
    update: &[u8],
    from_peer: Option<(String, String)>,
    permit: Option<&str>,
) -> std::result::Result<(), String> {
    let _ = permit; // Permit is used for subscription in Courier, not here

    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
    let layer_name = normalize_layer_name(layer_name, &state.page_id);
    let layer_name = layer_name.as_str();

    // Build context - computes all decisions upfront
    let ctx = UpdateContext::new(state, layer_name, from_peer.clone());

    // Step 1: Apply the update (with permission checks, validation, CRDT merge)
    let outcome = apply_update_core(state, &ctx, update).await;

    // Step 2: Handle the outcome
    match outcome {
        ApplyOutcome::Applied { layer_name, ops: _, created_layer } => {
            // Mark layer as dirty for persistence
            if let Some(unit) = state.units.get_mut(&layer_name) {
                unit.mark_dirty();
            }
            debug!(layer = %layer_name, created = created_layer, "Update applied successfully");

            // Post-apply handling for remote updates
            if ctx.is_remote {
                handle_post_apply(state, &layer_name, ctx.from_peer.clone()).await;
            }

            // Node-side: detect new dynamic layers and issue permits
            if created_layer {
                if let Some(ref from_peer) = ctx.from_peer {
                    emit_dynamic_layer_permits(state, &layer_name, from_peer).await;
                }
            }

            // Update sender's vector
            if let Some(ref peer) = ctx.from_peer {
                update_sender_vector(state, peer, &layer_name);
            }

            // Broadcast to eligible subscribers
            if ctx.should_broadcast {
                broadcast_update(state, &layer_name, ctx.from_peer.as_ref()).await;
            }

            // Note: Derivation is now handled externally by kunki/LuaRuntime
            // which subscribes to PageUpdate::LayerChanged events

            Ok(())
        }
        ApplyOutcome::Rejected { reason } => {
            warn!(layer = %layer_name, reason = %reason, "Update rejected");
            Err(reason)
        }
    }
}

/// Core apply logic - returns ApplyOutcome
///
/// **Context**: Separated from handle_apply_update for cleaner testing
/// **Returns**: ApplyOutcome::Applied or ApplyOutcome::Rejected
#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
async fn apply_update_core(
    state: &mut ScribeState,
    ctx: &UpdateContext,
    update: &[u8],
) -> ApplyOutcome {
    // Step 1: Permission check - reject local_only layers from remote
    if ctx.is_remote && ctx.is_local_only {
        return ApplyOutcome::Rejected {
            reason: "local_only layer cannot be updated by remote peer".to_string(),
        };
    }

    // Step 2: Permission check for remote updates
    if let Some(ref peer) = ctx.from_peer {
        if !Permissions::can_write(state, peer, &ctx.layer_name) {
            return ApplyOutcome::Rejected {
                reason: "Permission denied: cannot write to layer".to_string(),
            };
        }
    }

    // Step 3: Extract ops for validation (using optimized pre-commit method)
    let extracted_ops = if ctx.should_validate {
        // Use Layer::extract_ops_from_bytes (5-10x faster than old fork+diff)
        match Layer::extract_ops_from_bytes(update) {
            Ok(ops) => Some(ops),
            Err(e) => {
                // Log extraction failure - validation will proceed with empty ops
                // This could mask invalid updates, so log at warn level
                warn!(layer = %ctx.layer_name, error = %e, "Failed to extract ops from update, proceeding with empty ops");
                None
            }
        }
    } else {
        None
    };

    // Step 4: Validate with Lua (if needed)
    if ctx.should_validate {
        if let Err(e) = validate_update_with_context(state, ctx, &extracted_ops).await {
            return ApplyOutcome::Rejected { reason: e };
        }
    }

    // Step 5: Create layer if needed (remote only)
    let created_layer = if ctx.is_new_layer {
        if ctx.is_remote {
            create_layer_from_peer(state, &ctx.layer_name);
            true
        } else {
            return ApplyOutcome::Rejected {
                reason: "Layer not found".to_string(),
            };
        }
    } else {
        false
    };

    // Step 6: Apply CRDT update
    if let Err(e) = apply_crdt_update(state, &ctx.layer_name, update, ctx.from_peer.clone()) {
        return ApplyOutcome::Rejected { reason: e };
    }

    ApplyOutcome::Applied {
        layer_name: ctx.layer_name.clone(),
        ops: extracted_ops.unwrap_or_default(),
        created_layer,
    }
}

// Helper Functions

/// Validate update using ValidationHandle (kunki) or fallback to Lua runtime
///
/// **Context**: Business logic validation for remote updates
/// **Returns**: Ok(()) if validation passed, Err(message) if rejected
/// **Timeout**: 5 seconds for ValidationHandle (kunki), immediate for Lua runtime
#[instrument(skip_all, fields(page_id = %state.page_id, layer = %ctx.layer_name))]
async fn validate_update_with_context(
    state: &ScribeState,
    ctx: &UpdateContext,
    extracted_ops: &Option<Vec<JsonOp>>,
) -> Result<(), String> {
    let Some(ref ops) = extracted_ops else {
        return Ok(()); // No ops to validate
    };

    if ops.is_empty() {
        return Ok(()); // Empty ops = nothing to validate
    }

    // Extract actual DID from from_peer, not the role
    let from_did = ctx.from_peer.as_ref().map(|(d, _)| d.as_str()).unwrap_or("local");

    // Use ValidationHandle (kunki mode with presence_lib)
    let Some(ref validation_handle) = state.validation_handle else {
        // No validation available - allow update (viewer/owner mode without kunki)
        // This is expected in viewer/owner mode but unexpected in node mode without kunki
        warn!(layer = %ctx.layer_name, from_did = %from_did, "No ValidationHandle available, allowing remote update without validation");
        return Ok(());
    };

    use tokio::time::{timeout, Duration};

    let validation_future = validation_handle.validate_ops(
        &state.page_id,
        &ctx.layer_name,
        ops,
        from_did,
        &ctx.peer_role,
    );

    match timeout(Duration::from_secs(5), validation_future).await {
        Ok(Ok((true, _))) => {
            debug!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, "Validation passed");
            Ok(())
        }
        Ok(Ok((false, error_msg))) => {
            let msg = error_msg.unwrap_or_else(|| "Validation failed".to_string());
            warn!(layer = %ctx.layer_name, from_did = %from_did, role = %ctx.peer_role, error = %msg, "Validation rejected update");
            Err(format!("Validation failed: {}", msg))
        }
        Ok(Err(e)) => {
            warn!(layer = %ctx.layer_name, error = %e, "Validation error, rejecting update");
            Err(format!("Validation error: {}", e))
        }
        Err(_) => {
            warn!(layer = %ctx.layer_name, "Validation timeout (5s), rejecting update");
            Err("Validation timeout".to_string())
        }
    }
}

/// Create a new layer from peer sync
///
/// **Context**: Peer sent update for a layer we don't have yet
/// **We do**: Create layer, set up observer, notify UI
#[instrument(skip(state), fields(page_id = %state.page_id))]
fn create_layer_from_peer(state: &mut ScribeState, layer_name: &str) {
    // Defense-in-depth: normalize layer name (strip page_id/ prefix)
    let layer_name = normalize_layer_name(layer_name, &state.page_id);
    let layer_name = layer_name.as_str();
    let mut unit = LayerUnit::new_empty();
    unit.set_local_only(!state.should_sync_layer(layer_name));
    unit.mark_dirty();
    state.units.insert(layer_name.to_string(), unit);
    info!(layer = %layer_name, "Created new layer from peer sync");

    // Set up Loro observer for new layer to enable sync broadcasts
    setup_layer_observer(state, layer_name);

    // Notify UI subscribers about the new layer
    notify_layer_discovered(state, layer_name);
}

/// Apply CRDT update to layer
///
/// **Context**: Actually merge the update into the layer
/// **We do**: Set pending source, apply, clear pending source
#[instrument(skip(state, update), fields(page_id = %state.page_id, layer = %layer_name))]
fn apply_crdt_update(
    state: &mut ScribeState,
    layer_name: &str,
    update: &[u8],
    from_peer: Option<(String, String)>,
) -> Result<(), String> {
    // Set pending update source BEFORE apply() so observer knows who caused this change
    set_pending_update_source(state, from_peer);

    // Get the layer and apply update
    let result = if let Some(unit) = state.units.get(layer_name) {
        unit.layer().apply(update)
    } else {
        clear_pending_update_source(state);
        return Err("Layer not found".to_string());
    };

    if let Err(e) = result {
        // Clear on error too
        clear_pending_update_source(state);
        error!(error = %e, "Failed to apply update to layer");
        return Err(format!("Failed to apply update: {}", e));
    }

    // Clear pending update source AFTER apply() (observer already captured it)
    clear_pending_update_source(state);

    Ok(())
}

/// Handle post-apply actions for remote updates
///
/// **Context**: Remote update was successfully applied
/// **We do**: Flush app layers immediately
/// **Note**: UI notification is handled by Loro observer (no duplicate emit here)
#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
async fn handle_post_apply(
    state: &mut ScribeState,
    layer_name: &str,
    _from_peer: Option<(String, String)>,
) {
    // For app layers, flush immediately to storage so restart loads new code
    if layer_name.starts_with("app:") {
        if let Some(unit) = state.units.get_mut(layer_name) {
            let snapshot = unit.layer().export_snapshot();
            if let Err(e) = state.layer_storage.save_layer(layer_name, &snapshot) {
                error!(layer = %layer_name, error = %e, "Failed to save app layer immediately");
            } else {
                info!(layer = %layer_name, "Saved app layer immediately for restart");
                // Remove from dirty since we just saved it
                unit.clear_dirty();
            }
        }
    }

    // Note: UI notification via emit_layer_changed_after_apply was removed
    // The Loro observer handles PageUpdate::LayerChanged for all changes (local and remote)
    // This prevents duplicate notifications
}

/// Update sender's peer vector after receiving their update
#[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name))]
fn update_sender_vector(state: &mut ScribeState, peer: &(String, String), layer_name: &str) {
    if let Some(unit) = state.units.get(layer_name) {
        if let Ok(mut subs) = state.subscribers.write() {
            if let Some(info) = subs.get_mut(peer) {
                let current_vector = unit.layer().version_vector();
                info.vectors.insert(layer_name.to_string(), current_vector);
                debug!(user_did = %peer.0, "Updated sender's peer vector");
            }
        }
    }
}

/// Detect if a newly created layer matches a dynamic schema and emit permits
///
/// **Context**: Node receives a new layer from peer. If it matches a dynamic schema,
/// prepare layer permits for all connected peers and emit SyncEvent::NewDynamicLayer.
/// **Coordinator** distributes the permits to PeerActors → peers.
#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
async fn emit_dynamic_layer_permits(
    state: &ScribeState,
    layer_name: &str,
    from_peer: &(String, String),
) {
    // Only nodes issue permits (require permit_issuer + our_permit + sync_event_tx)
    let Some(ref permit_issuer) = state.permit_issuer else { return; };
    let Some(ref our_permit) = state.our_permit else { return; };
    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };

    // Check if layer matches a dynamic schema
    let Some((schema_key, schema, creator_did)) =
        find_matching_dynamic_schema(our_permit, layer_name, &state.page_id) else { return; };

    // Validate creator namespace: sender's DID must match DID in path
    if from_peer.0 != creator_did {
        warn!(
            layer = %layer_name,
            sender = %from_peer.0,
            creator = %creator_did,
            "Creator namespace mismatch — sender DID doesn't match path DID"
        );
        return;
    }

    // Mark the layer as dynamic
    if let Some(unit) = state.units.get(layer_name) {
        // Note: is_dynamic is pub so we'd need get_mut, but we can't mutate here.
        // The flag is informational; permit issuance is the critical path.
        let _ = unit;
    }

    // Collect connected peers with their roles
    let connected_peers = collect_connected_peers_with_roles(state);

    // Prepare layer permits
    let full_layer_name = format!("{}/{}", state.page_id, layer_name);
    match prepare_layer_permits(
        permit_issuer.as_ref(),
        &state.page_id,
        &full_layer_name,
        schema,
        &creator_did,
        &connected_peers,
    ) {
        Ok(permits) if !permits.is_empty() => {
            info!(
                layer = %layer_name,
                schema = %schema_key,
                creator = %creator_did,
                permit_count = permits.len(),
                "Prepared dynamic layer permits, emitting NewDynamicLayer"
            );

            // Add layer permits to node's SubscriberInfo so can_receive_layer() works
            // for subsequent broadcasts. Without this, the node would prepare permits
            // but never actually send the layer data to subscribers.
            if let Ok(mut subs) = state.subscribers.write() {
                for ((did, _device_id), info) in subs.iter_mut() {
                    for (recipient_did, token) in &permits {
                        if did == recipient_did {
                            match gurkha::Permit::from_token(token) {
                                Ok(permit) => {
                                    info.add_layer_permit(permit);
                                    debug!(
                                        recipient = %did,
                                        layer = %layer_name,
                                        "Added layer permit to subscriber"
                                    );
                                }
                                Err(e) => {
                                    warn!(
                                        recipient = %did,
                                        error = %e,
                                        "Failed to parse layer permit for subscriber"
                                    );
                                }
                            }
                        }
                    }
                }
            }

            let event = SyncEvent::NewDynamicLayer {
                page_id: state.page_id.clone(),
                layer_name: full_layer_name,
                permits,
            };

            if let Err(e) = sync_event_tx.send(event).await {
                error!(error = %e, "Failed to emit NewDynamicLayer event");
            }
        }
        Ok(_) => {
            debug!(layer = %layer_name, "No permits needed for dynamic layer");
        }
        Err(e) => {
            error!(layer = %layer_name, error = %e, "Failed to prepare dynamic layer permits");
        }
    }
}

/// Collect connected peers with their roles from subscriber info
///
/// **Context**: Node needs (did, role) pairs for prepare_layer_permits
fn collect_connected_peers_with_roles(state: &ScribeState) -> Vec<(String, String)> {
    let mut peers = Vec::new();

    if let Ok(subs) = state.subscribers.read() {
        for ((did, _device_id), info) in subs.iter() {
            let role = info.permit.relationship().unwrap_or("peer").to_string();
            // Avoid duplicates (same DID, different devices)
            if !peers.iter().any(|(d, _): &(String, String)| d == did) {
                peers.push((did.clone(), role));
            }
        }
    }

    peers
}

/// Get role for a peer from their stored permit
///
/// **Context**: Determining role for Lua validation
/// **Checks**:
/// 1. Sync target (owner/viewer mode) -> our role's counterpart
/// 2. Stored permit (node mode) -> extract role from permit
/// 3. Default -> "peer"
#[instrument(skip(state), fields(page_id = %state.page_id))]
fn get_peer_role(state: &ScribeState, peer_did: &str) -> String {
    // If peer is our sync target, they are the "node" from our perspective
    if let Some(ref config) = state.sync_config {
        if let Some(ref sync_target) = config.sync_target {
            if sync_target == peer_did {
                return "node".to_string();
            }
        }
    }

    // Node mode: look up peer's stored permit and extract role via PermitContext
    if let Some(ref resolver) = state.peer_resolver {
        if let Some(permit_token) = resolver.load_user_permit(peer_did) {
            let role = PermitContext::from_token(&permit_token, &state.page_id, peer_did)
                .map(|ctx| ctx.permit().relationship().unwrap_or("peer").to_string())
                .unwrap_or_else(|_| "peer".to_string());
            debug!(peer_did = %peer_did, role = %role, "Got peer role from stored permit via PermitContext");
            return role;
        }
    }

    // Default role
    "peer".to_string()
}

//! Scribe actor state and configuration types
//!
//! Contains all state structs, type aliases, and configuration for the Scribe actor.

use std::collections::HashMap;
use std::sync::{Arc, Mutex, RwLock};

use tokio::sync::mpsc;

use domains::{Layer, QuerySpec, QueryResult, QueryDelta};

use crate::layer_unit::LayerUnit;
use crate::{
    BroadcastPayload, EphemeralOutbound, PageUpdate, SyncEvent,
    LayerStorageRef, PeerVectorStorageRef, PeerResolverRef, PermitIssuerRef,
};

// Layer Name Normalization

/// Normalize a layer name by stripping `{page_id}/` prefix if present
///
/// **Context**: Lua apps and wire protocol use prefixed names (`{page_id}/messages`)
/// but Scribe stores layers with bare names (`messages`). This strips the prefix
/// at the Scribe boundary so all internal lookups use consistent bare names.
pub fn normalize_layer_name(name: &str, page_id: &str) -> String {
    let prefix = format!("{}/", page_id);
    if let Some(bare) = name.strip_prefix(&prefix) {
        bare.to_string()
    } else {
        name.to_string()
    }
}

// Sync Configuration

/// Sync mode derived from permit capabilities
///
/// **Design**: Capability-based, not role-based
/// - Mode is derived from permit's sync configuration
/// - No hardcoded role names in decision logic
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SyncMode {
    /// Sync to a specific source node (users sync to their node)
    ToSource,
    /// Broadcast to all authorized peers (node mode)
    Broadcast,
}

impl Default for SyncMode {
    fn default() -> Self {
        SyncMode::Broadcast
    }
}

/// Sync configuration derived from permit
///
/// **Context**: Determines how this Scribe syncs based on permit capabilities
/// - ToSource: Sync to a specific source node (owner/viewer/customer)
/// - Broadcast: Broadcast to all authorized peers (node)
#[derive(Debug, Clone)]
pub struct SyncConfig {
    /// Sync mode derived from permit (capability-based)
    pub mode: SyncMode,
    /// For ToSource: node_id to sync to
    /// For Broadcast: None (uses list_authorized_users callback)
    pub sync_target: Option<String>,
}

// Subscriber Types

/// Information about a subscribed peer
///
/// **Design**: Stores the parsed permit directly instead of extracted fields.
/// All access checks delegate to gurkha::Permit methods, ensuring consistency.
pub struct SubscriberInfo {
    /// Parsed page permit for all access checks (static layers)
    /// Stores the full permit so we can use its methods directly
    pub permit: gurkha::Permit,
    /// Layer permits (dynamic layers) — additive, one per dynamic layer
    pub layer_permits: Vec<gurkha::Permit>,
    /// Subscriber's DID (for pattern expansion with {aud})
    /// Extracted from permit audience and normalized to DID format
    pub subscriber_did: String,
    /// Whether this subscriber is visible (from permit presence config)
    /// Visible peers have their entry written to the presence layer
    pub is_visible: bool,
    /// Whether this subscriber can see others' presence
    /// Gates whether the presence layer is synced to this peer
    pub can_see_others: bool,
    /// Display name for this subscriber (from permit presence config)
    pub display_name: Option<String>,
    /// Channel to send CRDT broadcasts
    pub broadcast_tx: mpsc::Sender<BroadcastPayload>,
    /// Channel to send ephemeral broadcasts (cursor, typing)
    /// PeerActor creates this, spawns listener that sends datagrams
    pub ephemeral_tx: Option<mpsc::Sender<EphemeralOutbound>>,
    /// Their last known state vectors (layer_name → version_vector)
    pub vectors: HashMap<String, Vec<u8>>,
}

impl SubscriberInfo {
    /// Check if subscriber can receive updates for layer (two-tier)
    ///
    /// **Context**: Used during broadcast/reconciliation to check read permission
    /// **Two-tier**: Checks page permit (static layers) then layer permits (dynamic layers)
    pub fn can_receive_layer(&self, layer_name: &str, page_id: &str) -> bool {
        // Block presence layer for peers who can't see others
        if (layer_name == "presence" || layer_name.ends_with("/presence")) && !self.can_see_others {
            return false;
        }
        // Check if layer is in no_incoming_updates (sync facts)
        if self.permit.sync_facts().no_incoming_updates.contains(&layer_name.to_string()) {
            return false;
        }
        // Two-tier check: page permit OR any layer permit
        gurkha::can_access_with_layer_permits(
            &self.permit, &self.layer_permits,
            layer_name, page_id, &self.subscriber_did, "read",
        )
    }

    /// Check if subscriber can write to layer (two-tier)
    ///
    /// **Context**: Used during incoming update validation
    /// **Two-tier**: Checks page permit then layer permits
    pub fn can_write_layer(&self, layer_name: &str, page_id: &str) -> bool {
        gurkha::can_access_with_layer_permits(
            &self.permit, &self.layer_permits,
            layer_name, page_id, &self.subscriber_did, "write",
        )
    }

    /// Add a layer permit (additive, no replacement)
    ///
    /// **Context**: Node issued a new layer permit for a dynamic layer
    pub fn add_layer_permit(&mut self, permit: gurkha::Permit) {
        self.layer_permits.push(permit);
    }
}

/// Query subscription info
pub struct QuerySubscriberInfo {
    /// Query specification
    pub spec: QuerySpec,
    /// Channel to send deltas
    pub delta_tx: mpsc::Sender<QueryDelta>,
    /// Current version (monotonically increasing)
    pub version: u64,
    /// Last known result (for computing deltas)
    pub last_result: Option<QueryResult>,
}

// Actor State

/// Scribe actor state
pub struct ScribeState {
    /// Page identifier
    pub page_id: String,
    /// Per-layer compute units (layer_name → LayerUnit)
    pub units: HashMap<String, LayerUnit>,
    /// Peer subscribers (user_did, device_id) → SubscriberInfo
    /// Arc<RwLock> allows Loro observer callback to send directly to peers
    pub subscribers: Arc<RwLock<HashMap<(String, String), SubscriberInfo>>>,
    /// Query subscribers (query_id → QuerySubscriberInfo)
    pub query_subscribers: HashMap<String, QuerySubscriberInfo>,

    /// Layer persistence (saves layer snapshots)
    pub layer_storage: LayerStorageRef,
    /// Peer vector persistence (saves/loads peer state vectors)
    pub vector_storage: PeerVectorStorageRef,
    /// Peer resolver (node mode only) - lists authorized users, loads permits
    pub peer_resolver: Option<PeerResolverRef>,
    /// Permit issuer (node mode only) - issues layer permits for dynamic layers
    pub permit_issuer: Option<PermitIssuerRef>,

    /// Sync configuration derived from permit (mode + sync_target)
    pub sync_config: Option<SyncConfig>,
    /// Channel to emit sync events (EnsureSync) - consumed by Coordinator
    pub sync_event_tx: Option<mpsc::Sender<SyncEvent>>,

    /// Unified page update channel - all events flow through here
    /// **Consumers**: UI/Lua callbacks, Broadcast to peers, Derivation engine
    /// **Design**: Single channel for layer changes, ephemeral data, peer presence
    /// **Arc<RwLock>**: Shared with observer tasks so new subscribers are visible
    pub page_update_subscribers: Arc<RwLock<Vec<mpsc::Sender<PageUpdate>>>>,

    /// Pending update source for observer context
    /// **Context**: Set before import() so observer knows who caused the change
    /// **Usage**: Observer reads this to populate `from_peer` in PageEvent
    /// **Cleared**: After import() completes
    pub pending_update_source: Arc<Mutex<Option<(String, String)>>>,

    // Note: ephemeral events now go through page_update_subscribers (PageUpdate::Ephemeral)
    // outbound ephemeral goes directly via SubscriberInfo.ephemeral_tx (Scribe → PeerActor channels)

    /// Validation handle (for kunki node mode validation)
    /// If provided, Scribe delegates validation to external ValidationService
    /// This enables validation.lua to access presence_lib from LuaRuntime
    /// Falls back to local validation if not available (though we're removing ScribeLuaRuntime)
    pub validation_handle: Option<crate::validation_handle::ValidationHandle>,

    /// Parsed permit - provides should_sync_layer, can_write_layer etc.
    /// Uses gurkha::Permit directly with page_id/did passed to methods
    pub our_permit: Option<gurkha::Permit>,
    /// Our DID (for pattern expansion with {aud})
    pub our_did: String,

    /// Shutdown sender for node script tick loop (if running)
    /// **Context**: Set when is_node=true and entry_node found in manifest
    /// **Usage**: Send () to shutdown the tick loop
    pub node_script_shutdown: Option<mpsc::Sender<()>>,
}

/// Arguments for spawning Scribe
pub struct ScribeArgs {
    pub page_id: String,
    pub layers: HashMap<String, Layer>,

    /// Layer persistence (saves layer snapshots)
    pub layer_storage: LayerStorageRef,
    /// Peer vector persistence (saves/loads peer state vectors)
    pub vector_storage: PeerVectorStorageRef,
    /// Peer resolver (node mode only) - lists authorized users, loads permits
    pub peer_resolver: Option<PeerResolverRef>,
    /// Permit issuer (node mode only) - issues layer permits for dynamic layers
    pub permit_issuer: Option<PermitIssuerRef>,

    /// Optional: Sync configuration derived from permit (relationship + sync_target)
    /// - Owner: sync to sovereign node
    /// - Node: broadcast only (no outbound sync)
    /// - Viewer: sync to source node
    pub sync_config: Option<SyncConfig>,
    /// Channel to emit sync events (EnsureSync) - consumed by Coordinator
    pub sync_event_tx: Option<mpsc::Sender<SyncEvent>>,
    /// Validation handle (for kunki node mode validation)
    /// If provided, Scribe delegates validation to external ValidationService
    pub validation_handle: Option<crate::validation_handle::ValidationHandle>,
    /// Our permit for this page (local write authorization)
    /// Used to check if we can write to a layer before committing
    pub our_permit: Option<String>,
    /// Our DID (for pattern expansion and validation)
    pub our_did: String,
    /// Our username (for node script permit bindings)
    pub our_username: String,
    /// Whether this Scribe runs on a node (enables derivation engine and node scripts)
    pub is_node: bool,
    // Note: ephemeral_broadcast_tx removed - outbound ephemeral now goes directly via
    // SubscriberInfo.ephemeral_tx (Scribe → PeerActor channels)
}

impl ScribeState {
    /// Check if a layer should sync based on permit configuration
    ///
    /// **Context**: Used to filter out local-only layers (sync: false) before broadcasting
    /// **Returns**: true if layer should sync, false if local-only
    pub fn should_sync_layer(&self, layer_name: &str) -> bool {
        self.our_permit
            .as_ref()
            .map(|permit| permit.should_sync_layer(layer_name, &self.page_id, &self.our_did))
            .unwrap_or(true)  // No permit means sync everything
    }

    /// Check if we can write to a layer
    pub fn can_write_layer(&self, layer_name: &str) -> bool {
        self.our_permit
            .as_ref()
            .map(|permit| permit.can_write_layer(layer_name, &self.page_id, &self.our_did))
            .unwrap_or(true)  // No permit means full access
    }
}

