//! Storage trait implementations for Scribe actor
//!
//! Butler's implementations of the scribe storage traits using RedbStore.

use std::collections::HashMap;
use std::sync::Arc;

use scribe::{LayerStorage, PeerVectorStorage, PeerResolver, PermitIssuer, Result, ScribeError};

use tracing::{info, instrument, warn};
use crate::storage::RedbStore;

// Permit Issuer Implementation

/// Butler's implementation of PermitIssuer (node mode only)
///
/// Holds signing key + node's page permit. Scoped to a single page.
/// Scribe never sees the signing key — uses this trait to request permits.
pub struct ButlerPermitIssuer {
    signing_key: [u8; 32],
    node_permit_token: String,
    page_id: String,
}

impl ButlerPermitIssuer {
    pub fn new(signing_key: [u8; 32], node_permit_token: String, page_id: String) -> Self {
        Self { signing_key, node_permit_token, page_id }
    }
}

impl PermitIssuer for ButlerPermitIssuer {
    #[instrument(skip_all, fields(audience = %audience, layer_name = %layer_name))]
    fn issue_layer_permit(
        &self,
        audience: &str,
        layer_name: &str,
        config: gurkha::LayerConfig,
    ) -> Result<(String, String)> {
        info!(page_id = %self.page_id, "ButlerPermitIssuer::issue_layer_permit");
        futures::executor::block_on(gurkha::issue_layer_permit(
            &self.signing_key,
            &self.node_permit_token,
            audience,
            &self.page_id,
            layer_name,
            config,
        )).map_err(|e| {
            warn!(error = %e, "Permit issuance failed");
            ScribeError::Other(format!("Permit issuance failed: {}", e))
        })
    }
}

// Layer Storage Implementation

/// Butler's implementation of LayerStorage
///
/// Saves layer snapshots to RedbStore with AES encryption.
/// Scoped to a single page (page_id passed at construction).
pub struct ButlerLayerStorage {
    store: Arc<RedbStore>,
    page_id: String,
    aes_key: [u8; 32],
}

impl ButlerLayerStorage {
    pub fn new(store: Arc<RedbStore>, page_id: String, aes_key: [u8; 32]) -> Self {
        Self { store, page_id, aes_key }
    }
}

impl LayerStorage for ButlerLayerStorage {
    #[instrument(skip_all)]
    fn save_layer(&self, layer_name: &str, data: &[u8]) -> Result<()> {
        info!(page_id = %self.page_id, layer_name = %layer_name, data_len = data.len(), "ButlerLayerStorage::save_layer");

        // Encrypt layer data
        let encrypted = herald::encrypt_symmetric(&self.aes_key, data)
            .map_err(|e| ScribeError::Other(format!("Encryption failed: {}", e)))?;

        // Save to store
        self.store
            .put_layer(&self.page_id, layer_name, &encrypted)
            .map_err(|e| ScribeError::Other(format!("Store error: {}", e)))
    }
}

// Peer Vector Storage Implementation

/// Butler's implementation of PeerVectorStorage
///
/// Saves/loads peer state vectors to RedbStore.
/// Scoped to a single page (page_id passed at construction).
pub struct ButlerPeerVectorStorage {
    store: Arc<RedbStore>,
    page_id: String,
}

impl ButlerPeerVectorStorage {
    pub fn new(store: Arc<RedbStore>, page_id: String) -> Self {
        Self { store, page_id }
    }
}

impl PeerVectorStorage for ButlerPeerVectorStorage {
    #[instrument(skip_all)]
    fn load_vectors(
        &self,
        user_did: &str,
        device_id: &str,
    ) -> Result<Option<HashMap<String, Vec<u8>>>> {
        self.store
            .get_peer_vectors(&self.page_id, user_did, device_id)
            .map_err(|e| ScribeError::Other(format!("Store error: {}", e)))
    }

    #[instrument(skip_all)]
    fn save_vectors(
        &self,
        user_did: &str,
        device_id: &str,
        vectors: &HashMap<String, Vec<u8>>,
    ) -> Result<()> {
        self.store
            .put_peer_vectors(&self.page_id, user_did, device_id, vectors)
            .map_err(|e| ScribeError::Other(format!("Store error: {}", e)))
    }
}

// Peer Resolver Implementation

/// Butler's implementation of PeerResolver (node mode only)
///
/// Lists authorized users and loads their permits from RedbStore.
/// Scoped to a single page (page_id passed at construction).
pub struct ButlerPeerResolver {
    store: Arc<RedbStore>,
    page_id: String,
}

impl ButlerPeerResolver {
    pub fn new(store: Arc<RedbStore>, page_id: String) -> Self {
        Self { store, page_id }
    }
}

impl PeerResolver for ButlerPeerResolver {
    #[instrument(skip_all)]
    fn list_authorized_users(&self) -> Vec<String> {
        self.store
            .list_authorized_users_for_page(&self.page_id)
            .unwrap_or_default()
    }

    #[instrument(skip_all)]
    fn load_user_permit(&self, user_did: &str) -> Option<String> {
        self.store
            .get_user_page_permit(&self.page_id, user_did)
            .ok()
            .flatten()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const TEST_KEY: [u8; 32] = [1u8; 32];

    fn load_shop_template() -> String {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .parent().unwrap()
            .join("sample_apps/my-shop/permit_template.json");
        std::fs::read_to_string(path).unwrap()
    }

    /// C5: ButlerPermitIssuer issues valid layer permits via gurkha
    #[test]
    fn test_butler_permit_issuer() {
        let template = load_shop_template();

        // Create owner → node delegation chain
        let (owner_token, _) = futures::executor::block_on(
            gurkha::issue_page_owner_token(&TEST_KEY, "page1", &template),
        ).unwrap();
        let (node_token, _) = futures::executor::block_on(
            gurkha::delegate_page(&TEST_KEY, &owner_token, "node", "did:key:node"),
        ).unwrap();

        // Create ButlerPermitIssuer
        let issuer = ButlerPermitIssuer::new(
            TEST_KEY,
            node_token,
            "page1".to_string(),
        );

        // Issue a layer permit
        let config = gurkha::LayerConfig { sync: true, write: true, layer_type: None };
        let (token, cid) = issuer.issue_layer_permit(
            "did:key:viewer",
            "page1/channels/did:key:alice/general/messages",
            config,
        ).unwrap();

        assert!(!token.is_empty());
        assert!(!cid.is_empty());

        // Verify the token is a valid UCAN with the expected layer
        let permit = gurkha::Permit::from_token(&token).unwrap();
        assert_eq!(permit.layers().len(), 1);
        assert!(permit.layers().contains_key("page1/channels/did:key:alice/general/messages"));
    }
}

// Permit Issuer Trait (Node Mode Only)

/// Layer permit issuance (node mode only, scoped to a page)
///
/// **Implemented by**: Butler using signing key + gurkha
/// **Used by**: Scribe layer_unit for issuing layer permits on dynamic layer detection
///
/// Scribe must never hold signing keys. This trait abstracts permit creation
/// so Scribe can request permits without accessing crypto directly.
pub trait PermitIssuer: Send + Sync {
    /// Issue a layer permit for a single dynamic layer
    ///
    /// **Context**: Node detected new dynamic layer, needs to issue permits
    /// **Returns**: (permit_token, cid) — ready to store and send
    fn issue_layer_permit(
        &self,
        audience: &str,
        layer_name: &str,
        config: gurkha::LayerConfig,
    ) -> Result<(String, String)>;
}

// Type Aliases for Convenience

/// Reference-counted layer storage
pub type LayerStorageRef = Arc<dyn LayerStorage>;

/// Reference-counted peer vector storage
pub type PeerVectorStorageRef = Arc<dyn PeerVectorStorage>;

/// Reference-counted peer resolver
pub type PeerResolverRef = Arc<dyn PeerResolver>;

/// Reference-counted permit issuer
pub type PermitIssuerRef = Arc<dyn PermitIssuer>;

// Null Implementations (for testing)

/// Null layer storage that discards all saves
///
/// Useful for testing when persistence isn't needed
pub struct NullLayerStorage;

impl LayerStorage for NullLayerStorage {
    fn save_layer(&self, _layer_name: &str, _data: &[u8]) -> Result<()> {
        Ok(())
    }
}

/// Null peer vector storage that stores nothing
///
/// Useful for testing when peer tracking isn't needed
pub struct NullPeerVectorStorage;

impl PeerVectorStorage for NullPeerVectorStorage {
    fn load_vectors(
        &self,
        _user_did: &str,
        _device_id: &str,
    ) -> Result<Option<HashMap<String, Vec<u8>>>> {
        Ok(None)
    }

    fn save_vectors(
        &self,
        _user_did: &str,
        _device_id: &str,
        _vectors: &HashMap<String, Vec<u8>>,
    ) -> Result<()> {
        Ok(())
    }
}

/// Null peer resolver that has no authorized users
///
/// Useful for testing non-node mode
pub struct NullPeerResolver;

impl PeerResolver for NullPeerResolver {
    fn list_authorized_users(&self) -> Vec<String> {
        Vec::new()
    }

    fn load_user_permit(&self, _user_did: &str) -> Option<String> {
        None
    }
}

/// Null permit issuer that returns test tokens
///
/// Useful for testing when permit issuance isn't needed
pub struct NullPermitIssuer;

impl PermitIssuer for NullPermitIssuer {
    fn issue_layer_permit(
        &self,
        _audience: &str,
        _layer_name: &str,
        _config: gurkha::LayerConfig,
    ) -> Result<(String, String)> {
        Ok(("test-token".into(), "test-cid".into()))
    }
}

