        let page_ids = self.scribe_manager.list_active_page_ids().await;
        let mut result = Vec::new();

        for page_id in page_ids {
            if let Ok(Some(page_data)) = self.pages().get(&page_id) {
                if let Some(permit) = page_data.permit {
