            "{page_id}/products": { "sync": true, "write": false },
            "app:Shop Customer": { "sync": true, "write": false }
        },
        "layer_patterns": {
            "{page_id}/orders/*": { "sync": true }
        },
        "relationship": "sync_consent"
    }
}
```

## Lua Permit API

```lua
