    48→        "Creating dynamic layer"
    49→    );
    50→    let mut unit = LayerUnit::new_empty();
    51→    unit.set_local_only(!state.should_sync_layer(&bare_path));
    52→    unit.is_dynamic = true;
    53→    state.units.insert(bare_path.clone(), unit);
    54→
    55→    // Set up observer for the new layer
    56→    loro_observer::setup_layer_observer(state, &bare_path);
    57→
    58→    Ok(full_name)
    59→}
    60→
    61→/// Generate a dynamic layer path from schema pattern, creator DID, and layer ID
    62→///
    63→/// **Pattern**: `channels/{id}/messages` → `channels/{did}/{layer_id}/messages`
    64→/// **Pattern**: `orders/{id}` → `orders/{did}/{layer_id}`
    65→///
    66→/// The DID is inserted after the first literal segment, and `{id}` is replaced with layer_id.
    67→fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
    68→    let parts: Vec<&str> = schema_key.split('/').collect();
    69→    let mut result = Vec::new();
    70→
    71→    if parts.is_empty() {
    72→        return format!("{}/{}", our_did, layer_id);
    73→    }
    74→
    75→    // First segment: literal
    76→    result.push(parts[0].to_string());
    77→
    78→    // Insert our DID as the second segment (namespace)
    79→    result.push(our_did.to_string());
    80→
    81→    // Remaining segments: replace {id} with layer_id, keep literals
    82→    for part in &parts[1..] {
    83→        if *part == "{id}" {
    84→            result.push(layer_id.to_string());
    85→        } else {
    86→            result.push(part.to_string());
    87→        }
    88→    }
    89→
    90→    result.join("/")
    91→}
    92→
    93→/// Determine recipients and create layer permits for a new dynamic layer
    94→///
    95→/// **Context**: Called by Scribe when detecting a new dynamic layer from a peer.
    96→/// **Returns**: Ready-to-send permits — courier just distributes them.
    97→/// **Uses**: PermitIssuer trait (context-aware gurkha) — never touches signing keys.
    98→pub fn prepare_layer_permits(
    99→    permit_issuer: &dyn PermitIssuer,
   100→    page_id: &str,
   101→    layer_name: &str,
   102→    schema: &gurkha::DynamicLayerSchema,
   103→    creator_did: &str,
   104→    connected_peers: &[(String, String)],  // (did, role)
   105→) -> Result<Vec<(String, String)>, String> {
   106→    let mut permits = Vec::new();
   107→
   108→    match schema.grant {
   109→        gurkha::GrantType::Role => {
   110→            // Role-granted: all peers with matching roles get access
   111→            for (did, role) in connected_peers {
   112→                if let Some(perms) = schema.role_permissions.get(role) {
   113→                    match permit_issuer.issue_layer_permit(did, layer_name, perms.clone()) {
   114→                        Ok((token, _cid)) => {
   115→                            info!(
   116→                                page_id = %page_id,
   117→                                layer = %layer_name,
   118→                                recipient = %did,
   119→                                role = %role,
   120→                                "Issued role-based layer permit"
   121→                            );
   122→                            permits.push((did.clone(), token));
   123→                        }
   124→                        Err(e) => {
   125→                            warn!(
   126→                                page_id = %page_id,
   127→                                layer = %layer_name,
   128→                                recipient = %did,
   129→                                error = %e,
   130→                                "Failed to issue layer permit"
   131→                            );
   132→                        }
   133→                    }
   134→                }
   135→            }
   136→        }
   137→        gurkha::GrantType::Explicit => {
   138→            // Explicit-granted: creator + named participants only
   139→            let default_config = schema.permissions.clone().unwrap_or(
   140→                gurkha::LayerConfig { sync: true, write: true, layer_type: None }
   141→            );
   142→
   143→            // Creator always gets access
   144→            match permit_issuer.issue_layer_permit(creator_did, layer_name, default_config.clone()) {
   145→                Ok((token, _cid)) => {
   146→                    info!(
   147→                        page_id = %page_id,
   148→                        layer = %layer_name,
   149→                        creator = %creator_did,
   150→                        "Issued creator layer permit"
   151→                    );
   152→                    permits.push((creator_did.to_string(), token));
   153→                }
   154→                Err(e) => {
   155→                    warn!(
   156→                        page_id = %page_id,
   157→                        layer = %layer_name,
   158→                        error = %e,
   159→                        "Failed to issue creator layer permit"
   160→                    );
   161→                }
   162→            }
   163→
   164→            // TODO: Named participants (from layer metadata) — Phase 2d
   165→        }
   166→    }
   167→
   168→    Ok(permits)
   169→}
