   567→    if let Some(ref config) = state.sync_config {
   568→        if let Some(ref sync_target) = config.sync_target {
   569→            if sync_target == peer_did {
   570→                return "node".to_string();
   571→            }
   572→        }
   573→    }
   574→
   575→    // Node mode: look up peer's stored permit and extract role via PermitContext
   576→    if let Some(ref resolver) = state.peer_resolver {
