#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DynamicLayerSchema {
    /// Layer type: "map", "list", "text"
    #[serde(rename = "type", default)]
    pub layer_type: String,
    /// Grant type: "role" (all peers) or "explicit" (named participants)
    #[serde(default)]
    pub grant: GrantType,
    /// Permissions per role (for role-granted schemas)
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub role_permissions: HashMap<String, LayerConfig>,
    /// Permissions for explicit grants
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub permissions: Option<LayerConfig>,
}

/// How a dynamic layer is granted to peers
#[derive(Debug, Clone, Serialize, Deserialize, Default, PartialEq)]
#[serde(rename_all = "lowercase")]
pub enum GrantType {
    /// Granted to all peers of matching roles
    #[default]
    Role,
    /// Granted only to explicitly named participants
    Explicit,
}

/// Presence configuration for a peer
///
/// Controls visibility in the /users layer and presence events.

    layer_name: String,
    path: String,
    amount: i64,
},

/// Create a dynamic layer (from Lua app)
///
/// **Context**: Lua calls scribe:create_layer("channels/general/messages")
/// **We do**: Validate schema exists in permit, generate path with our DID, create layer
/// **We reply**: Full layer name (with page_id and DID prefix)
CreateDynamicLayer {
    /// Schema key from dynamic_layer_schemas, e.g. "channels/{id}/messages"
    schema_key: String,
    /// User-chosen ID that fills the {id} in the schema, e.g. "general"
    layer_id: String,
    reply: tokio::sync::oneshot::Sender<std::result::Result<String, String>>,
},

/// Shutdown the actor
Shutdown,

// Ephemeral Events (from datagrams via PeerActor)

/// Remote ephemeral data (from datagram via PeerActor)
///
/// **Context**: Peer sent ephemeral data (cursor, typing, etc.) for this page
/// **We do**: Forward to subscribed apps AND relay to other peers via ephemeral channels
/// **Note**: Not persisted in CRDT - purely ephemeral
/// **Design**: Protocol layer routes opaque bytes; app layer defines meaning
RemoteEphemeral {

    Ok(())
});

// Create a dynamic layer from a schema pattern
//
// Creates a dynamic layer matching a schema defined in the permit's dynamic_layer_schemas.
// The schema_key identifies the pattern (e.g., "channels/{id}/messages"),
// and layer_id fills the {id} placeholder (e.g., "general").
//
// Returns a table with:
//   - layer_name: The full layer name (e.g., "{page_id}/channels/{did}/general/messages")
//
// # Examples
// ```lua
// local result = scribe:create_layer("channels/{id}/messages", "general")
// print(result.layer_name) -- "page1/channels/did:key:alice/general/messages"
// local messages = scribe:list(result.layer_name)
// messages:push({text = "Hello!"})
// ```
methods.add_method("create_layer", |lua, this, (schema_key, layer_id): (String, String)| {
    let layer_name = this.scribe.create_layer(&schema_key, &layer_id)
        .map_err(|e| LuaError::RuntimeError(format!("Failed to create dynamic layer: {}", e)))?;

    let result = lua.create_table()?;
    result.set("layer_name", layer_name)?;
    Ok(result)
});

// Get or create a list layer
//
// Returns a handle to the specified list layer, creating it if it doesn't exist.
// The layer name can include the page_id, e.g., `scribe:list(page_id .. "/messages")`
methods.add_method("list", |_, this, name: String| {
    this.scribe.ensure_list(&name)
        .map_err(|e| LuaError::RuntimeError(e))?;
    Ok(LuaLoroList::new(this.scribe.clone(), name))
});

// Get or create a map layer
//

// -- Dynamic layers --

