     1→//! Coordinator - Minimal peer lifecycle manager
     2→//!
     3→//! The Coordinator handles:
     4→//! - Peer lifecycle (Connected/Disconnected events from transport)
     5→//! - Spawning PeerActors on new connections
     6→//! - Authentication state tracking
     7→//! - Cross-peer operations (relay, broadcast datagrams)
     8→//!
     9→//! All protocol handling is done by PeerActor. App communicates directly with PeerActor
    10→//! for operations like publishing, subscribing, etc.
    11→//!
    12→//! # Generic Transport
    13→//!
    14→//! The Coordinator is generic over `C: Connection` to support different transports:
    15→//! - `Coordinator<IrohConnection>`: Production with NAT traversal
    16→//! - `Coordinator<MockConnection>`: Unit tests with in-memory channels
    17→
    18→mod state;
    19→
    20→use std::marker::PhantomData;
    21→use std::sync::Arc;
    22→
    23→use ractor::{Actor, ActorProcessingErr, ActorRef, SupervisionEvent};
    24→use tracing::{debug, error, info, warn, instrument};
    25→use transport::{Connection, NodeId};
    26→
    27→use tokio::sync::{mpsc, oneshot};
    28→
    29→use crate::handle::CourierEvent;
    30→use crate::peer_actor::{PeerActor, PeerActorArgs, PeerMessage};
    31→use crate::state::PeerType;
    32→use crate::trace::MessageTrace;
    33→use butler::Butler;
    34→
    35→pub use state::{CoordinatorState, PeerEntry, PeerInfo};
    36→
    37→// Type aliases for production use
    38→pub type IrohCoordinator = Coordinator<transport::IrohConnection>;
    39→pub type IrohCoordinatorMessage = CoordinatorMessage<transport::IrohConnection>;
    40→
    41→/// Request for CourierRunner to initiate a connection
    42→#[derive(Debug, Clone)]
    43→pub struct ConnectRequest {
    44→    pub node_id: NodeId,
    45→    pub permit: String,
    46→}
    47→
    48→/// Messages received by Coordinator
    49→///
    50→/// Generic over `C: Connection` to support different transport implementations.
    51→#[derive(Debug)]
    52→pub enum CoordinatorMessage<C: Connection> {
    53→
    54→    /// New connection from transport
    55→    Connected {
    56→        node_id: NodeId,
    57→        conn: C,
    58→    },
    59→
    60→    /// Connection disconnected
    61→    Disconnected { node_id: NodeId },
    62→
    63→    /// PeerActor completed handshake
    64→    PeerAuthenticated {
    65→        node_id: NodeId,
    66→        peer_type: PeerType,
    67→        did: String,
    68→        username: String,
    69→    },
    70→
    71→    /// PeerActor failed
    72→    PeerFailed { node_id: NodeId, reason: String },
    73→
    74→    /// Connect to peer (fire-and-forget, result via CourierEvent)
    75→    ///
    76→    /// **Context**: App wants to connect to a peer
    77→    /// **We do**: Store permit, mark as pending, request transport connection
    78→    /// **Events emitted**: PeerAuthenticated on success, ConnectionFailed on failure
    79→    Connect {
    80→        node_id: NodeId,
    81→        permit: String,
    82→    },
    83→
    84→    /// Get PeerActor reference for direct communication
    85→    GetPeerActor {
    86→        node_id: NodeId,
    87→        response: oneshot::Sender<Option<ActorRef<PeerMessage>>>,
    88→    },
    89→
    90→    /// Relay datagram to other peers (Node mode only)
    91→    RelayDatagram {
    92→        from_node_id: NodeId,
    93→        data: Vec<u8>,
    94→    },
    95→
    96→    /// Broadcast datagram to all authenticated peers
    97→    BroadcastDatagram { data: Vec<u8> },
    98→
    99→    /// Scribe requested sync with a user
   100→    EnsureSync { user_did: String },
   101→
   102→    /// Distribute layer permits for a new dynamic layer (Node mode)
   103→    ///
   104→    /// **Context**: Scribe detected a new dynamic layer, permits already created
   105→    /// **We do**: Store permits in butler, send LayerPermitMsg to each recipient's PeerActor
   106→    DistributeLayerPermits {
   107→        page_id: String,
   108→        layer_name: String,
   109→        permits: Vec<(String, String)>,  // (recipient_did, layer_permit_token)
   110→    },
   111→
   112→    /// Distribute updated page permits to peers (Node mode)
   113→    ///
   114→    /// **Context**: New app installed → page permits reissued with new layers
   115→    /// **We do**: Store updated permits in butler, send PermitUpdate to each recipient's PeerActor
   116→    DistributePagePermitUpdates {
   117→        page_id: String,
   118→        permits: Vec<(String, String)>,  // (recipient_did, new_permit_token)
   119→    },
   120→
   121→    /// Page opened - trigger subscription refresh for all authenticated peers
   122→    ///
   123→    /// **Context**: App opened a page, we need to ensure subscriptions are set up
   124→    /// **We do**: Send RefreshSubscriptions to all authenticated PeerActors
   125→    PageOpened { page_id: String },
   126→
   127→    /// Check if a node is authenticated
   128→    ///
   129→    /// **Context**: Script/app wants to wait for auth before publishing
   130→    /// **Returns**: true if handshake complete, false otherwise
   131→    IsNodeAuthenticated {
   132→        node_id: NodeId,
   133→        response: oneshot::Sender<bool>,
   134→    },
   135→
   136→    /// Shutdown all actors
   137→    Shutdown,
   138→}
   139→
   140→/// Courier mode (User or Node)
   141→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
   142→pub enum CourierMode {
   143→    /// Running as user's device (connects TO node)
   144→    User,
   145→    /// Running as always-on node (accepts connections)
   146→    Node,
   147→}
   148→
   149→/// Coordinator manages all PeerActors
   150→///
   151→/// Generic over `C: Connection` to support different transport implementations.
   152→pub struct Coordinator<C: Connection> {
   153→    _phantom: PhantomData<C>,
   154→}
   155→
   156→impl<C: Connection> Coordinator<C> {
   157→    pub fn new() -> Self {
   158→        Self { _phantom: PhantomData }
   159→    }
   160→
   161→    /// Emit an event to the app layer via event_tx channel
   162→    fn emit_event(state: &CoordinatorState<C>, event: CourierEvent) {
   163→        if let Some(tx) = &state.event_tx {
   164→            if let Err(e) = tx.try_send(event) {
   165→                warn!("Failed to emit event: {}", e);
   166→            }
   167→        }
   168→    }
   169→
   170→    /// Process a ConnectionEvent and convert to CoordinatorMessage
   171→    ///
   172→    /// **Note**: Transport now only emits lifecycle events (Connected/Disconnected).
   173→    /// Message reading is done by PeerSession directly from the Connection.
   174→    pub fn from_connection_event(event: transport::ConnectionEvent<C>) -> Option<CoordinatorMessage<C>> {
   175→        match event {
   176→            transport::ConnectionEvent::Connected { node_id, conn } => {
   177→                Some(CoordinatorMessage::Connected { node_id, conn })
   178→            }
   179→            transport::ConnectionEvent::Disconnected { node_id } => {
   180→                Some(CoordinatorMessage::Disconnected { node_id })
   181→            }
   182→        }
   183→    }
   184→}
   185→
   186→impl<C: Connection> Default for Coordinator<C> {
   187→    fn default() -> Self {
   188→        Self::new()
   189→    }
   190→}
   191→
   192→impl<C: Connection> Actor for Coordinator<C> {
   193→    type Msg = CoordinatorMessage<C>;
   194→    type State = CoordinatorState<C>;
   195→    type Arguments = (
   196→        NodeId,
   197→        CourierMode,
   198→        Arc<Butler>,
   199→        crate::peer_actor::BlobStore,
   200→        Option<mpsc::Sender<ConnectRequest>>,
   201→        Option<mpsc::Sender<CourierEvent>>,
   202→        Option<mpsc::UnboundedSender<MessageTrace>>,
   203→    );
   204→
   205→    #[instrument(skip_all)]
   206→    async fn pre_start(
   207→        &self,
   208→        _myself: ActorRef<Self::Msg>,
   209→        args: Self::Arguments,
   210→    ) -> Result<Self::State, ActorProcessingErr> {
   211→        let (our_node_id, mode, butler, blob_store, connect_tx, event_tx, message_tx) = args;
   212→
   213→        info!("Coordinator started in {:?} mode (node_id={})", mode, our_node_id);
   214→
   215→        Ok(CoordinatorState::new(
   216→            our_node_id,
   217→            mode,
   218→            butler,
   219→            blob_store,
   220→            connect_tx,
   221→            event_tx,
   222→            message_tx,
   223→        ))
   224→    }
   225→
   226→    async fn handle(
   227→        &self,
   228→        myself: ActorRef<Self::Msg>,
   229→        message: Self::Msg,
   230→        state: &mut Self::State,
   231→    ) -> Result<(), ActorProcessingErr> {
   232→        match message {
   233→
   234→            CoordinatorMessage::Connected { node_id, conn } => {
   235→                self.on_connected(myself.clone(), node_id, conn, state).await;
   236→            }
   237→
   238→            CoordinatorMessage::Disconnected { node_id } => {
   239→                self.on_disconnected(node_id, state).await;
   240→            }
   241→
   242→            CoordinatorMessage::PeerAuthenticated {
   243→                node_id,
   244→                peer_type,
   245→                did,
   246→                username,
   247→            } => {
   248→                info!("Peer authenticated: {} ({}) - {:?}", username, node_id, peer_type);
   249→                state.authenticate_peer(node_id, peer_type, did.clone(), username.clone());
   250→
   251→                // Mark sovereign node as connected (for User mode connecting to their Node)
   252→                if peer_type == PeerType::MyNode {
   253→                    let node_id_str = node_id.to_string();
   254→                    match state.butler.nodes().set_connected(&node_id_str, true) {
   255→                        Ok(true) => info!("Marked sovereign node {} as connected", node_id_str),
   256→                        Ok(false) => debug!("Sovereign node {} not found in storage", node_id_str),
   257→                        Err(e) => warn!("Failed to mark sovereign node connected: {}", e),
   258→                    }
   259→                }
   260→
   261→                // Emit event for app layer
   262→                Self::emit_event(state, CourierEvent::PeerAuthenticated {
   263→                    node_id: node_id.to_string(),
   264→                    did,
   265→                    username,
   266→                });
   267→            }
   268→
   269→            CoordinatorMessage::PeerFailed { node_id, reason } => {
   270→                warn!("Peer failed: {} - {}", node_id, reason);
   271→
   272→                // Emit failure event for app layer
   273→                Self::emit_event(state, CourierEvent::ConnectionFailed {
   274→                    node_id: node_id.to_string(),
   275→                    error: reason,
   276→                });
   277→
   278→                state.remove_peer(node_id);
   279→            }
   280→
   281→            CoordinatorMessage::Connect { node_id, permit } => {
   282→                self.on_connect(node_id, permit, state).await;
   283→            }
   284→
   285→            CoordinatorMessage::GetPeerActor { node_id, response } => {
   286→                let actor = state.get_actor(&node_id).cloned();
   287→                let _ = response.send(actor);
   288→            }
   289→
   290→            CoordinatorMessage::RelayDatagram { from_node_id, data } => {
   291→                if state.mode == CourierMode::Node {
   292→                    for (peer_node_id, entry) in state.authenticated_peers() {
   293→                        if peer_node_id != from_node_id {
   294→                            if let Err(e) = entry.conn.send_datagram(&data) {
   295→                                debug!(from = %from_node_id, to = %peer_node_id, error = %e, "Failed to relay datagram");
   296→                            }
   297→                        }
   298→                    }
   299→                }
   300→            }

