   432→/// **Context**: Node receives a new layer from peer. If it matches a dynamic schema,
   433→/// prepare layer permits for all connected peers and emit SyncEvent::NewDynamicLayer.
   434→/// **Coordinator** distributes the permits to PeerActors → peers.
   435→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
   436→async fn emit_dynamic_layer_permits(
   437→    state: &ScribeState,
