   439→    from_peer: &(String, String),
   440→) {
   441→    // Only nodes issue permits (require permit_issuer + our_permit + sync_event_tx)
   442→    let Some(ref permit_issuer) = state.permit_issuer else { return; };
   443→    let Some(ref our_permit) = state.our_permit else { return; };
   444→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
   445→
   446→    // Check if layer matches a dynamic schema
   447→    let Some((schema_key, schema, creator_did)) =
   448→        find_matching_dynamic_schema(our_permit, layer_name, &state.page_id) else { return; };
   449→
   450→    // Validate creator namespace: sender's DID must match DID in path
   451→    if from_peer.0 != creator_did {
   452→        warn!(
   453→            layer = %layer_name,
   454→            sender = %from_peer.0,
   455→            creator = %creator_did,
   456→            "Creator namespace mismatch — sender DID doesn't match path DID"
   457→        );
   458→        return;
