   171→/// Find matching dynamic schema for a layer received from a peer
   172→///
   173→/// **Context**: Node receives a new layer from peer. Check if it matches a dynamic schema.
   174→/// **Returns**: (schema_key, schema, creator_did) if matched, None otherwise
   175→pub fn find_matching_dynamic_schema<'a>(
   176→    permit: &'a gurkha::Permit,
   177→    layer_name: &str,
   178→    page_id: &str,
   179→) -> Option<(&'a str, &'a gurkha::DynamicLayerSchema, String)> {
   180→    let schemas = permit.dynamic_layer_schemas();
   181→    if schemas.is_empty() {
   182→        return None;
   183→    }
   184→
   185→    // Strip page_id prefix to get bare layer path
   186→    let page_prefix = format!("{}/", page_id);
   187→    let bare_path = layer_name.strip_prefix(&page_prefix).unwrap_or(layer_name);
   188→
   189→    let path_parts: Vec<&str> = bare_path.split('/').collect();
   190→
   191→    // Path must have at least 3 segments: prefix/did/id[/suffix]
   192→    if path_parts.len() < 3 {
   193→        return None;
   194→    }
   195→
   196→    // Second segment should be a DID (the creator)
   197→    let potential_creator = path_parts[1];
   198→    if !potential_creator.starts_with("did:") {
   199→        return None;
   200→    }
   201→
   202→    // Try each schema pattern
   203→    for (schema_key, schema) in schemas {
   204→        let pattern_parts: Vec<&str> = schema_key.split('/').collect();
   205→
   206→        // Dynamic path has one extra segment (DID) compared to pattern
   207→        if path_parts.len() != pattern_parts.len() + 1 {
   208→            continue;
   209→        }
   210→
   211→        // First segment must match literally
   212→        if path_parts[0] != pattern_parts[0] {
   213→            continue;
   214→        }
   215→
   216→        // path[2..] must match pattern[1..] (with {id} as wildcard)
   217→        let mut matched = true;
   218→        for (path_seg, pat_seg) in path_parts[2..].iter().zip(pattern_parts[1..].iter()) {
   219→            if *pat_seg != "{id}" && path_seg != pat_seg {
   220→                matched = false;
   221→                break;
   222→            }
   223→        }
   224→
   225→        if matched {
   226→            return Some((schema_key, schema, potential_creator.to_string()));
   227→        }
   228→    }
   229→
   230→    None
   231→}
