   461→/// Issue a space sync consent permit
   462→///
   463→/// **Context**: Viewer issues this permit back to the node after receiving SpaceSync.
   464→/// It expresses the viewer's consent to receive sync updates and new pages for this space.
   465→///
   466→/// **Issued by**: Viewer
   467→/// **Audience**: Node (specific node pubkey/DID)
   468→/// **Proof**: Node's original viewer permit (establishes delegation chain)
   469→///
   470→/// # Arguments
   471→/// * `signing_key_bytes` - Viewer's 32-byte Ed25519 secret key
   472→/// * `node_pubkey` - Node's public key (audience of the consent permit)
   473→/// * `space_id` - Space identifier
   474→/// * `node_viewer_permit` - Node's original permit issued to the viewer (used as proof)
   475→/// * `template_json` - JSON template for the consent permit (SYNC_SPACE_CONSENT_TEMPLATE)
   476→///
   477→/// # Returns
   478→/// * `Ok((token, cid))` - The consent permit token and its CID
   479→#[instrument(skip(signing_key_bytes, node_viewer_permit, template_json), fields(space_id = %space_id, token_type = "sync_space_consent"))]
   480→pub async fn issue_sync_space_consent(
   481→    signing_key_bytes: &[u8; 32],
   482→    node_pubkey: &str,
   483→    space_id: &str,
   484→    node_viewer_permit: &str,
   485→    template_json: &str,
   486→) -> ServiceResult<(String, String)> {
   487→    trace!("Issuing space sync consent permit");
   488→
   489→    let signing_key = SigningKey::from_bytes(signing_key_bytes);
   490→    let verifying_key = signing_key.verifying_key();
   491→
   492→    let token_decision = decision::decide_sync_space_consent(
   493→        &verifying_key,
   494→        node_pubkey,
   495→        space_id,
   496→        node_viewer_permit,
   497→        template_json,
   498→    )?;
   499→
   500→    let (token, cid) = crypto::sign_permit(signing_key_bytes, &token_decision).await?;
   501→
   502→    info!("Space sync consent permit issued: cid={}", cid);
   503→    Ok((token, cid))
   504→}
