     1→//! Handshake decision logic
     2→//!
     3→//! Pure decision functions for handshake state machine.
     4→//! PeerActor calls these to decide what to do, then executes.
     5→//!
     6→//! ## Design (Capability-Based)
     7→//!
     8→//! The protocol is completely role-agnostic. All decisions are based on
     9→//! capabilities derived directly from the permit structure:
    10→//!
    11→//! - `accept_publish: true` → Peer can publish spaces to this node
    12→//! - `first_connection: true` → First time connecting (needs OwnerInfo stored)
    13→//! - `relay: true` → Can forward data to other peers
    14→//! - `share: true` → Can issue delegated permits
    15→//!
    16→//! ## Security Model
    17→//!
    18→//! - **Capabilities in permit**: No hardcoded role names
    19→//! - **Uniform handshake**: Same flow for all peers, capabilities determine behavior
    20→//! - **Bidirectional permits**: Both sides issue permits to authenticate
    21→
    22→use gurkha::{Permit, PeerCapabilities};
    23→
    24→/// Extract peer capabilities from permit
    25→///
    26→/// **Context**: Determining behavior from the permit in connection string
    27→/// **We read**: `peer_capabilities` from permit facts
    28→/// **We return**: PeerCapabilities struct with all capability flags
    29→pub fn extract_capabilities(permit: &Permit) -> PeerCapabilities {
    30→    permit.peer_capabilities().clone()
    31→}
    32→
    33→/// Check if permit indicates first connection
    34→pub fn is_first_connection(permit: &Permit) -> bool {
    35→    permit.is_first_connection()
    36→}
    37→
    38→/// Check if permit allows publishing spaces
    39→pub fn can_publish(permit: &Permit) -> bool {
    40→    permit.peer_capabilities().accept_publish
    41→}
    42→
    43→/// Decision for how to respond to Hello message (Node mode)
    44→///
    45→/// **Context**: Node received Hello from a peer
    46→/// **Decision**: Accept with appropriate handling, or reject with reason
    47→///
    48→/// Note: Decisions are capability-based, not role-based.
    49→#[derive(Debug, Clone)]
    50→pub enum HelloDecision {
    51→    /// Accept first connection from peer who can publish
    52→    /// - Store OwnerInfo
    53→    /// - Issue peer_connection permit
    54→    AcceptFirstConnection {
    55→        /// Peer can publish spaces to this node
    56→        can_publish: bool,
    57→    },
    58→    /// Accept reconnection from known peer
    59→    /// - Use stored permit
    60→    AcceptReconnection {
    61→        stored_permit: String,
    62→        can_publish: bool,
    63→    },
    64→    /// Accept connection from peer (not first, not owner reconnection)
    65→    AcceptPeer,
    66→    /// Reject - already have a different owner
    67→    RejectAlreadyHasOwner,
    68→    /// Reject - owner DID mismatch on reconnection
    69→    RejectOwnerMismatch,
    70→    /// Reject - no owner for reconnection attempt
    71→    RejectNoOwnerForReconnection,
    72→}
    73→
    74→/// Context for Hello decision
    75→///
    76→/// **Context**: Node building decision context from incoming Hello
    77→/// **Courier provides**: Parsed permit, incoming DID, existing owner info
    78→pub struct HelloContext<'a> {
    79→    pub incoming_permit: &'a Permit,
    80→    pub incoming_did: &'a str,
    81→    pub existing_owner_did: Option<&'a str>,
    82→    pub existing_owner_permit: Option<&'a str>,
    83→}
    84→
    85→/// Decide how to respond to Hello (Node mode)
    86→///
    87→/// **Context**: Node received Hello with permit, needs to decide response
    88→/// **We check**: Capabilities (can_publish), first_connection flag
    89→/// **We decide**: Accept/reject based on existing state and capabilities
    90→///
    91→/// # Arguments
    92→/// * `ctx` - Context with incoming permit and existing owner state
    93→///
    94→/// # Returns
    95→/// Decision enum indicating how courier should respond
    96→pub fn decide_hello_response(ctx: &HelloContext) -> HelloDecision {
    97→    let caps = extract_capabilities(ctx.incoming_permit);
    98→    let is_first = is_first_connection(ctx.incoming_permit);
    99→
   100→    if caps.accept_publish {
   101→        // Peer wants to publish - check owner state
   102→        if is_first {
   103→            match ctx.existing_owner_did {
   104→                Some(_) => HelloDecision::RejectAlreadyHasOwner,
   105→                None => HelloDecision::AcceptFirstConnection { can_publish: true },
   106→            }
   107→        } else {
   108→            // Reconnection - verify it's the same owner
   109→            match (ctx.existing_owner_did, ctx.existing_owner_permit) {
   110→                (Some(owner_did), Some(permit)) if owner_did == ctx.incoming_did => {
   111→                    HelloDecision::AcceptReconnection {
   112→                        stored_permit: permit.to_string(),
   113→                        can_publish: true,
   114→                    }
   115→                }
   116→                (Some(_), _) => HelloDecision::RejectOwnerMismatch,
   117→                (None, _) => HelloDecision::RejectNoOwnerForReconnection,
   118→            }
   119→        }
   120→    } else {
   121→        // Regular peer connection (no publish capability)
   122→        HelloDecision::AcceptPeer
   123→    }
   124→}
   125→
   126→/// Decision for how to respond to Welcome message (User mode)
   127→///
   128→/// **Context**: User received Welcome from node
   129→/// **Decision**: Accept and issue reciprocal permit, or reject
   130→#[derive(Debug, Clone)]
   131→pub enum WelcomeDecision {
   132→    /// Accept - permit valid, issue reciprocal
   133→    Accept {
   134→        /// Whether we can publish to this node
   135→        can_publish: bool,
   136→    },
   137→    /// Reject - node public key doesn't match connection string
   138→    RejectNodeMismatch,
   139→    /// Reject - permit audience doesn't match our DID
   140→    RejectAudienceMismatch,
   141→}
   142→
   143→/// Context for Welcome decision
   144→///
   145→/// **Context**: User building decision context from incoming Welcome
   146→/// **User provides**: Our permit (for capabilities), our identifiers, expected node pubkey, received permit
   147→pub struct WelcomeContext<'a> {
   148→    /// Our outgoing permit (to extract capabilities)
   149→    pub our_permit: &'a Permit,
   150→    pub our_did: &'a str,
   151→    /// Our public key in base64 - permits use this as audience, not DID
   152→    pub our_pubkey_b64: &'a str,
   153→    pub expected_node_pubkey: &'a [u8],
   154→    pub received_node_pubkey: &'a [u8],
   155→    pub received_permit: &'a Permit,
   156→}
   157→
   158→/// Decide how to respond to Welcome (User mode)
   159→///
   160→/// **Context**: User received Welcome with node's permit
   161→/// **We verify**: Node identity, permit audience
   162→/// **Security**: Uniform validation for all peers
   163→///
   164→/// # Arguments
   165→/// * `ctx` - Context with our permit, expected node identity, received permit
   166→///
   167→/// # Returns
   168→/// Decision enum indicating acceptance or rejection
   169→pub fn decide_welcome_response(ctx: &WelcomeContext) -> WelcomeDecision {
   170→    // 1. Verify node identity matches connection string
   171→    if !ctx.expected_node_pubkey.is_empty() && ctx.expected_node_pubkey != ctx.received_node_pubkey {
   172→        return WelcomeDecision::RejectNodeMismatch;
   173→    }
   174→
   175→    // 2. Verify permit audience is us (or wildcard)
   176→    // Note: Permits use base64 pubkey as audience, not DID
   177→    if let Some(aud) = ctx.received_permit.audience() {
   178→        if aud != "*" && aud != ctx.our_pubkey_b64 && aud != ctx.our_did {
   179→            return WelcomeDecision::RejectAudienceMismatch;
   180→        }
   181→    }
   182→
   183→    // Extract our capabilities to pass through
   184→    let caps = extract_capabilities(ctx.our_permit);
   185→
   186→    // All checks passed
   187→    WelcomeDecision::Accept {
   188→        can_publish: caps.accept_publish,
   189→    }
   190→}
   191→
   192→/// Decision for how to respond to PermitGrant message (Node mode)
   193→///
   194→/// **Context**: Node received PermitGrant from user with their permit
   195→/// **Decision**: Accept and complete handshake, or reject
   196→#[derive(Debug, Clone)]
   197→pub enum PermitGrantDecision {
   198→    /// Accept - permit valid, complete handshake
   199→    Accept {
   200→        /// Whether peer can publish to this node
   201→        can_publish: bool,
   202→    },
   203→    /// Reject - permit audience isn't us
   204→    RejectAudienceMismatch,
   205→    /// Reject - permit issuer isn't the peer
   206→    RejectIssuerMismatch,
   207→}
   208→
   209→/// Context for PermitGrant decision
   210→///
   211→/// **Context**: Node building decision context from incoming PermitGrant
   212→/// **Node provides**: Peer's capabilities (from Hello), our pubkey (base64), their DID, received permit
   213→pub struct PermitGrantContext<'a> {
   214→    /// Capabilities we determined from their Hello permit
   215→    pub peer_can_publish: bool,
   216→    /// Our public key base64-encoded - this is what peer uses as audience
   217→    pub our_pubkey_b64: &'a str,
   218→    pub their_did: &'a str,
   219→    pub received_permit: &'a Permit,
   220→}
   221→
   222→/// Decide how to respond to PermitGrant (Node mode)
   223→///
   224→/// **Context**: Node received PermitGrant with user's reciprocal permit
   225→/// **We verify**: Permit audience (us), issuer (them)
   226→///
   227→/// # Arguments
   228→/// * `ctx` - Context with peer capabilities, DIDs, received permit
   229→///
   230→/// # Returns
   231→/// Decision enum indicating acceptance or rejection
   232→pub fn decide_permit_grant_response(ctx: &PermitGrantContext) -> PermitGrantDecision {
   233→    // 1. Verify permit audience is our base64-encoded public key
   234→    if let Some(aud) = ctx.received_permit.audience() {
   235→        if aud != ctx.our_pubkey_b64 {
   236→            return PermitGrantDecision::RejectAudienceMismatch;
   237→        }
   238→    }
   239→
   240→    // 2. Verify permit issuer is them
   241→    if let Some(iss) = ctx.received_permit.issuer() {
   242→        if iss != ctx.their_did {
   243→            return PermitGrantDecision::RejectIssuerMismatch;
   244→        }
   245→    }
   246→
   247→    // Accept with capability info
   248→    PermitGrantDecision::Accept {
   249→        can_publish: ctx.peer_can_publish,
   250→    }
   251→}
