    32→    #[instrument(skip(self, state), fields(space_id = %space_id))]
    33→    pub(super) async fn initiate_publish_space(&self, space_id: &str, state: &mut PeerActorState<C>) {
    34→        if require_user_mode(state.mode, "initiate_publish_space").is_some() {
