    54→                return;
    55→            }
    56→        };
    57→
    58→        // Delegate permit to node
    59→        let node_pubkey = self.node_id.to_string();
    60→        let delegated_permit = match state.butler.spaces().delegate_to_node(space_id, &node_pubkey).await {
    61→            Ok(permit) => permit,
    62→            Err(e) => {
