     1→//! ScribeHandle trait — abstracts Scribe actor access for testability
     2→//!
     3→//! **Pattern**: Follows the same trait extraction pattern as `LayerStorage`/`PeerVectorStorage`
     4→//! in `scribe/src/storage.rs`.
     5→//!
     6→//! **Production**: `ActorScribeHandle` wraps `ActorRef<ScribeMessage>` with `block_on_async()`
     7→//! **Testing**: `MockScribeHandle` (in `mock_scribe.rs`) uses in-memory HashMap storage
     8→
     9→use serde_json::Value as JsonValue;
    10→use std::sync::Arc;
    11→
    12→/// Abstraction over Scribe actor operations used by Lua bindings
    13→///
    14→/// All methods are synchronous (blocking) because Lua runtime runs on an OS thread
    15→/// without a tokio runtime. Implementations handle the async-to-sync bridge internally.
    16→pub trait ScribeHandle: Send + Sync {
    17→    // -- Layer lifecycle --
    18→
    19→    /// Ensure a list layer exists (creates if needed)
    20→    fn ensure_list(&self, layer_name: &str) -> Result<(), String>;
    21→
    22→    /// Ensure a map layer exists (creates if needed)
    23→    fn ensure_map(&self, layer_name: &str) -> Result<(), String>;
    24→
    25→    /// Create an empty derived layer (for derivation engine)
    26→    fn create_derived_layer(&self, target_layer: &str) -> Result<(), String>;
    27→
    28→    // -- List operations --
    29→
    30→    /// Push item to end of list
    31→    fn list_push(&self, layer_name: &str, path: &str, item: JsonValue) -> Result<(), String>;
    32→
    33→    /// Insert item at index
    34→    fn list_insert(
    35→        &self,
    36→        layer_name: &str,
    37→        path: &str,
    38→        index: usize,
    39→        item: JsonValue,
    40→    ) -> Result<(), String>;
    41→
    42→    /// Delete item at index
    43→    fn list_delete(&self, layer_name: &str, path: &str, index: usize) -> Result<(), String>;
    44→
    45→    /// Get item at index
    46→    fn list_get(&self, layer_name: &str, index: usize) -> Result<Option<JsonValue>, String>;
    47→
    48→    /// Get list length
    49→    fn list_length(&self, layer_name: &str) -> Result<usize, String>;
    50→
    51→    // -- Map operations --
    52→
    53→    /// Insert or update a key-value pair
    54→    fn map_insert(
    55→        &self,
    56→        layer_name: &str,
    57→        path: &str,
    58→        key: &str,
    59→        value: JsonValue,
    60→    ) -> Result<(), String>;
    61→
    62→    /// Get value by key
    63→    fn map_get(&self, layer_name: &str, key: &str) -> Result<Option<JsonValue>, String>;
    64→
    65→    /// Delete key from map
    66→    fn map_delete(&self, layer_name: &str, path: &str, key: &str) -> Result<(), String>;
    67→
    68→    /// Get map length
    69→    fn map_length(&self, layer_name: &str) -> Result<usize, String>;
    70→
    71→    /// Get all keys from map
    72→    fn map_keys(&self, layer_name: &str) -> Result<Vec<String>, String>;
    73→
    74→    // -- Query --
    75→
    76→    /// List layer names matching a glob pattern
    77→    fn list_layers(&self, pattern: &str) -> Result<Vec<String>, String>;
    78→
    79→    /// Get layer content as JSON (returns None if layer doesn't exist)
    80→    fn get_layer_json(&self, layer_name: &str) -> Result<Option<JsonValue>, String>;
    81→
    82→    /// Get layer data as JSON (returns error if layer doesn't exist)
    83→    fn get_layer_data(&self, layer_name: &str) -> Result<JsonValue, String>;
    84→
    85→    // -- Dynamic layers --
    86→
    87→    /// Create a dynamic layer from a schema pattern
    88→    ///
    89→    /// **Context**: Lua app calls `scribe:create_layer("channels/{id}/messages", "general")`
    90→    /// **Returns**: Full layer name (e.g., "{page_id}/channels/{our_did}/general/messages")
    91→    fn create_layer(&self, schema_key: &str, layer_id: &str) -> Result<String, String>;
    92→
    93→    // -- Peers & Ephemeral --
    94→
    95→    /// Get count of subscribers to this page
    96→    fn get_subscriber_count(&self) -> usize;
    97→
    98→    /// Send ephemeral data to all peers
    99→    fn send_ephemeral(&self, payload: Vec<u8>) -> Result<(), String>;
   100→}
   101→
   102→// -- Production implementation: ActorScribeHandle --
   103→
   104→use ractor::ActorRef;
   105→use scribe::ScribeMessage;
   106→use tokio::sync::oneshot;
   107→
   108→/// Helper: block_on an async oneshot that returns `Result<T, ScribeError>`,
   109→/// flattening both channel errors and scribe errors to `String`.
   110→fn rpc<T, E: std::fmt::Display>(rx: oneshot::Receiver<Result<T, E>>) -> Result<T, String> {
   111→    let inner = match tokio::runtime::Handle::try_current() {
   112→        Ok(handle) => tokio::task::block_in_place(|| handle.block_on(rx)),
   113→        Err(_) => futures::executor::block_on(rx),
   114→    };
   115→    inner
   116→        .map_err(|e| format!("Channel error: {}", e))?
   117→        .map_err(|e| format!("{}", e))
   118→}
   119→
   120→/// Helper: block_on an async oneshot that returns `T` directly (no inner Result)
   121→fn rpc_direct<T>(rx: oneshot::Receiver<T>) -> Result<T, String> {
   122→    let result = match tokio::runtime::Handle::try_current() {
   123→        Ok(handle) => tokio::task::block_in_place(|| handle.block_on(rx)),
   124→        Err(_) => futures::executor::block_on(rx),
   125→    };
   126→    result.map_err(|e| format!("Channel error: {}", e))
   127→}
   128→
   129→/// Production ScribeHandle wrapping an `ActorRef<ScribeMessage>`
   130→///
   131→/// All operations delegate to the Scribe actor via cast/call with `block_on_async`.
   132→/// Identical behavior to the previous direct `scribe_ref` usage in bindings.
   133→pub struct ActorScribeHandle {
   134→    scribe_ref: ActorRef<ScribeMessage>,
   135→}
   136→
   137→impl ActorScribeHandle {
   138→    pub fn new(scribe_ref: ActorRef<ScribeMessage>) -> Arc<dyn ScribeHandle> {
   139→        Arc::new(Self { scribe_ref })
   140→    }
   141→
   142→    /// Get the underlying ActorRef (for operations not covered by the trait,
   143→    /// like SubscribeToPageUpdates)
   144→    pub fn actor_ref(&self) -> &ActorRef<ScribeMessage> {
   145→        &self.scribe_ref
   146→    }
   147→}
   148→
   149→impl ScribeHandle for ActorScribeHandle {
   150→    fn ensure_list(&self, layer_name: &str) -> Result<(), String> {
   151→        let (tx, rx) = oneshot::channel();
   152→        self.scribe_ref
   153→            .cast(ScribeMessage::EnsureLoroList {
   154→                layer_name: layer_name.to_string(),
   155→                reply: tx,
   156→            })
   157→            .map_err(|e| format!("Failed to ensure list: {}", e))?;
   158→        rpc(rx)
   159→    }
   160→
   161→    fn ensure_map(&self, layer_name: &str) -> Result<(), String> {
   162→        let (tx, rx) = oneshot::channel();
   163→        self.scribe_ref
