     1→//! MockScribeHandle — in-memory ScribeHandle for testing
     2→//!
     3→//! No Loro, no actors, no network. Pure HashMap-based storage.
     4→//! Provides inspection methods for test assertions.
     5→//!
     6→//! **Reactive**: Mutations notify all registered subscribers via `LuaCommand::LoroChanged`
     7→//! with `full_data` (no delta/ops — uses the Replace fallback path, works for both lists and maps).
     8→
     9→use std::collections::HashMap;
    10→use std::sync::{Arc, Mutex};
    11→
    12→use serde_json::Value as JsonValue;
    13→use tokio::sync::mpsc;
    14→
    15→use crate::commands::LuaCommand;
    16→use crate::scribe_handle::ScribeHandle;
    17→
    18→/// Layer storage variants
    19→#[derive(Debug, Clone)]
    20→enum MockLayer {
    21→    List(Vec<JsonValue>),
    22→    Map(HashMap<String, JsonValue>),
    23→}
    24→
    25→/// Shared state for MockScribeHandle
    26→///
    27→/// Wrapped in Arc<Mutex<>> so multiple handles can share state
    28→/// (simulates multiple peers on the same page).
    29→///
    30→/// **Reactive**: Register `lua_tx` channels via `register_subscriber()`.
    31→/// Every mutation sends `LuaCommand::LoroChanged { full_data }` to all subscribers.
    32→///
    33→/// **Layer normalization**: Like the real Scribe, strips `page_id/` prefix from layer names.
    34→/// Lua calls `scribe:list(page_id .. "/messages")` but layers are stored as `"messages"`.
    35→pub struct MockScribeState {
    36→    layers: HashMap<String, MockLayer>,
    37→    ephemerals: Vec<Vec<u8>>,
    38→    subscriber_count: usize,
    39→    /// Page ID for layer name normalization (strips "page_id/" prefix)
    40→    page_id: Option<String>,
    41→    /// Registered Lua runtime channels — notified on every mutation
    42→    subscribers: Vec<mpsc::Sender<LuaCommand>>,
    43→}
    44→
    45→impl MockScribeState {
    46→    fn new() -> Self {
    47→        Self {
    48→            layers: HashMap::new(),
    49→            ephemerals: Vec::new(),
    50→            subscriber_count: 0,
    51→            page_id: None,
    52→            subscribers: Vec::new(),
    53→        }
    54→    }
    55→
    56→    /// Set page ID for layer name normalization
    57→    ///
    58→    /// **Context**: Lua calls `scribe:list(page_id .. "/messages")` with a prefix.
    59→    /// Real Scribe strips this prefix. The mock must do the same.
    60→    pub fn set_page_id(&mut self, page_id: &str) {
    61→        self.page_id = Some(page_id.to_string());
    62→    }
    63→
    64→    /// Normalize layer name — strip `page_id/` prefix (matches real Scribe behavior)
    65→    fn normalize(&self, name: &str) -> String {
    66→        if let Some(ref page_id) = self.page_id {
    67→            let prefix = format!("{}/", page_id);
    68→            if let Some(bare) = name.strip_prefix(&prefix) {
    69→                return bare.to_string();
    70→            }
    71→        }
    72→        name.to_string()
    73→    }
    74→
    75→    /// Register a Lua runtime's command channel for change notifications
    76→    ///
    77→    /// **Context**: Called after `launch_test_slint_app()` returns the `lua_tx`.
    78→    /// All subsequent mutations will send `LoroChanged` to this channel.
    79→    pub fn register_subscriber(&mut self, tx: mpsc::Sender<LuaCommand>) {
    80→        self.subscribers.push(tx);
    81→    }
    82→
    83→    /// Clear all subscribers (stale channels from previous reload cycle)
    84→    pub fn clear_subscribers(&mut self) {
    85→        self.subscribers.clear();
    86→    }
    87→
    88→    /// Notify all subscribers that a layer changed
    89→    ///
    90→    /// **Sends**: `LuaCommand::LoroChanged` with `full_data` (no delta/ops).
    91→    /// This triggers the Replace fallback path in the binding system,
    92→    /// which works for both list and map layers.
    93→    fn notify_change(&self, layer_name: &str) {
    94→        if self.subscribers.is_empty() {
    95→            return;
    96→        }
    97→        let full_data = match self.get_layer_data(layer_name) {
    98→            Some(data) => data,
    99→            None => return,
   100→        };
   101→        for tx in &self.subscribers {
   102→            let _ = tx.try_send(LuaCommand::LoroChanged {
   103→                layer_name: layer_name.to_string(),
   104→                ops: None,
   105→                delta: None,
   106→                full_data: Some(full_data.clone()),
   107→            });
   108→        }
   109→    }
   110→}
