   357→            Some(MockLayer::Map(map)) => Ok(map.keys().cloned().collect()),
   358→            Some(MockLayer::List(_)) => {
   359→                Err(format!("Layer '{}' is a list, not a map", name))
   360→            }
   361→            None => Err(format!("Layer '{}' does not exist", name)),
   362→        }
   363→    }
   364→
   365→    fn list_layers(&self, pattern: &str) -> Result<Vec<String>, String> {
   366→        let state = self.state.lock().unwrap();
   367→        let names: Vec<String> = state
   368→            .layers
   369→            .keys()
   370→            .filter(|name| matches_glob(name, pattern))
   371→            .cloned()
   372→            .collect();
   373→        Ok(names)
   374→    }
