   376→    fn get_layer_json(&self, layer_name: &str) -> Result<Option<JsonValue>, String> {
   377→        let state = self.state.lock().unwrap();
   378→        let name = state.normalize(layer_name);
   379→        Ok(state.get_layer_data(&name))
   380→    }
   381→
   382→    fn get_layer_data(&self, layer_name: &str) -> Result<JsonValue, String> {
   383→        let state = self.state.lock().unwrap();
   384→        let name = state.normalize(layer_name);
   385→        state
   386→            .get_layer_data(&name)
   387→            .ok_or_else(|| format!("Layer '{}' does not exist", name))
   388→    }
