   407→/// Simple glob matching for layer names
   408→///
   409→/// Supports `*` as wildcard for any characters within a segment.
   410→fn matches_glob(name: &str, pattern: &str) -> bool {
   411→    if !pattern.contains('*') {
   412→        return name == pattern;
   413→    }
   414→
   415→    // Split on '*' and match greedily
   416→    let parts: Vec<&str> = pattern.split('*').collect();
   417→    if parts.is_empty() {
   418→        return true;
   419→    }
   420→
   421→    let mut pos = 0;
   422→    for (i, part) in parts.iter().enumerate() {
   423→        if part.is_empty() {
   424→            continue;
   425→        }
   426→        match name[pos..].find(part) {
   427→            Some(idx) => {
   428→                // First part must match at start
   429→                if i == 0 && idx != 0 {
   430→                    return false;
   431→                }
   432→                pos += idx + part.len();
   433→            }
   434→            None => return false,
   435→        }
   436→    }
   437→
   438→    // Last part must match at end (unless pattern ends with *)
   439→    if !pattern.ends_with('*') {
   440→        name.ends_with(parts.last().unwrap_or(&""))
   441→    } else {
   442→        true
   443→    }
   444→}
