   281→        assert!(!validate_creator_namespace(
   282→            "page1/channels/did:key:alice/general/messages",
   283→            "page1",
   284→            "did:key:bob",
   285→        ));
   286→        // Bare path (no page prefix)
   287→        assert!(validate_creator_namespace(
   288→            "channels/did:key:alice/general/messages",
   289→            "other_page",
   290→            "did:key:alice",
   291→        ));
   292→        // Too short
   293→        assert!(!validate_creator_namespace(
   294→            "page1/channels",
   295→            "page1",
   296→            "did:key:alice",
   297→        ));
   298→    }
