   538→/// Collect connected peers with their roles from subscriber info
   539→///
   540→/// **Context**: Node needs (did, role) pairs for prepare_layer_permits
   541→fn collect_connected_peers_with_roles(state: &ScribeState) -> Vec<(String, String)> {
   542→    let mut peers = Vec::new();
   543→
   544→    if let Ok(subs) = state.subscribers.read() {
   545→        for ((did, _device_id), info) in subs.iter() {
   546→            let role = info.permit.relationship().unwrap_or("peer").to_string();
   547→            // Avoid duplicates (same DID, different devices)
   548→            if !peers.iter().any(|(d, _): &(String, String)| d == did) {
   549→                peers.push((did.clone(), role));
   550→            }
   551→        }
   552→    }
   553→
   554→    peers
   555→}
