   593→    async fn on_distribute_layer_permits(
   594→        &self,
   595→        page_id: &str,
   596→        layer_name: &str,
   597→        permits: &[(String, String)],
   598→        state: &mut CoordinatorState<C>,
   599→    ) {
   600→        info!(
   601→            "Distributing {} layer permits for page={} layer={}",
   602→            permits.len(), page_id, layer_name
   603→        );
   604→
   605→        for (recipient_did, permit_token) in permits {
   606→            // Store layer permit in butler
   607→            if let Err(e) = state.butler.permits().store_layer_permit(
   608→                page_id,
   609→                recipient_did,
   610→                layer_name,
   611→                permit_token,
   612→            ) {
   613→                warn!(
   614→                    recipient = %recipient_did,
   615→                    error = %e,
   616→                    "Failed to store layer permit"
   617→                );
   618→                continue;
   619→            }
   620→
   621→            // Find PeerActor for this recipient and send
   622→            if let Some(actor) = state.get_peer_actor_for_did(recipient_did) {
   623→                if let Err(e) = actor.cast(PeerMessage::SendLayerPermit {
   624→                    page_id: page_id.to_string(),
   625→                    layer_name: layer_name.to_string(),
   626→                    permit: permit_token.clone(),
   627→                }) {
   628→                    warn!(
   629→                        recipient = %recipient_did,
   630→                        error = %e,
   631→                        "Failed to send LayerPermit to PeerActor"
   632→                    );
   633→                } else {
   634→                    info!(recipient = %recipient_did, "Sent LayerPermit to PeerActor");
   635→                }
   636→            } else {
   637→                // Peer not connected — permit stored, will be sent on reconnect
   638→                debug!(
   639→                    recipient = %recipient_did,
   640→                    "Peer not connected, layer permit stored for reconnect"
   641→                );
   642→            }
   643→        }
   644→    }
