   701→    /// Handle page opened - refresh subscriptions for all authenticated peers
   702→    ///
   703→    /// **Context**: App opened a page, subscriptions may not be established yet
   704→    /// **We do**: Send RefreshSubscriptions to all authenticated PeerActors
   705→    /// **Design**: Ensures subscription after page open (race condition fix)
   706→    #[instrument(skip_all, fields(page_id = %page_id))]
   707→    async fn on_page_opened(&self, page_id: &str, state: &mut CoordinatorState<C>) {
   708→        let peer_count = state.authenticated_peers().count();
   709→        if peer_count == 0 {
   710→            debug!(page_id = %page_id, "No authenticated peers to refresh subscriptions for");
   711→            return;
   712→        }
   713→
   714→        info!(page_id = %page_id, peer_count = peer_count, "Page opened, refreshing subscriptions for authenticated peers");
   715→
   716→        for (node_id, entry) in state.authenticated_peers() {
   717→            if let Err(e) = entry.actor.cast(PeerMessage::RefreshSubscriptions) {
   718→                warn!(node_id = %node_id, error = %e, "Failed to send RefreshSubscriptions");
   719→            }
   720→        }
   721→    }
   722→}
