   212→            Ok(permit) => permit.parsed().issuer().to_string(),
   213→            Err(e) => {
   214→                error!("Cannot issue space consent: failed to parse permit: {}", e);
   215→                return;
   216→            }
   217→        };
   218→
   219→        let signing_key = match state.butler.signing_key().await {
   220→            Ok(key) => key,
   221→            Err(e) => {
   222→                error!("Failed to get signing key for space consent: {}", e);
   223→                return;
   224→            }
   225→        };
   226→
   227→        let (space_consent_permit, _cid) = match gurkha::issue_sync_space_consent(
   228→            &signing_key,
   229→            &node_pubkey,
   230→            space_id,
   231→            node_space_permit,
   232→            space_template,
   233→        ).await {
   234→            Ok(result) => result,
   235→            Err(e) => {
   236→                error!("Failed to issue space consent permit: {}", e);
   237→                return;
   238→            }
   239→        };
   240→
   241→        info!("Issued space consent permit for space {}", space_id);
   242→
   243→        // Send SyncConsentGrant with only space consent (no page consents yet)
   244→        let request_id = uuid::Uuid::new_v4().to_string();
   245→        let msg = Message::SyncConsentGrant(SyncConsentGrantMsg {
   246→            request_id,
   247→            space_id: space_id.to_string(),
   248→            space_consent_permit,
   249→            page_consent_permits: vec![],
   250→        });
   251→
   252→        self.send_message(&msg, state).await;
   253→        info!("Sent space consent for space {} to node", space_id);
   254→    }
   255→
   256→    /// Issue page consent permit (when each page is received)
   257→    ///
   258→    /// **Context**: Viewer received a page, issues consent for that page
   259→    /// **We do**: Issue page consent permit via gurkha, send SyncConsentGrant
   260→    #[instrument(skip(self, state, node_page_permit, page_template), fields(page_id = %page_id))]
   261→    pub(in crate::peer_actor) async fn issue_page_consent(
   262→        &self,
   263→        page_id: &str,
   264→        node_page_permit: &str,
   265→        page_template: &str,
   266→        state: &mut PeerActorState<C>,
   267→    ) {
   268→        if require_user_mode(state.mode, "issue_page_consent").is_some() {
   269→            return;
   270→        }
   271→
   272→        // Extract node's DID from the permit (iss field)
   273→        // This works for both handshake and SpaceRequest flows
   274→        let node_pubkey = match parse_permit(node_page_permit) {
   275→            Ok(permit) => permit.parsed().issuer().to_string(),
   276→            Err(e) => {
   277→                error!("Cannot issue page consent: failed to parse permit: {}", e);
   278→                return;
   279→            }
   280→        };
   281→
   282→        let signing_key = match state.butler.signing_key().await {
