     1→//! Ephemeral event handling for Scribe actor
     2→//!
     3→//! - Remote ephemeral routing (structured ephemerals)
     4→//! - Local app event emission (PeerSubscribed, PeerUnsubscribed, Ephemeral, StructuredEphemeral)
     5→//! - Peer broadcast via ephemeral channels (cursors, typing, etc.)
     6→
     7→use tracing::{debug, info, instrument, warn};
     8→
     9→use crate::message::{EphemeralOutbound, PageUpdate};
    10→use crate::state::ScribeState;
    11→
    12→// Remote Ephemeral Routing
    13→
    14→/// Route incoming remote ephemeral to appropriate handler
    15→///
    16→/// Returns true if the message was handled, false if it should be emitted as raw ephemeral
    17→#[instrument(skip(state, payload), fields(page_id = %state.page_id))]
    18→pub fn route_remote_ephemeral(state: &mut ScribeState, from_did: &str, payload: &[u8]) -> bool {
    19→    let Ok(json) = serde_json::from_slice::<serde_json::Value>(payload) else {
    20→        debug!(page_id = %state.page_id, "route_remote_ephemeral: failed to parse JSON");
    21→        return false;
    22→    };
    23→
    24→    let Some(msg_type) = json.get("type").and_then(|t| t.as_str()) else {
    25→        debug!(page_id = %state.page_id, "route_remote_ephemeral: no 'type' field in JSON");
    26→        return false;
    27→    };
    28→
    29→    debug!(page_id = %state.page_id, msg_type = %msg_type, from_did = %from_did, "route_remote_ephemeral: routing message");
    30→
    31→    match msg_type {
    32→        "structured" => {
    33→            let func = json.get("func").and_then(|f| f.as_str());
    34→            let args = json.get("args");
    35→            // Extract original sender's DID from payload (for relayed messages)
    36→            // Fall back to from_did parameter (the immediate peer) if not present
    37→            let original_sender = json
    38→                .get("from_did")
    39→                .and_then(|d| d.as_str())
    40→                .unwrap_or(from_did);
    41→            if let (Some(func), Some(args)) = (func, args) {
    42→                emit_structured_ephemeral(state, original_sender, func, args);
    43→                debug!(page_id = %state.page_id, original_sender = %original_sender, func = %func, "Remote structured ephemeral");
    44→                return true;
    45→            }
    46→            false
    47→        }
    48→        // Legacy message types
    49→        "peer_joined" | "peer_left" | "peer_count" | "online_peers" => {
    50→            debug!(page_id = %state.page_id, msg_type = %msg_type, "Ignoring legacy ephemeral message type");
    51→            true
    52→        }
    53→        _ => false
    54→    }
    55→}
    56→
    57→// Local App Event Emission
    58→
    59→/// Send a PageUpdate to all local app subscribers
    60→///
    61→/// **Context**: Common helper for all event emission — acquires read lock once,
    62→/// iterates subscribers, sends update. Returns count of successful sends.
    63→#[instrument(skip_all, fields(page_id = %state.page_id))]
    64→pub fn emit_to_page_subscribers(state: &ScribeState, update: PageUpdate) -> usize {
    65→    let Ok(subs) = state.page_update_subscribers.read() else {
    66→        warn!(page_id = %state.page_id, "Cannot emit to page subscribers - failed to acquire lock");
    67→        return 0;
    68→    };
    69→    let mut sent = 0;
    70→    for tx in subs.iter() {
    71→        if tx.try_send(update.clone()).is_ok() {
    72→            sent += 1;
    73→        }
    74→    }
    75→    sent
    76→}
    77→
    78→/// Emit PeerSubscribed to local app subscribers
    79→pub fn emit_peer_subscribed(state: &ScribeState, user_did: &str) {
    80→    let sent = emit_to_page_subscribers(state, PageUpdate::PeerSubscribed {
    81→        did: user_did.to_string(),
    82→        username: None,
    83→    });
    84→    if sent > 0 {
    85→        info!(user_did = %user_did, "Emitted PeerSubscribed to {} subscribers", sent);
    86→    }
    87→}
    88→
    89→/// Emit PeerUnsubscribed to local app subscribers
    90→pub fn emit_peer_unsubscribed(state: &ScribeState, user_did: &str) {
    91→    let sent = emit_to_page_subscribers(state, PageUpdate::PeerUnsubscribed {
    92→        did: user_did.to_string(),
    93→    });
    94→    if sent > 0 {
    95→        info!(user_did = %user_did, "Emitted PeerUnsubscribed to {} subscribers", sent);
    96→    }
    97→}
    98→
    99→/// Emit raw ephemeral to local app subscribers
   100→pub fn emit_raw_ephemeral(state: &ScribeState, user_did: &str, device_id: &str, payload: &[u8]) {
   101→    emit_to_page_subscribers(state, PageUpdate::Ephemeral {
   102→        user_did: user_did.to_string(),
   103→        device_id: device_id.to_string(),
   104→        payload: payload.to_vec(),
   105→    });
   106→}
   107→
   108→/// Emit structured ephemeral to local app subscribers
   109→///
   110→/// **Context**: Called when a structured ephemeral is sent (locally or received from peer)
   111→/// **Note**: Only emits to PageUpdate subscribers, not to PeerActor ephemeral channels
   112→pub fn emit_structured_ephemeral(
   113→    state: &ScribeState,
   114→    from_did: &str,
   115→    func: &str,
   116→    args: &serde_json::Value,
   117→) {
   118→    let sent = emit_to_page_subscribers(state, PageUpdate::StructuredEphemeral {
   119→        from_did: from_did.to_string(),
   120→        func: func.to_string(),
   121→        args: args.clone(),
   122→    });
   123→    debug!(
   124→        page_id = %state.page_id,
   125→        from_did = %from_did,
   126→        func = %func,
   127→        subscribers = sent,
   128→        "emit_structured_ephemeral: sent to app subscribers"
   129→    );
   130→}
   131→
   132→// Peer Broadcast via Ephemeral Channels
   133→
   134→/// Broadcast ephemeral data to all subscribed PeerActors (via their ephemeral channels)
   135→///
   136→/// **Context**: Called for:
   137→/// - SendEphemeral from Lua (local user action) - no exclusion
   138→/// - RemoteEphemeral (relay to other peers) - exclude sender
   139→///
   140→/// **exclude_key**: (user_did, device_id) to skip (the sender for relay)
   141→#[instrument(skip(state, payload), fields(page_id = %state.page_id, payload_len = payload.len()))]
   142→pub fn broadcast_ephemeral_to_subscribers(
   143→    state: &ScribeState,
   144→    payload: &[u8],
   145→    exclude_key: Option<(&str, &str)>,
   146→) {
   147→    if let Ok(subscribers) = state.subscribers.read() {
   148→        let total_subs = subscribers.len();
   149→        let mut sent_count = 0;
   150→        let mut skipped_no_channel = 0;
   151→        let mut skipped_excluded = 0;
   152→
   153→        for ((did, device), info) in subscribers.iter() {
   154→            // Skip sender (for relay - don't echo back)
   155→            if let Some((ex_did, ex_device)) = exclude_key {
   156→                if did == ex_did && device == ex_device {
   157→                    skipped_excluded += 1;
   158→                    continue;
   159→                }
   160→            }
   161→            // Send via ephemeral channel if available
   162→            if let Some(ref tx) = info.ephemeral_tx {
   163→                match tx.try_send(EphemeralOutbound {
   164→                    page_id: state.page_id.clone(),
   165→                    payload: payload.to_vec(),
   166→                }) {
   167→                    Ok(()) => sent_count += 1,
   168→                    Err(e) => {
   169→                        debug!(
   170→                            page_id = %state.page_id,
   171→                            did = %did,
   172→                            error = %e,
   173→                            "Failed to send ephemeral to subscriber"
   174→                        );
   175→                    }
   176→                }
   177→            } else {
   178→                skipped_no_channel += 1;
   179→            }
   180→        }
   181→
   182→        debug!(
   183→            page_id = %state.page_id,
   184→            total_subscribers = total_subs,
   185→            sent = sent_count,
   186→            skipped_no_channel = skipped_no_channel,
   187→            skipped_excluded = skipped_excluded,
   188→            payload_len = payload.len(),
   189→            "Ephemeral broadcast to PeerActors complete"
   190→        );
   191→    } else {
   192→        warn!(page_id = %state.page_id, "Failed to acquire subscribers lock for ephemeral broadcast");
   193→    }
   194→}
