```rust
fn generate_dynamic_path(schema_key: &str, our_did: &str, layer_id: &str) -> String {
    // "channels/{id}/messages" with DID "did:key:alice" and ID "general" →
    // "channels/did:key:alice/general/messages"

    let parts: Vec<&str> = schema_key.split('/').collect();
    let mut result = Vec::new();

    result.push(parts[0].to_string());  // First segment: literal (e.g., "channels")
    result.push(our_did.to_string());   // Insert our DID as second segment

    for part in &parts[1..] {           // Remaining: replace {id}, keep literals
        if *part == "{id}" {
            result.push(layer_id.to_string());
        } else {
            result.push(part.to_string());
        }
    }

    result.join("/")
}
```

