   144→        let table = read_txn.open_table(DYNAMIC_LAYER_META)?;
   145→
   146→        let mut layers = Vec::new();
   147→        for result in table.range(prefix.as_str()..)? {
   148→            let (key, value) = result?;
   149→            let key_str = key.value();
   150→
   151→            if !key_str.starts_with(&prefix) {
