   160→    }
   161→
   162→    /// Get metadata for a specific dynamic layer.
   163→    #[instrument(skip_all)]
   164→    pub fn get_dynamic_layer_meta(
   165→        &self,
   166→        page_id: &str,
   167→        layer_name: &str,
   168→    ) -> Result<Option<Vec<u8>>> {
   169→        let key = format!("{}/{}", page_id, layer_name);
