fn load_layer_participants(&self, page_id: &str, layer_name: &str) -> Result<Vec<String>> {
    match self.store.get_dynamic_layer_meta(page_id, layer_name)? {
        Some(bytes) => {
            let meta: serde_json::Value = serde_json::from_slice(&bytes)?;
            let participants = meta.get("participants")
                .and_then(|v| v.as_array())
                .map(|arr| arr.iter().filter_map(|v| v.as_str().map(String::from)).collect())
                .unwrap_or_default();
            Ok(participants)
        }
        None => Ok(Vec::new()),
    }
}

fn store_layer_participants(&self, page_id: &str, layer_name: &str, participants: &[String]) -> Result<()> {
    // Load existing metadata, update participants, store back
    let meta = match self.store.get_dynamic_layer_meta(page_id, layer_name)? {
        Some(bytes) => {
            let mut meta: serde_json::Value = serde_json::from_slice(&bytes)?;
            meta["participants"] = serde_json::json!(participants);
            meta
        }
        None => {
            serde_json::json!({ "participants": participants })
        }
    };
    let meta_bytes = serde_json::to_vec(&meta)?;
    self.store.store_dynamic_layer_meta(page_id, layer_name, &meta_bytes)?;
    Ok(())
}
```

The existing `RedbStore` methods (`store_dynamic_layer_meta`, `get_dynamic_layer_meta`, `list_dynamic_layers`) are already sufficient and need no changes.

