   243→#[cfg(test)]
   244→mod tests {
   245→    use super::*;
   246→
   247→    fn test_store() -> RedbStore {
   248→        let temp_path = std::env::temp_dir()
   249→            .join(format!("butler_dyn_layer_test_{}.redb", uuid::Uuid::new_v4()));
   250→        RedbStore::open(&temp_path).unwrap()
   251→    }
   252→
   253→    // ── C1: Layer permit CRUD ─────────────────────────────────────────
   254→
   255→    #[test]
   256→    fn test_store_and_retrieve_layer_permits() {
   257→        let store = test_store();
   258→        store.store_layer_permit("page1", "did:key:user", "page1/channels/foo", "token1").unwrap();
   259→        store.store_layer_permit("page1", "did:key:user", "page1/dms/bar", "token2").unwrap();
   260→
   261→        let permits = store.get_layer_permits("page1", "did:key:user").unwrap();
   262→        assert_eq!(permits.len(), 2);
   263→
   264→        // Sorted by key (lexicographic on layer_name)
   265→        let names: Vec<&str> = permits.iter().map(|(n, _)| n.as_str()).collect();
   266→        assert!(names.contains(&"page1/channels/foo"));
   267→        assert!(names.contains(&"page1/dms/bar"));
   268→    }
   269→
   270→    #[test]
   271→    fn test_layer_permits_isolated_per_user() {
   272→        let store = test_store();
   273→        store.store_layer_permit("page1", "did:key:alice", "page1/ch/foo", "token-a").unwrap();
   274→        store.store_layer_permit("page1", "did:key:bob", "page1/ch/foo", "token-b").unwrap();
   275→
   276→        let alice = store.get_layer_permits("page1", "did:key:alice").unwrap();
   277→        assert_eq!(alice.len(), 1);
   278→        assert_eq!(alice[0].1, "token-a");
   279→
   280→        let bob = store.get_layer_permits("page1", "did:key:bob").unwrap();
   281→        assert_eq!(bob.len(), 1);
   282→        assert_eq!(bob[0].1, "token-b");
   283→    }
   284→
   285→    // ── C2: Layer permit removal ──────────────────────────────────────
   286→
   287→    #[test]
   288→    fn test_remove_layer_permit() {
   289→        let store = test_store();
   290→        store.store_layer_permit("page1", "did:key:user", "page1/channels/foo", "token").unwrap();
   291→        assert!(store.has_layer_permit("page1", "did:key:user", "page1/channels/foo").unwrap());
   292→
   293→        let removed = store.remove_layer_permit("page1", "did:key:user", "page1/channels/foo").unwrap();
   294→        assert!(removed);
   295→
   296→        let permits = store.get_layer_permits("page1", "did:key:user").unwrap();
   297→        assert!(permits.is_empty());
   298→
   299→        // Removing non-existent returns false
   300→        let removed2 = store.remove_layer_permit("page1", "did:key:user", "page1/channels/foo").unwrap();
   301→        assert!(!removed2);
   302→    }
   303→
   304→    // ── C3: Dynamic layer metadata ────────────────────────────────────
   305→
   306→    #[test]
   307→    fn test_dynamic_layer_metadata_storage() {
   308→        let store = test_store();
   309→        let meta = serde_json::json!({
   310→            "schema_pattern": "channels/{id}/messages",
   311→            "creator_did": "did:key:alice",
   312→            "grant_type": "role",
   313→        });
   314→        let meta_bytes = serde_json::to_vec(&meta).unwrap();
   315→
   316→        store.store_dynamic_layer_meta(
   317→            "page1",
   318→            "page1/channels/did:key:alice/general/messages",
   319→            &meta_bytes,
   320→        ).unwrap();
   321→
   322→        let layers = store.list_dynamic_layers("page1").unwrap();
   323→        assert_eq!(layers.len(), 1);
   324→        assert_eq!(layers[0].0, "page1/channels/did:key:alice/general/messages");
   325→
   326→        let retrieved: serde_json::Value = serde_json::from_slice(&layers[0].1).unwrap();
   327→        assert_eq!(retrieved["creator_did"], "did:key:alice");
   328→        assert_eq!(retrieved["grant_type"], "role");
   329→    }
   330→
   331→    #[test]
   332→    fn test_get_dynamic_layer_meta() {
   333→        let store = test_store();
   334→        let meta = b"{\"schema\":\"orders/{id}\"}";
   335→        store.store_dynamic_layer_meta("page1", "page1/orders/did:key:a/uuid1", meta).unwrap();
   336→
   337→        let result = store.get_dynamic_layer_meta("page1", "page1/orders/did:key:a/uuid1").unwrap();
   338→        assert!(result.is_some());
   339→
   340→        let missing = store.get_dynamic_layer_meta("page1", "page1/nonexistent").unwrap();
   341→        assert!(missing.is_none());
   342→    }
   343→
   344→    // ── C4: Viewer layer consent ──────────────────────────────────────
   345→
   346→    #[test]
   347→    fn test_viewer_layer_consent_storage() {
   348→        let store = test_store();
   349→        store.store_viewer_layer_consent(
   350→            "did:key:viewer", "page1", "page1/channels/foo", "consent-token-1",
   351→        ).unwrap();
   352→
   353→        assert!(store.has_viewer_layer_consent("did:key:viewer", "page1", "page1/channels/foo").unwrap());
   354→        assert!(!store.has_viewer_layer_consent("did:key:viewer", "page1", "page1/channels/bar").unwrap());
   355→        assert!(!store.has_viewer_layer_consent("did:key:other", "page1", "page1/channels/foo").unwrap());
   356→
   357→        let token = store.get_viewer_layer_consent("did:key:viewer", "page1", "page1/channels/foo").unwrap();
   358→        assert_eq!(token, Some("consent-token-1".to_string()));
   359→
   360→        let missing = store.get_viewer_layer_consent("did:key:viewer", "page1", "page1/channels/bar").unwrap();
   361→        assert!(missing.is_none());
