//! Dynamic Layer Storage Operations
//!
//! Three tables for the two-tier permit model:
//! - **Layer permits**: per-peer per-dynamic-layer UCAN tokens
//! - **Dynamic layer metadata**: tracks which layers are dynamic (for reconnect)
//! - **Viewer layer consents**: per-viewer per-layer consent tokens

use redb::{ReadableTable, ReadableDatabase};
use crate::error::Result;
use tracing::instrument;
use super::{
    RedbStore, LAYER_PERMITS, DYNAMIC_LAYER_META, VIEWER_LAYER_CONSENTS,
};

impl RedbStore {
    // ── Layer Permit Operations ──────────────────────────────────────────
    // Key: {page_id}/{user_did}/{layer_name} → permit token string
    // Multiple permits per peer per page (one per dynamic layer)

    /// Store a layer permit for a peer (additive).
    ///
    /// **Context**: Node detected new dynamic layer, issued permit for peer.
    #[instrument(skip_all)]
    pub fn store_layer_permit(
        &self,
        page_id: &str,
        user_did: &str,
        layer_name: &str,
        permit_token: &str,
    ) -> Result<()> {
        let key = format!("{}/{}/{}", page_id, user_did, layer_name);
        let write_txn = self.db.begin_write()?;
        {
            let mut table = write_txn.open_table(LAYER_PERMITS)?;
            table.insert(key.as_str(), permit_token)?;
        }
        write_txn.commit()?;
        Ok(())
    }

    /// Load all layer permits for a peer on a page.
    ///
    /// **Context**: Used during reconnect to determine which dynamic layers peer has access to.
    /// **Returns**: Vec of (layer_name, permit_token) tuples.
    #[instrument(skip_all)]
    pub fn get_layer_permits(
        &self,
        page_id: &str,
        user_did: &str,
    ) -> Result<Vec<(String, String)>> {
        let prefix = format!("{}/{}/", page_id, user_did);
        let read_txn = self.db.begin_read()?;
        let table = read_txn.open_table(LAYER_PERMITS)?;

        let mut permits = Vec::new();
        for result in table.range(prefix.as_str()..)? {
            let (key, value) = result?;
            let key_str = key.value();

            if !key_str.starts_with(&prefix) {
                break;
            }

            if let Some(layer_name) = key_str.strip_prefix(&prefix) {
                permits.push((layer_name.to_string(), value.value().to_string()));
            }
        }
        Ok(permits)
    }

    /// Remove a layer permit for a peer.
    ///
    /// **Context**: Called during revocation or cleanup.
    #[instrument(skip_all)]
    pub fn remove_layer_permit(
        &self,
        page_id: &str,
        user_did: &str,
        layer_name: &str,
    ) -> Result<bool> {
        let key = format!("{}/{}/{}", page_id, user_did, layer_name);
        let write_txn = self.db.begin_write()?;
        let removed = {
            let mut table = write_txn.open_table(LAYER_PERMITS)?;
            let result = table.remove(key.as_str())?.is_some();
            result
        };
        write_txn.commit()?;
        Ok(removed)
    }

    /// Check if a peer has a layer permit for a specific dynamic layer.
    #[instrument(skip_all)]
    pub fn has_layer_permit(
        &self,
        page_id: &str,
        user_did: &str,
        layer_name: &str,
    ) -> Result<bool> {
        let key = format!("{}/{}/{}", page_id, user_did, layer_name);
        let read_txn = self.db.begin_read()?;
        let table = read_txn.open_table(LAYER_PERMITS)?;
        let result = table.get(key.as_str())?.is_some();
        Ok(result)
    }

    // ── Dynamic Layer Metadata Operations ────────────────────────────────
    // Key: {page_id}/{layer_name} → meta JSON bytes
    // Tracks which layers are dynamic (schema, creator, grant type)

    /// Record that a layer is dynamic.
    ///
    /// **Context**: Node detected new dynamic layer from peer sync.
    /// Stores metadata for reconnect enumeration and permit recomputation.
    #[instrument(skip_all)]
    pub fn store_dynamic_layer_meta(
        &self,
        page_id: &str,
        layer_name: &str,
        meta_json: &[u8],
    ) -> Result<()> {
        let key = format!("{}/{}", page_id, layer_name);
        let write_txn = self.db.begin_write()?;
        {
            let mut table = write_txn.open_table(DYNAMIC_LAYER_META)?;
            table.insert(key.as_str(), meta_json)?;
        }
        write_txn.commit()?;
        Ok(())
    }

    /// List all dynamic layers for a page.
    ///
    /// **Context**: Used during peer reconnect to enumerate dynamic layers
    /// and compute which permits are missing.
    /// **Returns**: Vec of (layer_name, meta_json_bytes) tuples.
    #[instrument(skip_all)]
    pub fn list_dynamic_layers(
        &self,
        page_id: &str,
    ) -> Result<Vec<(String, Vec<u8>)>> {
        let prefix = format!("{}/", page_id);
        let read_txn = self.db.begin_read()?;
        let table = read_txn.open_table(DYNAMIC_LAYER_META)?;

        let mut layers = Vec::new();
        for result in table.range(prefix.as_str()..)? {
            let (key, value) = result?;
            let key_str = key.value();

            if !key_str.starts_with(&prefix) {
                break;
            }

            if let Some(layer_name) = key_str.strip_prefix(&prefix) {
                layers.push((layer_name.to_string(), value.value().to_vec()));
            }
        }
        Ok(layers)
    }

    /// Get metadata for a specific dynamic layer.
    #[instrument(skip_all)]
    pub fn get_dynamic_layer_meta(
        &self,
        page_id: &str,
        layer_name: &str,
    ) -> Result<Option<Vec<u8>>> {
        let key = format!("{}/{}", page_id, layer_name);
        let read_txn = self.db.begin_read()?;
        let table = read_txn.open_table(DYNAMIC_LAYER_META)?;

        match table.get(key.as_str())? {
            Some(guard) => Ok(Some(guard.value().to_vec())),
            None => Ok(None),
        }
    }

    // ── Viewer Layer Consent Operations ──────────────────────────────────
    // Key: {viewer_did}/{page_id}/{layer_name} → consent token string
    // Tracks per-layer consent from viewer (dynamic layers need separate consent)

    /// Store viewer's consent for a dynamic layer.
    ///
    /// **Context**: Node receives LayerConsentGrant from viewer.
    /// Required before node can sync that dynamic layer to the viewer.
    #[instrument(skip_all)]
    pub fn store_viewer_layer_consent(
        &self,
        viewer_did: &str,
        page_id: &str,
        layer_name: &str,
        consent_token: &str,
    ) -> Result<()> {
        let key = format!("{}/{}/{}", viewer_did, page_id, layer_name);
        let write_txn = self.db.begin_write()?;
        {
            let mut table = write_txn.open_table(VIEWER_LAYER_CONSENTS)?;
            table.insert(key.as_str(), consent_token)?;
        }
        write_txn.commit()?;
        Ok(())
    }

    /// Check if viewer has consented to a dynamic layer.
    ///
    /// **Context**: Node checks before syncing a dynamic layer to a peer.
    /// Both layer permit AND consent must be present before sync.
    #[instrument(skip_all)]
    pub fn has_viewer_layer_consent(
        &self,
        viewer_did: &str,
        page_id: &str,
        layer_name: &str,
    ) -> Result<bool> {
        let key = format!("{}/{}/{}", viewer_did, page_id, layer_name);
        let read_txn = self.db.begin_read()?;
        let table = read_txn.open_table(VIEWER_LAYER_CONSENTS)?;
        Ok(table.get(key.as_str())?.is_some())
    }

    /// Get viewer's layer consent token.
    ///
    /// **Context**: Node needs consent token for proof chain during sync.
    #[instrument(skip_all)]
    pub fn get_viewer_layer_consent(
        &self,
        viewer_did: &str,
        page_id: &str,
        layer_name: &str,
    ) -> Result<Option<String>> {
        let key = format!("{}/{}/{}", viewer_did, page_id, layer_name);
        let read_txn = self.db.begin_read()?;
        let table = read_txn.open_table(VIEWER_LAYER_CONSENTS)?;

        match table.get(key.as_str())? {
            Some(guard) => Ok(Some(guard.value().to_string())),
            None => Ok(None),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn test_store() -> RedbStore {
        let temp_path = std::env::temp_dir()
            .join(format!("butler_dyn_layer_test_{}.redb", uuid::Uuid::new_v4()));
        RedbStore::open(&temp_path).unwrap()
    }

    // ── C1: Layer permit CRUD ─────────────────────────────────────────

    #[test]
    fn test_store_and_retrieve_layer_permits() {
        let store = test_store();
        store.store_layer_permit("page1", "did:key:user", "page1/channels/foo", "token1").unwrap();
        store.store_layer_permit("page1", "did:key:user", "page1/dms/bar", "token2").unwrap();

        let permits = store.get_layer_permits("page1", "did:key:user").unwrap();
        assert_eq!(permits.len(), 2);

        // Sorted by key (lexicographic on layer_name)
        let names: Vec<&str> = permits.iter().map(|(n, _)| n.as_str()).collect();
        assert!(names.contains(&"page1/channels/foo"));
        assert!(names.contains(&"page1/dms/bar"));
    }

    #[test]
    fn test_layer_permits_isolated_per_user() {
        let store = test_store();
        store.store_layer_permit("page1", "did:key:alice", "page1/ch/foo", "token-a").unwrap();
        store.store_layer_permit("page1", "did:key:bob", "page1/ch/foo", "token-b").unwrap();

        let alice = store.get_layer_permits("page1", "did:key:alice").unwrap();
        assert_eq!(alice.len(), 1);
        assert_eq!(alice[0].1, "token-a");

        let bob = store.get_layer_permits("page1", "did:key:bob").unwrap();
        assert_eq!(bob.len(), 1);
        assert_eq!(bob[0].1, "token-b");
    }

    // ── C2: Layer permit removal ──────────────────────────────────────

    #[test]
    fn test_remove_layer_permit() {
        let store = test_store();
        store.store_layer_permit("page1", "did:key:user", "page1/channels/foo", "token").unwrap();
        assert!(store.has_layer_permit("page1", "did:key:user", "page1/channels/foo").unwrap());

        let removed = store.remove_layer_permit("page1", "did:key:user", "page1/channels/foo").unwrap();
        assert!(removed);

        let permits = store.get_layer_permits("page1", "did:key:user").unwrap();
        assert!(permits.is_empty());

        // Removing non-existent returns false
        let removed2 = store.remove_layer_permit("page1", "did:key:user", "page1/channels/foo").unwrap();
        assert!(!removed2);
    }

    // ── C3: Dynamic layer metadata ────────────────────────────────────

    #[test]
    fn test_dynamic_layer_metadata_storage() {
        let store = test_store();
        let meta = serde_json::json!({
            "schema_pattern": "channels/{id}/messages",
            "creator_did": "did:key:alice",
            "grant_type": "role",
        });
        let meta_bytes = serde_json::to_vec(&meta).unwrap();

        store.store_dynamic_layer_meta(
            "page1",
            "page1/channels/did:key:alice/general/messages",
            &meta_bytes,
        ).unwrap();

        let layers = store.list_dynamic_layers("page1").unwrap();
        assert_eq!(layers.len(), 1);
        assert_eq!(layers[0].0, "page1/channels/did:key:alice/general/messages");

        let retrieved: serde_json::Value = serde_json::from_slice(&layers[0].1).unwrap();
        assert_eq!(retrieved["creator_did"], "did:key:alice");
        assert_eq!(retrieved["grant_type"], "role");
    }

    #[test]
    fn test_get_dynamic_layer_meta() {
        let store = test_store();
        let meta = b"{\"schema\":\"orders/{id}\"}";
        store.store_dynamic_layer_meta("page1", "page1/orders/did:key:a/uuid1", meta).unwrap();

        let result = store.get_dynamic_layer_meta("page1", "page1/orders/did:key:a/uuid1").unwrap();
        assert!(result.is_some());

        let missing = store.get_dynamic_layer_meta("page1", "page1/nonexistent").unwrap();
        assert!(missing.is_none());
    }

    // ── C4: Viewer layer consent ──────────────────────────────────────

    #[test]
    fn test_viewer_layer_consent_storage() {
        let store = test_store();
        store.store_viewer_layer_consent(
            "did:key:viewer", "page1", "page1/channels/foo", "consent-token-1",
        ).unwrap();

        assert!(store.has_viewer_layer_consent("did:key:viewer", "page1", "page1/channels/foo").unwrap());
        assert!(!store.has_viewer_layer_consent("did:key:viewer", "page1", "page1/channels/bar").unwrap());
        assert!(!store.has_viewer_layer_consent("did:key:other", "page1", "page1/channels/foo").unwrap());

        let token = store.get_viewer_layer_consent("did:key:viewer", "page1", "page1/channels/foo").unwrap();
        assert_eq!(token, Some("consent-token-1".to_string()));

        let missing = store.get_viewer_layer_consent("did:key:viewer", "page1", "page1/channels/bar").unwrap();
        assert!(missing.is_none());
    }
}

//! Storage traits for Scribe actor
//!
//! Butler implements these using RedbStore + encryption.
//! Scribe only knows about the abstract interface.
//!
//! ## Design
//!
//! These traits replace the closure-based storage injection pattern:
//! - `LayerStorage` replaces `SaveLayerFn`
//! - `PeerVectorStorage` replaces `LoadPeerVectorFn` + `SavePeerVectorFn`
//! - `PeerResolver` replaces `ListAuthorizedUsersFn` + `LoadUserPermitFn`
//!
//! Each trait is scoped to a single page (page_id passed at construction time).

use std::collections::HashMap;
use std::sync::Arc;

use crate::Result;

// Layer Storage Trait

/// Layer persistence (scoped to a page)
///
/// **Implemented by**: Butler's RedbStore + encryption layer
/// **Used by**: Scribe flush handler, immediate app layer saves
pub trait LayerStorage: Send + Sync {
    /// Save layer snapshot
    ///
    /// **Context**: Called during periodic flush or immediate save (app layers)
    /// **Implementor**: Should encrypt data before persistence
    fn save_layer(&self, layer_name: &str, data: &[u8]) -> Result<()>;
}

// Peer Vector Storage Trait

/// Peer state vector persistence (scoped to a page)
///
/// **Implemented by**: Butler's RedbStore
/// **Used by**: Scribe subscription handling, unsubscription, flush
///
/// State vectors track what each peer has already received.
/// This enables incremental sync (send only what they're missing).
pub trait PeerVectorStorage: Send + Sync {
    /// Load peer's state vectors for all layers
    ///
    /// **Context**: Called when peer subscribes to restore their last known state
    /// **Returns**: HashMap of layer_name -> state_vector bytes, or None if first connection
    fn load_vectors(&self, user_did: &str, device_id: &str)
        -> Result<Option<HashMap<String, Vec<u8>>>>;

    /// Save peer's state vectors for all layers
    ///
    /// **Context**: Called during flush and on unsubscribe
    /// **Note**: Vectors are stored as-is (Loro's binary format)
    fn save_vectors(
        &self,
        user_did: &str,
        device_id: &str,
        vectors: &HashMap<String, Vec<u8>>,
    ) -> Result<()>;
}

// Peer Resolver Trait (Node Mode Only)

/// Peer authorization (node mode only)
///
/// **Implemented by**: Butler's permit store
/// **Used by**: Scribe for node-mode peer lookup and validation
///
/// Only used when Scribe runs on a node (is_node=true).
/// Allows looking up authorized users and their permits.
pub trait PeerResolver: Send + Sync {
    /// List all authorized user_dids for this page
    ///
    /// **Context**: Node mode sync - finding peers to broadcast to
    /// **Returns**: List of DIDs that have permits for this page
    fn list_authorized_users(&self) -> Vec<String>;

    /// Load a user's permit for this page
    ///
    /// **Context**: Node mode - getting permit for validation/role extraction
    /// **Returns**: Permit token string if user has access, None otherwise
    fn load_user_permit(&self, user_did: &str) -> Option<String>;
}

// Permit Issuer Trait (Node Mode Only)

/// Layer permit issuance (node mode only, scoped to a page)
///
/// **Implemented by**: Butler using signing key + gurkha
/// **Used by**: Scribe layer_unit for issuing layer permits on dynamic layer detection
///
/// Scribe must never hold signing keys. This trait abstracts permit creation
/// so Scribe can request permits without accessing crypto directly.
pub trait PermitIssuer: Send + Sync {
    /// Issue a layer permit for a single dynamic layer
    ///
    /// **Context**: Node detected new dynamic layer, needs to issue permits
    /// **Returns**: (permit_token, cid) — ready to store and send
    fn issue_layer_permit(
        &self,
        audience: &str,
        layer_name: &str,
        config: gurkha::LayerConfig,
    ) -> Result<(String, String)>;
}

// Type Aliases for Convenience

/// Reference-counted layer storage
pub type LayerStorageRef = Arc<dyn LayerStorage>;

/// Reference-counted peer vector storage
pub type PeerVectorStorageRef = Arc<dyn PeerVectorStorage>;

/// Reference-counted peer resolver
pub type PeerResolverRef = Arc<dyn PeerResolver>;

/// Reference-counted permit issuer
pub type PermitIssuerRef = Arc<dyn PermitIssuer>;

// Null Implementations (for testing)

/// Null layer storage that discards all saves
///
/// Useful for testing when persistence isn't needed
pub struct NullLayerStorage;

impl LayerStorage for NullLayerStorage {
    fn save_layer(&self, _layer_name: &str, _data: &[u8]) -> Result<()> {
        Ok(())
    }
}

/// Null peer vector storage that stores nothing
///
/// Useful for testing when peer tracking isn't needed
pub struct NullPeerVectorStorage;

impl PeerVectorStorage for NullPeerVectorStorage {
    fn load_vectors(
        &self,
        _user_did: &str,
        _device_id: &str,
    ) -> Result<Option<HashMap<String, Vec<u8>>>> {
        Ok(None)
    }

    fn save_vectors(
        &self,
        _user_did: &str,
        _device_id: &str,
        _vectors: &HashMap<String, Vec<u8>>,
    ) -> Result<()> {
        Ok(())
    }
}

/// Null peer resolver that has no authorized users
///
/// Useful for testing non-node mode
pub struct NullPeerResolver;

impl PeerResolver for NullPeerResolver {
    fn list_authorized_users(&self) -> Vec<String> {
        Vec::new()
    }

    fn load_user_permit(&self, _user_did: &str) -> Option<String> {
        None
    }
}

/// Null permit issuer that returns test tokens
///
/// Useful for testing when permit issuance isn't needed
pub struct NullPermitIssuer;

impl PermitIssuer for NullPermitIssuer {
    fn issue_layer_permit(
        &self,
        _audience: &str,
        _layer_name: &str,
        _config: gurkha::LayerConfig,
    ) -> Result<(String, String)> {
        Ok(("test-token".into(), "test-cid".into()))
    }
}

//! Scribe message types
//!
//! Contains both the actor messages (ScribeMessage) and shared types
//! (BroadcastPayload, PageUpdate, etc.)

use std::collections::HashMap;
use std::path::PathBuf;

use ractor::RpcReplyPort;
use tokio::sync::mpsc;
use serde::{Serialize, Deserialize};

use domains::{QuerySpec, QueryDelta, QueryResult, JsonOp};
use crate::Result;

/// Payload sent to PeerActor for broadcast (3-step sync protocol)
///
/// **Context**: Scribe sends this to PeerActor, who then sends SyncOffer to peer
/// **state_vector**: Our state vector after this update (for 3-step protocol)
/// **layer_type**: Protocol routing hint (App=snapshot, Data=incremental, Static=blob)
#[derive(Debug, Clone)]
pub struct BroadcastPayload {
    pub page_id: String,
    pub layer_name: String,
    pub update: Vec<u8>,
    /// Our state vector for this layer (for SyncOffer message)
    pub state_vector: Vec<u8>,
    /// Layer type for protocol routing
    pub layer_type: domains::LayerType,
}

/// Ephemeral broadcast payload (generic)
///
/// **Context**: Scribe sends this to Butler/Courier for datagram broadcast
/// **Transport**: Unreliable QUIC datagram (fire-and-forget, lowest latency)
/// **Design**: Generic payload - app defines format; protocol routes by page_id
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct EphemeralBroadcast {
    /// Page ID for routing
    pub page_id: String,
    /// Opaque payload - app defines format (JSON with type/x/y, etc.)
    pub payload: Vec<u8>,
}

/// Outbound ephemeral data (Scribe → PeerActor via channel)
///
/// **Context**: Same pattern as BroadcastPayload for CRDT data
/// **Flow**: Scribe broadcasts ephemeral to all subscriber channels,
///           PeerActor listener receives and sends datagram to peer
#[derive(Debug, Clone)]
pub struct EphemeralOutbound {
    /// Page ID for routing (used in datagram)
    pub page_id: String,
    /// Opaque payload - app defines format (JSON with type/x/y, etc.)
    pub payload: Vec<u8>,
}

/// Delta operations for different Loro container types
///
/// **Context**: Represents incremental changes to CRDT containers
/// **Usage**: Lua apps can apply deltas for efficient UI updates (preserve scroll, animations)
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type")]
pub enum LoroDelta {
    /// List delta: sequence of Retain/Insert/Delete operations
    List { ops: Vec<ListOp> },

    /// Map delta: updated keys
    Map { updated: HashMap<String, Option<serde_json::Value>> },

    /// Text delta (for future rich text support)
    Text { ops: Vec<TextOp> },
}

/// List delta operations (applied sequentially)
///
/// **Context**: Represents changes to a Loro list container
/// **Example**: [Retain(3), Insert([msg4]), Delete(1)] means "skip 3 items, insert msg4, delete 1 item"
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "op")]
pub enum ListOp {
    /// Keep N items unchanged (advance cursor)
    Retain { count: usize },

    /// Insert values at current position
    Insert { values: Vec<serde_json::Value> },

    /// Delete N items at current position
    Delete { count: usize },
}

/// Text delta operations (for rich text editing)
///
/// **Context**: Represents changes to a Loro text container
/// **Note**: Deferred for now - will implement when we need rich text editing
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "op")]
pub enum TextOp {
    /// Keep N characters unchanged
    Retain { count: usize },

    /// Insert text at current position
    Insert { text: String },

    /// Delete N characters at current position
    Delete { count: usize },
}

// Unified Page Update Channel (Replaces PageEvent + EphemeralEvent + QueryDelta)

/// Unified update enum for all page events
///
/// **Context**: Single channel replaces 3 separate broadcast types
/// **Benefits**: 3 listener tasks → 1, unified fan-out logic
/// **Consumers**: UI/Lua callbacks, Broadcast to peers, Derivation engine
#[derive(Debug, Clone)]
pub enum PageUpdate {
    /// Layer data changed (local edit or remote sync)
    LayerChanged {
        layer: String,
        from_peer: Option<(String, String)>,  // (did, device_id)
        /// Structured operations extracted from the update (same format as validation)
        /// Enables surgical UI updates - Lua can process individual ops
        ops: Option<Vec<JsonOp>>,
        delta: Option<LoroDelta>,
        state_vector: Vec<u8>,
        /// Full layer state as JSON — None when delta is available (avoids O(N) serialization)
        /// Some for initial load, wildcard bindings, or fallback scenarios
        full_data: Option<serde_json::Value>,
        /// True if this is a newly created layer (first time seeing it)
        created: bool,
    },

    /// Ephemeral data from remote peer (cursor, typing, etc.)
    Ephemeral {
        user_did: String,
        device_id: String,
        payload: Vec<u8>,
    },

    /// Query result changed
    QueryUpdated {
        query_id: String,
        delta: QueryDelta,
    },

    /// Peer subscribed to this page
    PeerSubscribed {
        did: String,
        /// Username if presence.share_username is true in their permit
        username: Option<String>,
    },

    /// Peer unsubscribed from this page
    PeerUnsubscribed {
        did: String,
    },

    /// Structured ephemeral received (permission-validated)
    ///
    /// **Context**: Ephemeral with func name, validated against permit
    StructuredEphemeral {
        from_did: String,
        func: String,
        args: serde_json::Value,
    },
}

/// Type alias for unified page update channel
pub type PageUpdateTx = mpsc::Sender<PageUpdate>;

/// Events emitted for sync coordination (consumed by Coordinator)
///
/// **Context**: Scribe emits these when it needs to sync with a user.
/// NOTE: Scribe only knows user_did. Coordinator handles everything else:
/// - Device resolution
/// - Connection establishment
/// - Subscription (PeerActor discovers active Scribes on connect)
#[derive(Debug, Clone)]
pub enum SyncEvent {
    /// Ensure this user is synced (connected + subscribed to active Scribes)
    EnsureSync { user_did: String },

    /// Node detected a new dynamic layer — permits already created by layer_unit
    ///
    /// **Context**: Scribe detected a dynamic layer (via schema match) and used
    /// PermitIssuer to create ready-to-send permits. Coordinator just distributes.
    NewDynamicLayer {
        page_id: String,
        layer_name: String,
        /// Ready-to-send permits: (recipient_did, layer_permit_token)
        permits: Vec<(String, String)>,
    },
}

// ScribeMessage - Actor Messages for Scribe

/// Messages received by Scribe actor
#[derive(Debug)]
pub enum ScribeMessage {
    /// Peer subscription - PeerActor subscribes to receive layer updates
    ///
    /// **Context**: PeerActor connects for a page and wants sync updates
    /// **We do**: Parse permit, extract layer permissions + sync policies, store subscriber
    Subscribe {
        user_did: String,
        device_id: String,
        /// Callback to send CRDT broadcasts to this peer
        broadcast_tx: mpsc::Sender<BroadcastPayload>,
        /// Callback to send ephemeral broadcasts to this peer (cursor, typing)
        /// PeerActor creates this channel, spawns listener that sends datagrams
        ephemeral_tx: Option<mpsc::Sender<EphemeralOutbound>>,
        /// Raw permit string - we parse to extract permissions
        permit: String,
    },

    /// Peer unsubscription
    Unsubscribe {
        user_did: String,
        device_id: String,
    },

    /// Apply layer update (from local UI or remote peer)
    ///
    /// **Context**: Local edit or remote sync push
    /// **We do**: Permission check, CRDT merge, broadcast to subscribers
    ApplyUpdate {
        layer_name: String,
        update: Vec<u8>,
        /// None = local edit, Some = remote peer
        from_peer: Option<(String, String)>,
        /// Permit from SyncOffer (for peers not yet subscribed)
        permit: Option<String>,
    },

    /// Apply layer update with result feedback (for SyncAccept control)
    ///
    /// **Context**: Remote sync push that needs success/failure feedback
    /// **We do**: Permission check, CRDT merge, broadcast to subscribers, reply with result
    ApplyUpdateWithResult {
        layer_name: String,
        update: Vec<u8>,
        from_peer: Option<(String, String)>,
        permit: Option<String>,
        reply: tokio::sync::oneshot::Sender<std::result::Result<(), String>>,
    },

    /// Sync request - peer wants updates since their version
    SyncRequest {
        layer_name: String,
        their_vector: Vec<u8>,
        reply: RpcReplyPort<Result<Vec<u8>>>,
    },

    /// Export full snapshot (for initial sync or send_full_snapshot policy)
    ExportSnapshot {
        layer_name: String,
        reply: RpcReplyPort<Result<Vec<u8>>>,
    },

    /// Get our state vector (for incremental sync)
    GetStateVector {
        layer_name: String,
        reply: RpcReplyPort<Result<Vec<u8>>>,
    },

    /// Get updates since a given state vector (for resync after divergence)
    ///
    /// **Context**: SyncAccept showed divergence, sender needs full diff
    /// **We do**: Export updates from our LoroDoc since their vector
    GetUpdatesSince {
        layer_name: String,
        state_vector: Vec<u8>,
        reply: tokio::sync::oneshot::Sender<Result<Vec<u8>>>,
    },

    /// Replace layer entirely with snapshot (for SyncReset recovery)
    ///
    /// **Context**: User mode received SyncSnapshot after max resyncs exceeded
    /// **We do**: Replace local layer with authoritative snapshot from node
    /// **Invariant**: Node is source of truth for divergence resolution
    ReplaceLayer {
        layer_name: String,
        snapshot: Vec<u8>,
        reply: tokio::sync::oneshot::Sender<std::result::Result<(), String>>,
    },

    /// Flush dirty layers to storage
    Flush,

    /// Update peer's cached state vector (from PeerActor after SyncAccept/SyncAck)
    ///
    /// **Context**: PeerActor received confirmation of peer's state
    /// **We do**: Update in-memory vector cache (persistence via periodic flush)
    UpdatePeerVector {
        user_did: String,
        device_id: String,
        layer_name: String,
        state_vector: Vec<u8>,
    },

    /// Periodic reconciliation - check all subscribers for divergence
    ///
    /// **Context**: Timer fires every 30 seconds
    /// **We do**: Compare vectors, re-broadcast if diverged
    ReconcileWithPeers,

    /// Ensure a list layer exists (creates if needed)
    ///
    /// **Context**: Lua calls loro:list("name") - ensures layer exists
    /// **We do**: Create layer if needed, reply with success
    /// **Why**: Lua doesn't hold direct LoroList handle (stale after ReplaceLayer)
    EnsureLoroList {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Result<()>>,
    },

    /// Ensure a map layer exists (creates if needed)
    ///
    /// **Context**: Lua calls loro:map("name") - ensures layer exists
    /// **We do**: Create layer if needed, reply with success
    /// **Why**: Lua doesn't hold direct LoroMap handle (stale after ReplaceLayer)
    EnsureLoroMap {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Result<()>>,
    },

    /// Check if a layer exists (for get_list/get_map that return nil if missing)
    ///
    /// **Context**: Lua calls loro:get_list("name") - returns nil if missing
    LayerExists {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<bool>,
    },

    // Typed read operations (Lua → Scribe, avoids stale handles)

    /// Get item at index from a list layer
    ///
    /// **Context**: Lua calls list:get(index)
    /// **We do**: Read from current LoroDoc (never stale)
    ListGet {
        layer_name: String,
        index: usize,
        reply: tokio::sync::oneshot::Sender<Result<Option<serde_json::Value>>>,
    },

    /// Get list length
    ///
    /// **Context**: Lua calls list:length()
    ListLength {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Result<usize>>,
    },

    /// Get value by key from a map layer
    ///
    /// **Context**: Lua calls map:get(key)
    MapGet {
        layer_name: String,
        key: String,
        reply: tokio::sync::oneshot::Sender<Result<Option<serde_json::Value>>>,
    },

    /// Get map length
    ///
    /// **Context**: Lua calls map:length()
    MapLength {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Result<usize>>,
    },

    /// Get all keys from a map
    ///
    /// **Context**: Lua calls map:keys()
    MapKeys {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Result<Vec<String>>>,
    },

    /// List layers matching a pattern
    ///
    /// **Context**: Lua calls loro:list_layers("*:order")
    /// **We do**: Return layer names matching glob pattern
    ListLayers {
        pattern: String,
        reply: tokio::sync::oneshot::Sender<Vec<String>>,
    },

    /// Subscribe to all page updates (unified channel)
    ///
    /// **Context**: App runtime subscribes to receive ALL page updates
    /// **We do**: Store sender, forward PageUpdate events when they occur
    /// **Consumers**: UI/Lua callbacks, Broadcast to peers, Derivation engine - all filter as needed
    /// **Design**: Unified channel for layer changes, ephemeral data, and peer presence
    SubscribeToPageUpdates {
        tx: mpsc::Sender<PageUpdate>,
    },


    /// Get layer data as JSON value
    ///
    /// **Context**: Lua bindings need to read layer content
    /// **We do**: Export layer as serde_json::Value
    GetLayerData {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Result<serde_json::Value>>,
    },

    /// Get current snapshot for a layer (for testing/debugging)
    ///
    /// **Context**: Test wants to verify Scribe state without waiting for persistence
    /// **We do**: Export current snapshot and return via reply channel
    GetSnapshot {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Option<Vec<u8>>>,
    },

    /// Get layer data as JSON (for egui rendering)
    ///
    /// **Context**: egui window wants to read Loro data directly
    /// **We do**: Export layer content as JSON value
    GetLayerJson {
        layer_name: String,
        reply: tokio::sync::oneshot::Sender<Option<serde_json::Value>>,
    },

    /// Get all layers as JSON context (for egui rendering)
    ///
    /// **Context**: egui window wants full context for CEL evaluation
    /// **We do**: Export all layer contents as a single JSON object
    GetContext {
        reply: tokio::sync::oneshot::Sender<serde_json::Value>,
    },

    /// Execute a query and return results
    ///
    /// **Context**: HUML renderer needs filtered/sorted/paginated data
    /// **We do**: Execute query against layer, apply filter/sort/limit, return results
    Query {
        spec: QuerySpec,
        reply: tokio::sync::oneshot::Sender<Result<QueryResult>>,
    },

    /// Subscribe to query updates
    ///
    /// **Context**: HUML renderer wants incremental updates when query results change
    /// **We do**: Store subscription, send QueryDelta when underlying data changes
    SubscribeQuery {
        spec: QuerySpec,
        /// Channel to send deltas when results change
        delta_tx: mpsc::Sender<QueryDelta>,
    },

    /// Unsubscribe from query updates
    UnsubscribeQuery {
        query_id: String,
    },

    /// Update layer from JSON (for UI commits via CEL commit())
    ///
    /// **Context**: HUML renderer's CEL `commit()` returns JSON values to persist.
    /// **We do**: Update the layer at the given path, notify query subscribers.
    UpdateFromJson {
        layer_name: String,
        path: String,
        value: serde_json::Value,
        /// Optional reply for error handling
        reply: Option<tokio::sync::oneshot::Sender<Result<()>>>,
    },

    // Typed CRDT Operations (from template actions)

    /// Push item to a list (append)
    ///
    /// **Context**: Template `action: { messages: append({...}) }`
    /// **We do**: Layer.list_push, broadcast, notify subscribers
    ListPush {
        layer_name: String,
        path: String,
        item: serde_json::Value,
    },

    /// Insert item at index in a list
    ListInsert {
        layer_name: String,
        path: String,
        index: usize,
        item: serde_json::Value,
    },

    /// Delete item at index from a list
    ListDelete {
        layer_name: String,
        path: String,
        index: usize,
    },

    /// Insert/update key in a map
    ///
    /// **Context**: Template `action: { users: set("id", {...}) }`
    MapInsert {
        layer_name: String,
        path: String,
        key: String,
        value: serde_json::Value,
    },

    /// Delete key from a map
    MapDelete {
        layer_name: String,
        path: String,
        key: String,
    },

    /// Increment/decrement a counter
    ///
    /// **Context**: Template `action: { likes: increment(1) }`
    CounterInc {
        layer_name: String,
        path: String,
        amount: i64,
    },

    /// Create a dynamic layer (from Lua app)
    ///
    /// **Context**: Lua calls scribe:create_layer("channels/general/messages")
    /// **We do**: Validate schema exists in permit, generate path with our DID, create layer
    /// **We reply**: Full layer name (with page_id and DID prefix)
    CreateDynamicLayer {
        /// Schema key from dynamic_layer_schemas, e.g. "channels/{id}/messages"
        schema_key: String,
        /// User-chosen ID that fills the {id} in the schema, e.g. "general"
        layer_id: String,
        reply: tokio::sync::oneshot::Sender<std::result::Result<String, String>>,
    },

    /// Shutdown the actor
    Shutdown,

    // Ephemeral Events (from datagrams via PeerActor)

    /// Remote ephemeral data (from datagram via PeerActor)
    ///
    /// **Context**: Peer sent ephemeral data (cursor, typing, etc.) for this page
    /// **We do**: Forward to subscribed apps AND relay to other peers via ephemeral channels
    /// **Note**: Not persisted in CRDT - purely ephemeral
    /// **Design**: Protocol layer routes opaque bytes; app layer defines meaning
    RemoteEphemeral {
        /// Who sent this (from peer state, may be None if not authenticated)
        user_did: Option<String>,
        /// Device/connection ID of sender (for relay exclusion)
        device_id: Option<String>,
        /// Opaque payload - app defines format (JSON with type/x/y, etc.)
        payload: Vec<u8>,
    },

    /// Send ephemeral data to peers (from Lua)
    ///
    /// **Context**: Local user wants to broadcast ephemeral data (cursor, typing, etc.)
    /// **We do**: Forward via ephemeral broadcast channel to Courier
    /// **Design**: App layer provides opaque payload; protocol layer routes by page_id
    SendEphemeral {
        /// Opaque payload - app defines format (JSON with type/x/y, etc.)
        payload: Vec<u8>,
    },

    /// Send structured ephemeral with func name (permission-validated)
    ///
    /// **Context**: Local user wants to broadcast structured ephemeral (typing, cursor, etc.)
    /// **We do**: Validate func against our permit's ephemeral_funcs, then broadcast
    /// **Design**: Structured format allows permission control per-function
    SendStructuredEphemeral {
        /// Function name (validated against permit.ephemeral_funcs)
        func: String,
        /// Arguments (arbitrary JSON)
        args: serde_json::Value,
    },

    /// Remote structured ephemeral received (needs validation)
    ///
    /// **Context**: Peer sent structured ephemeral via datagram
    /// **We do**: Validate func against sender's permit, then emit to app subscribers
    RemoteStructuredEphemeral {
        /// Sender's DID
        from_did: String,
        /// Sender's device ID
        device_id: String,
        /// Function name (validated against sender's permit)
        func: String,
        /// Arguments
        args: serde_json::Value,
    },

    // Derivation Operations (via ScribeLuaRuntime)

    /// Rebuild a derived layer from all source layers
    ///
    /// **Context**: Called on startup or manual rebuild request
    /// **We do**: Clear derived layer, transform ALL entries from ALL matching sources
    RebuildDerived {
        target: String,
        reply: tokio::sync::oneshot::Sender<std::result::Result<usize, String>>,
    },

    /// Rebuild all derived layers (on startup)
    RebuildAllDerived {
        reply: tokio::sync::oneshot::Sender<std::result::Result<(), String>>,
    },

    /// Check if derivation is enabled on this Scribe
    ///
    /// **Context**: Lua bindings check before registering rules
    IsDerivationEnabled {
        reply: tokio::sync::oneshot::Sender<bool>,
    },

    /// Create an empty derived layer
    ///
    /// **Context**: When registering a derivation rule, create target layer
    CreateDerivedLayer {
        target_layer: String,
    },

    // App Refresh Operations

    /// Refresh app from filesystem (owner only)
    ///
    /// **Context**: Owner wants to reload app code from disk (development workflow)
    /// **We do**: Read files from app_dir, update app layer, commit (triggers broadcast)
    /// **Consumers**: UI Reload button, Debug socket command
    RefreshApp {
        app_name: String,
        app_dir: PathBuf,
        reply: tokio::sync::oneshot::Sender<std::result::Result<Vec<String>, String>>,
    },

    /// Get app files from in-memory layer
    ///
    /// **Context**: App restart needs current files from Scribe's in-memory layer
    /// **We do**: Extract files from app layer and return
    /// **Why**: Storage may be stale; Scribe has the latest synced content
    GetAppFiles {
        app_name: String,
        reply: tokio::sync::oneshot::Sender<std::result::Result<HashMap<String, String>, String>>,
    },

    /// Get subscriber count (for Lua peers:count() binding)
    ///
    /// **Context**: Node script wants to check if anyone is listening before broadcasting
    /// **We do**: Return count of current subscribers
    GetSubscriberCount {
        reply: tokio::sync::oneshot::Sender<usize>,
    },
}

