   430→/// Detect if a newly created layer matches a dynamic schema and emit permits
   431→///
   432→/// **Context**: Node receives a new layer from peer. If it matches a dynamic schema,
   433→/// prepare layer permits for all connected peers and emit SyncEvent::NewDynamicLayer.
   434→/// **Coordinator** distributes the permits to PeerActors → peers.
   435→#[instrument(skip(state), fields(page_id = %state.page_id, layer = %layer_name))]
   436→async fn emit_dynamic_layer_permits(
   437→    state: &ScribeState,
   438→    layer_name: &str,
   439→    from_peer: &(String, String),
   440→) {
   441→    // Only nodes issue permits (require permit_issuer + our_permit + sync_event_tx)
   442→    let Some(ref permit_issuer) = state.permit_issuer else { return; };
   443→    let Some(ref our_permit) = state.our_permit else { return; };
   444→    let Some(ref sync_event_tx) = state.sync_event_tx else { return; };
   445→
   446→    // Check if layer matches a dynamic schema
   447→    let Some((schema_key, schema, creator_did)) =
   448→        find_matching_dynamic_schema(our_permit, layer_name, &state.page_id) else { return; };
   449→
   450→    // Validate creator namespace: sender's DID must match DID in path
   451→    if from_peer.0 != creator_did {
   452→        warn!(
   453→            layer = %layer_name,
   454→            sender = %from_peer.0,
   455→            creator = %creator_did,
   456→            "Creator namespace mismatch — sender DID doesn't match path DID"
   457→        );
   458→        return;
   459→    }
   460→
   461→    // Mark the layer as dynamic
   462→    if let Some(unit) = state.units.get(layer_name) {
   463→        // Note: is_dynamic is pub so we'd need get_mut, but we can't mutate here.
   464→        // The flag is informational; permit issuance is the critical path.
   465→        let _ = unit;
   466→    }
   467→
   468→    // Collect connected peers with their roles
   469→    let connected_peers = collect_connected_peers_with_roles(state);
   470→
   471→    // Prepare layer permits
   472→    let full_layer_name = format!("{}/{}", state.page_id, layer_name);
   473→    match prepare_layer_permits(
   474→        permit_issuer.as_ref(),
   475→        &state.page_id,
   476→        &full_layer_name,
   477→        schema,
   478→        &creator_did,
   479→        &connected_peers,
   480→    ) {
   481→        Ok(permits) if !permits.is_empty() => {
   482→            info!(
   483→                layer = %layer_name,
   484→                schema = %schema_key,
   485→                creator = %creator_did,
   486→                permit_count = permits.len(),
   487→                "Prepared dynamic layer permits, emitting NewDynamicLayer"
   488→            );
   489→
   490→            // Add layer permits to node's SubscriberInfo so can_receive_layer() works
   491→            // for subsequent broadcasts. Without this, the node would prepare permits
   492→            // but never actually send the layer data to subscribers.
   493→            if let Ok(mut subs) = state.subscribers.write() {
   494→                for ((did, _device_id), info) in subs.iter_mut() {
   495→                    for (recipient_did, token) in &permits {
   496→                        if did == recipient_did {
   497→                            match gurkha::Permit::from_token(token) {
   498→                                Ok(permit) => {
   499→                                    info.add_layer_permit(permit);
   500→                                    debug!(
   501→                                        recipient = %did,
   502→                                        layer = %layer_name,
   503→                                        "Added layer permit to subscriber"
   504→                                    );
   505→                                }
   506→                                Err(e) => {
   507→                                    warn!(
   508→                                        recipient = %did,
   509→                                        error = %e,
   510→                                        "Failed to parse layer permit for subscriber"
   511→                                    );
   512→                                }
   513→                            }
   514→                        }
   515→                    }
   516→                }
   517→            }
   518→
   519→            let event = SyncEvent::NewDynamicLayer {
   520→                page_id: state.page_id.clone(),
   521→                layer_name: full_layer_name,
   522→                permits,
   523→            };
   524→
   525→            if let Err(e) = sync_event_tx.send(event).await {
   526→                error!(error = %e, "Failed to emit NewDynamicLayer event");
   527→            }
   528→        }
   529→        Ok(_) => {
   530→            debug!(layer = %layer_name, "No permits needed for dynamic layer");
   531→        }
   532→        Err(e) => {
   533→            error!(layer = %layer_name, error = %e, "Failed to prepare dynamic layer permits");
   534→        }
   535→    }
   536→}
   537→
   538→/// Collect connected peers with their roles from subscriber info
   539→///
   540→/// **Context**: Node needs (did, role) pairs for prepare_layer_permits
   541→fn collect_connected_peers_with_roles(state: &ScribeState) -> Vec<(String, String)> {
   542→    let mut peers = Vec::new();
   543→
   544→    if let Ok(subs) = state.subscribers.read() {
   545→        for ((did, _device_id), info) in subs.iter() {
   546→            let role = info.permit.relationship().unwrap_or("peer").to_string();
   547→            // Avoid duplicates (same DID, different devices)
   548→            if !peers.iter().any(|(d, _): &(String, String)| d == did) {
   549→                peers.push((did.clone(), role));
   550→            }
   551→        }
   552→    }
   553→
   554→    peers
   555→}
