     1→//! Dynamic Layer Storage Operations
     2→//!
     3→//! Three tables for the two-tier permit model:
     4→//! - **Layer permits**: per-peer per-dynamic-layer UCAN tokens
     5→//! - **Dynamic layer metadata**: tracks which layers are dynamic (for reconnect)
     6→//! - **Viewer layer consents**: per-viewer per-layer consent tokens
     7→
     8→use redb::{ReadableTable, ReadableDatabase};
     9→use crate::error::Result;
    10→use tracing::instrument;
    11→use super::{
    12→    RedbStore, LAYER_PERMITS, DYNAMIC_LAYER_META, VIEWER_LAYER_CONSENTS,
    13→};
    14→
    15→impl RedbStore {
    16→    // ── Layer Permit Operations ──────────────────────────────────────────
    17→    // Key: {page_id}/{user_did}/{layer_name} → permit token string
    18→    // Multiple permits per peer per page (one per dynamic layer)
    19→
    20→    /// Store a layer permit for a peer (additive).
    21→    ///
    22→    /// **Context**: Node detected new dynamic layer, issued permit for peer.
    23→    #[instrument(skip_all)]
    24→    pub fn store_layer_permit(
    25→        &self,
    26→        page_id: &str,
    27→        user_did: &str,
    28→        layer_name: &str,
    29→        permit_token: &str,
    30→    ) -> Result<()> {
    31→        let key = format!("{}/{}/{}", page_id, user_did, layer_name);
    32→        let write_txn = self.db.begin_write()?;
    33→        {
    34→            let mut table = write_txn.open_table(LAYER_PERMITS)?;
    35→            table.insert(key.as_str(), permit_token)?;
    36→        }
    37→        write_txn.commit()?;
    38→        Ok(())
    39→    }
    40→
    41→    /// Load all layer permits for a peer on a page.
    42→    ///
    43→    /// **Context**: Used during reconnect to determine which dynamic layers peer has access to.
    44→    /// **Returns**: Vec of (layer_name, permit_token) tuples.
    45→    #[instrument(skip_all)]
    46→    pub fn get_layer_permits(
    47→        &self,
    48→        page_id: &str,
    49→        user_did: &str,
    50→    ) -> Result<Vec<(String, String)>> {
    51→        let prefix = format!("{}/{}/", page_id, user_did);
    52→        let read_txn = self.db.begin_read()?;
    53→        let table = read_txn.open_table(LAYER_PERMITS)?;
    54→
    55→        let mut permits = Vec::new();
    56→        for result in table.range(prefix.as_str()..)? {
    57→            let (key, value) = result?;
    58→            let key_str = key.value();
    59→
    60→            if !key_str.starts_with(&prefix) {
    61→                break;
    62→            }
    63→
    64→            if let Some(layer_name) = key_str.strip_prefix(&prefix) {
    65→                permits.push((layer_name.to_string(), value.value().to_string()));
    66→            }
    67→        }
    68→        Ok(permits)
    69→    }
    70→
    71→    /// Remove a layer permit for a peer.
    72→    ///
    73→    /// **Context**: Called during revocation or cleanup.
    74→    #[instrument(skip_all)]
    75→    pub fn remove_layer_permit(
    76→        &self,
    77→        page_id: &str,
    78→        user_did: &str,
    79→        layer_name: &str,
    80→    ) -> Result<bool> {
    81→        let key = format!("{}/{}/{}", page_id, user_did, layer_name);
    82→        let write_txn = self.db.begin_write()?;
    83→        let removed = {
    84→            let mut table = write_txn.open_table(LAYER_PERMITS)?;
    85→            let result = table.remove(key.as_str())?.is_some();
    86→            result
    87→        };
    88→        write_txn.commit()?;
    89→        Ok(removed)
    90→    }
    91→
    92→    /// Check if a peer has a layer permit for a specific dynamic layer.
    93→    #[instrument(skip_all)]
    94→    pub fn has_layer_permit(
    95→        &self,
    96→        page_id: &str,
    97→        user_did: &str,
    98→        layer_name: &str,
    99→    ) -> Result<bool> {
   100→        let key = format!("{}/{}/{}", page_id, user_did, layer_name);
   101→        let read_txn = self.db.begin_read()?;
   102→        let table = read_txn.open_table(LAYER_PERMITS)?;
   103→        let result = table.get(key.as_str())?.is_some();
   104→        Ok(result)
   105→    }
   106→
   107→    // ── Dynamic Layer Metadata Operations ────────────────────────────────
   108→    // Key: {page_id}/{layer_name} → meta JSON bytes
   109→    // Tracks which layers are dynamic (schema, creator, grant type)
   110→
   111→    /// Record that a layer is dynamic.
   112→    ///
   113→    /// **Context**: Node detected new dynamic layer from peer sync.
   114→    /// Stores metadata for reconnect enumeration and permit recomputation.
   115→    #[instrument(skip_all)]
   116→    pub fn store_dynamic_layer_meta(
   117→        &self,
   118→        page_id: &str,
   119→        layer_name: &str,
   120→        meta_json: &[u8],
   121→    ) -> Result<()> {
