   338→                schema_key: schema_key.to_string(),
   339→                layer_id: layer_id.to_string(),
   340→                reply: tx,
   341→            })
   342→            .map_err(|e| format!("Failed to create dynamic layer: {}", e))?;
   343→        rpc(rx)
   344→    }
   345→
   346→    fn get_subscriber_count(&self) -> usize {
   347→        let (tx, rx) = oneshot::channel();
   348→        if self
   349→            .scribe_ref
   350→            .cast(ScribeMessage::GetSubscriberCount { reply: tx })
   351→            .is_err()
   352→        {
   353→            return 0;
   354→        }
   355→        let result = match tokio::runtime::Handle::try_current() {
   356→            Ok(handle) => tokio::task::block_in_place(|| handle.block_on(rx)),
   357→            Err(_) => futures::executor::block_on(rx),
   358→        };
   359→        result.unwrap_or(0)
   360→    }
   361→
   362→    fn send_ephemeral(&self, payload: Vec<u8>) -> Result<(), String> {
   363→        self.scribe_ref
   364→            .cast(ScribeMessage::SendEphemeral { payload })
   365→            .map_err(|e| format!("Failed to send ephemeral: {}", e))
   366→    }
   367→}
