     1→//! Multi-peer test runner
     2→//!
     3→//! Shared MockScribeState with N independent LuaRuntime instances.
     4→//! Simulates multiple users interacting with the same page.
     5→
     6→use std::path::Path;
     7→use std::sync::{Arc, Mutex};
     8→
     9→use lua_runtime::{MockScribeHandle, MockScribeState};
    10→
    11→use crate::runner::AppTestRunner;
    12→
    13→/// Role definition for a peer
    14→pub struct PeerRole {
    15→    pub did: String,
    16→    pub name: String,
    17→    pub role: String,
    18→}
    19→
    20→impl PeerRole {
    21→    pub fn new(did: &str, name: &str, role: &str) -> Self {
    22→        Self {
    23→            did: did.to_string(),
    24→            name: name.to_string(),
    25→            role: role.to_string(),
    26→        }
    27→    }
    28→}
    29→
    30→/// Multi-peer test runner
    31→///
    32→/// Shared MockScribeState across N runners — writes from one peer
    33→/// are immediately visible to others (no sync delay simulation).
    34→pub struct MultiPeerRunner {
    35→    peers: Vec<AppTestRunner>,
    36→    shared_state: Arc<Mutex<MockScribeState>>,
    37→}
    38→
    39→impl MultiPeerRunner {
    40→    /// Create from app directory with multiple peers
    41→    pub fn from_dir(
    42→        app_dir: &Path,
    43→        page_id: &str,
    44→        roles: &[PeerRole],
    45→    ) -> Result<Self, String> {
    46→        // Read manifest + lua code
    47→        let manifest_path = app_dir.join("manifest.json");
    48→        let manifest_str = std::fs::read_to_string(&manifest_path)
    49→            .map_err(|e| format!("Failed to read manifest.json: {}", e))?;
    50→        let manifest: serde_json::Value = serde_json::from_str(&manifest_str)
    51→            .map_err(|e| format!("Failed to parse manifest.json: {}", e))?;
    52→
    53→        let entry_logic = manifest
    54→            .get("entry_logic")
    55→            .and_then(|v| v.as_str())
    56→            .unwrap_or("app.lua");
    57→
    58→        let lua_path = app_dir.join(entry_logic);
    59→        let lua_code = std::fs::read_to_string(&lua_path)
    60→            .map_err(|e| format!("Failed to read {}: {}", entry_logic, e))?;
    61→
    62→        // Set package.path so require() finds .lua modules in the app directory
    63→        let app_dir_abs = app_dir.canonicalize()
    64→            .map_err(|e| format!("Failed to resolve app dir: {}", e))?;
    65→        let package_path_preamble = format!(
    66→            "package.path = '{}/?.lua;' .. package.path\n",
    67→            app_dir_abs.display()
    68→        );
    69→
    70→        let init_path = app_dir.join("init.lua");
    71→        let full_code = if init_path.exists() {
    72→            let init_code = std::fs::read_to_string(&init_path)
    73→                .map_err(|e| format!("Failed to read init.lua: {}", e))?;
    74→            format!("{}{}\n{}", package_path_preamble, init_code, lua_code)
    75→        } else {
    76→            format!("{}{}", package_path_preamble, lua_code)
    77→        };
    78→
    79→        let app_name = manifest
    80→            .get("name")
    81→            .and_then(|v| v.as_str())
    82→            .unwrap_or("test-app");
    83→
    84→        Self::from_code(&full_code, app_name, page_id, roles)
    85→    }
    86→
    87→    /// Create from raw Lua code with multiple peers
    88→    pub fn from_code(
    89→        lua_code: &str,
    90→        app_name: &str,
    91→        page_id: &str,
    92→        roles: &[PeerRole],
    93→    ) -> Result<Self, String> {
    94→        let shared_state = MockScribeHandle::shared_state();
    95→
    96→        // Set subscriber count to number of peers
    97→        shared_state.lock().unwrap().set_subscriber_count(roles.len());
    98→
    99→        let mut peers = Vec::with_capacity(roles.len());
   100→        for role in roles {
   101→            let runner = AppTestRunner::from_code_with_shared_state(
   102→                lua_code,
   103→                app_name,
   104→                page_id,
   105→                &role.role,
   106→                &role.did,
   107→                &role.name,
   108→                shared_state.clone(),
   109→            )?;
   110→            peers.push(runner);
   111→        }
   112→
   113→        Ok(Self {
   114→            peers,
   115→            shared_state,
   116→        })
   117→    }
   118→
   119→    /// Call on_init on all peers
   120→    pub fn init_all(&mut self) {
   121→        for peer in &mut self.peers {
   122→            peer.call_on_init();
   123→        }
   124→    }
   125→
   126→    /// Tick all peers once
   127→    pub fn tick_all(&mut self) {
   128→        for peer in &mut self.peers {
   129→            peer.tick();
   130→        }
   131→    }
   132→
   133→    /// Tick all peers N times
   134→    pub fn tick_all_n(&mut self, n: usize) {
   135→        for _ in 0..n {
   136→            for peer in &mut self.peers {
   137→                peer.tick();
   138→            }
   139→        }
   140→    }
   141→
   142→    /// Get peer by index
   143→    pub fn peer(&mut self, index: usize) -> &mut AppTestRunner {
   144→        &mut self.peers[index]
   145→    }
   146→
   147→    /// Get number of peers
   148→    pub fn peer_count(&self) -> usize {
   149→        self.peers.len()
   150→    }

