    15→/// Helper: get message count from the channels/general/messages map layer
    16→fn message_count(runner: &AppTestRunner) -> usize {
    17→    let data = runner.layer_data("channels/general/messages");
    18→    match data {
    19→        Some(obj) => obj.as_object().map(|m| m.len()).unwrap_or(0),
    20→        None => 0,
    21→    }
    22→}
    23→
    24→/// Helper: get all messages as a sorted-by-timestamp vec
    25→fn get_messages(runner: &AppTestRunner) -> Vec<serde_json::Value> {
    26→    let data = runner.layer_data("channels/general/messages");
    27→    match data {
    28→        Some(obj) => {
    29→            let map = obj.as_object().unwrap();
    30→            let mut msgs: Vec<serde_json::Value> = map.values().cloned().collect();
    31→            msgs.sort_by_key(|m| m["timestamp"].as_i64().unwrap_or(0));
    32→            msgs
    33→        }
    34→        None => vec![],
    35→    }
    36→}
