   201→
   202→    // Set reply state + draft text, then call on_submit (like pressing Enter)
   203→    runner.eval_sync(&format!("ui:set('replying_to_id', '{}')", msg_id)).unwrap();
   204→    runner.eval_sync("ui:set('replying_to_text', 'Original message')").unwrap();
   205→    runner.eval_sync("ui:set('draft_text', 'This is a reply')").unwrap();
