   222→#[test]
   223→fn test_chat_multi_peer() {
   224→    let mut multi = MultiPeerRunner::from_dir(
   225→        &chat_app_dir(),
   226→        "shared-page",
   227→        &[
   228→            PeerRole::new("did:key:alice", "Alice", "owner"),
   229→            PeerRole::new("did:key:bob", "Bob", "viewer"),
   230→        ],
   231→    )
   232→    .unwrap();
   233→
   234→    multi.init_all();
   235→
   236→    // Alice sends a message
   237→    multi
   238→        .peer(0)
   239→        .fire_callback("send_message", vec![serde_json::json!("Hello from Alice")])
   240→        .unwrap();
   241→    multi.tick_all();
   242→
   243→    // Bob can see Alice's message (shared MockScribeState)
   244→    let messages = get_messages(multi.peer(1));
   245→    assert_eq!(messages.len(), 1);
   246→    assert_eq!(messages[0]["text"], "Hello from Alice");
   247→    assert_eq!(messages[0]["sender_name"], "Alice");
   248→
   249→    // Bob replies
   250→    multi
   251→        .peer(1)
   252→        .fire_callback("send_message", vec![serde_json::json!("Hi Alice!")])
   253→        .unwrap();
   254→    multi.tick_all();
   255→
   256→    // Both see 2 messages
   257→    assert_eq!(message_count(multi.peer(0)), 2);
   258→    assert_eq!(message_count(multi.peer(1)), 2);
   259→
   260→    // Verify Bob's message exists
   261→    let messages = get_messages(multi.peer(1));
   262→    let bob_msg = messages.iter().find(|m| m["sender_name"] == "Bob").unwrap();
   263→    assert_eq!(bob_msg["text"], "Hi Alice!");
   264→}
