/// Handle AddLayerAccess message
///
/// **Context**: Lua app calls scribe:add_layer_access(layer_name, did)
/// **We do**: Validate capability, store participant, issue permit if peer is subscribed
pub async fn handle_add_layer_access(
    state: &ScribeState,
    layer_name: &str,
    did: &str,
) -> Result<Vec<(String, String)>, String> {
    // 1. Check our permit has manage_layer_access capability
    let permit = state.our_permit.as_ref().ok_or("No permit")?;
    if !permit.can_manage_layer_access() {
        return Err("No manage_layer_access capability".into());
    }

    // 2. Store participant via PermitIssuer
    let issuer = state.permit_issuer.as_ref().ok_or("No permit issuer (not node mode)")?;
    let mut participants = issuer.load_layer_participants(layer_name)
        .map_err(|e| e.to_string())?;
    if !participants.contains(&did.to_string()) {
        participants.push(did.to_string());
        issuer.store_layer_participants(layer_name, &participants)
            .map_err(|e| e.to_string())?;
    }

    // 3. If peer is currently subscribed, issue permit immediately
    let mut new_permits = Vec::new();
    if let Ok(subs) = state.subscribers.read() {
        for ((sub_did, _), _info) in subs.iter() {
            if sub_did == did {
                // Find schema for this layer to get permissions
                let full_name = if layer_name.starts_with(&state.page_id) {
                    layer_name.to_string()
                } else {
                    format!("{}/{}", state.page_id, layer_name)
                };

                if let Some((_schema_key, schema, _creator)) =
                    find_matching_dynamic_schema(permit, &full_name, &state.page_id)
                {
                    let config = schema.permissions.clone().unwrap_or(
                        gurkha::LayerConfig { sync: true, write: true, layer_type: None }
                    );
                    match issuer.issue_layer_permit(did, &full_name, config) {
                        Ok((token, _cid)) => {
                            new_permits.push((did.to_string(), token));
                        }
                        Err(e) => {
                            warn!(error = %e, "Failed to issue layer permit for new participant");
                        }
                    }
                }
                break;
            }
        }
    }

    // 4. Add layer permits to subscriber info (if issued)
    if !new_permits.is_empty() {
        if let Ok(mut subs) = state.subscribers.write() {
            for ((sub_did, _), info) in subs.iter_mut() {
                for (recipient, token) in &new_permits {
                    if sub_did == recipient {
                        if let Ok(p) = gurkha::Permit::from_token(token) {
                            info.add_layer_permit(p);
                        }
                    }
                }
            }
        }
    }

    Ok(new_permits)
}
```

