```lua
local M = {}

local page_id, my_did, my_name
local dms_meta_layer = nil
local active_dm = nil
local messages_layer = nil
local on_dm_switch = nil

function M.init(pid, did, name, callback)
    page_id = pid
    my_did = did
    my_name = name
    on_dm_switch = callback
    dms_meta_layer = scribe:map(page_id .. "/dms_meta")
    M.refresh_dm_list()
end

-- Create a DM with a specific user
-- 1. create_layer with explicit schema
-- 2. add_layer_access for the other user
-- 3. Store DM metadata so both sides see it in sidebar
function M.create_dm(other_did, other_name)
    -- Generate a stable DM id from sorted DIDs (so both sides get same id)
    local dids = { my_did, other_did }
    table.sort(dids)
    local dm_id = dids[1]:sub(-8) .. "-" .. dids[2]:sub(-8)

    -- Check if already exists
    local existing = dms_meta_layer and dms_meta_layer:get(dm_id)
    if existing then
        M.switch_dm(dm_id)
        return
    end

    -- Create explicit dynamic layer
    local result = scribe:create_layer("dms/{id}/messages", dm_id)
    local layer_path = nil
    if result and result.layer_name then
        local prefix = page_id .. "/"
        if result.layer_name:sub(1, #prefix) == prefix then
            layer_path = result.layer_name:sub(#prefix + 1)
        else
            layer_path = result.layer_name
        end
    end

    -- Grant access to the other user (generic API — node handles permits)
    scribe:add_layer_access(result.layer_name, other_did)

    -- Store DM metadata (visible to both via dms_meta sync)
    dms_meta_layer:set(dm_id, {
        id = dm_id,
        participants = { my_did, other_did },
        participant_names = { [my_did] = my_name, [other_did] = other_name or other_did:sub(-8) },
        created_by = my_did,
        created_at = os.time(),
        layer_path = layer_path,
    })

    M.refresh_dm_list()
    M.switch_dm(dm_id)
end

function M.switch_dm(dm_id)
    active_dm = dm_id
    local meta = dms_meta_layer and dms_meta_layer:get(dm_id)
    if not meta or not meta.layer_path then return end

    messages_layer = scribe:map(page_id .. "/" .. meta.layer_path)

    -- Get display name (the OTHER person's name)
    local display = dm_id
    if meta.participants then
        for _, did in ipairs(meta.participants) do
            if did ~= my_did then
                display = (meta.participant_names and meta.participant_names[did])
                    or did:sub(-8)
                break
            end
        end
    end

    ui:set("active_dm", dm_id)
    ui:set("active_dm_name", display)

    if on_dm_switch then
        on_dm_switch(dm_id, meta.layer_path)
    end
end

function M.refresh_dm_list()
    if not dms_meta_layer then return end

    local dm_list = {}
    local keys = dms_meta_layer:keys()
    if keys then
        for _, key in ipairs(keys) do
            local meta = dms_meta_layer:get(key)
            if meta and meta.participants then
                -- Only show DMs I'm a participant in
                local im_in = false
                local other_name = key
                for _, did in ipairs(meta.participants) do
                    if did == my_did then im_in = true end
                    if did ~= my_did then
                        other_name = (meta.participant_names and meta.participant_names[did])
                            or did:sub(-8)
                    end
                end
                if im_in then
                    table.insert(dm_list, {
                        id = meta.id or key,
                        name = other_name,
                        is_active = (meta.id or key) == active_dm,
                    })
                end
            end
        end
    end

    ui:set("dms", dm_list)
end

function M.get_active_dm() return active_dm end
function M.get_messages_layer() return messages_layer end
function M.get_dms_meta_layer() return dms_meta_layer end

return M
```

