### Step 16: E2E test — `test_dm.py`

**File**: `e2e_tests/test_dm.py`

Tests two scenarios:

**Test 1: 1:1 DM** — Alice creates DM with Bob, sends message. Bob receives, Carol does NOT.

**Test 2: Private channel** — Alice creates private channel with Bob and Carol, sends message. Both receive.

```python
with AppTestScenario(
    name="dm_test",
    app_path=str(DEMOS_APP),
    peers={
        "alice": {"role": "owner", "app": "Group Chat"},
        "bob": {"role": "viewer", "app": "Group Chat"},
        "carol": {"role": "viewer", "app": "Group Chat"},
    },
    **args,
) as s:
    alice, bob, carol = s.peer("alice"), s.peer("bob"), s.peer("carol")

    # --- Test 1: 1:1 DM ---
    bob_did = bob.eval('return scribe:my_did()')
    alice.eval(f'create_dm("{bob_did}", "Bob")')
    alice.eval('send_dm_message("Private to Bob")')

    bob.wait_for(lambda: bob.eval("return get_dm_message_count()") >= 1, desc="Bob DM")

    time.sleep(3)
    assert carol.eval("return get_dm_message_count()") == 0, "Carol should not see 1:1 DM"

    # --- Test 2: Private channel ---
    carol_did = carol.eval('return scribe:my_did()')
    alice.eval(f'create_private_channel("secret-ops", {{{{did="{bob_did}", name="Bob"}}, {{did="{carol_did}", name="Carol"}}}})')
    alice.eval('send_dm_message("Hello secret team")')

    bob.wait_for(lambda: bob.eval("return get_dm_message_count()") >= 2, desc="Bob private ch")
    carol.wait_for(lambda: carol.eval("return get_dm_message_count()") >= 1, desc="Carol private ch")

    print("[SUCCESS] DM + Private Channel E2E Test Passed!")
```

